INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mungus451/starlight_v2/Test Commander', 'community', 'mungus451', 'starlight_v2', 'mungus451/starlight_v2', 'Test Commander', 0, 0, 26, '2026-03-08T01:57:15.601Z', '2026-03-08T02:14:51.160Z', '4406f56412956c1a153af7a2f7610b0c91ea0bcf129b2db5c856b40e7cd79324', '{"id":"mungus451/starlight_v2/Test Commander","name":"Test Commander","description":{"en":"Test Commander is an AI Agent Skill that provides procedural guidance for writing unit tests in Laravel. It enforces mocking standards for Config and Repositories and provides specific assertion helpers for ServiceResponse objects, benefiting Laravel developers implementing TDD."},"seo":{"title":{"en":"Test Commander: Laravel Unit Testing Best Practices | AI ..."},"description":{"en":"Master Laravel unit testing with Test Commander. This AI Agent Skill enforces mocking standards for Config and Repositories, provides ServiceResponse asserti..."},"definition":{"en":"Test Commander is an AI Agent Skill designed for Laravel developers. It provides a structured framework for writing unit tests by enforcing specific mocking protocols for configuration and repositories and offering dedicated assertion methods for service responses."},"features":{"en":["Enforces test base class inheritance from `Tests\\Unit\\TestCase`","Provides Config mocking via `$this->mockConfig->shouldReceive(''get'')`","Mocks repositories to return Entities instead of raw arrays","Includes ServiceResponse assertion helpers `assertServiceSuccess` and `assertServiceFailure`"]},"keywords":{"en":["how to use Test Commander Laravel","Test Commander vs PHPUnit","Test Commander setup guide","Laravel unit testing best practices","mock Laravel config in tests","mock Laravel repository","assertServiceSuccess method","install Test Commander AI agent","what is Test Commander AI skill"]}},"owner":"mungus451","repo":"starlight_v2","repoPath":"mungus451/starlight_v2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.601Z","topics":[],"category":"community","skillMd":{"name":"Test Commander","description":"Automates the creation of strict PHPUnit tests. It specializes in mocking Repositories/Configs using `Mockery` and validating `App\\Core\\ServiceResponse` objects. It ensures no feature is considered complete without a test. Use this skill when a new **Service Method** is created or a bug is reported.","bodyPreview":"# Procedural Guidance\n### 1. The Mockery Standard\n*   **Base Class:** All tests must extend `Tests\\Unit\\TestCase`.\n*   **Config Mocking:** Use `$this->mockConfig->shouldReceive(''get'')->with(''key'')->andReturn(...)`.\n*   **Repo Mocking:** Mock repositories to return Entities, never raw arrays (unless it''s a legacy repo).\n\n### 2. The Assertion Protocol\n*   **ServiceResponse:** Use helper methods `$this->assertServiceSuccess($response)` and `$this->assertServiceFailure($response)`.\n*   **Transaction","body":"# Procedural Guidance\n### 1. The Mockery Standard\n*   **Base Class:** All tests must extend `Tests\\Unit\\TestCase`.\n*   **Config Mocking:** Use `$this->mockConfig->shouldReceive(''get'')->with(''key'')->andReturn(...)`.\n*   **Repo Mocking:** Mock repositories to return Entities, never raw arrays (unless it''s a legacy repo).\n\n### 2. The Assertion Protocol\n*   **ServiceResponse:** Use helper methods `$this->assertServiceSuccess($response)` and `$this->assertServiceFailure($response)`.\n*   **Transactions:** Ensure the Service test mocks `$db->beginTransaction()`, `commit()`, and `rollBack()`.\n\n### 3. Integration vs Unit\n*   **Unit:** Default. Mock everything. Place in `tests/Unit/Services/`.\n*   **Integration:** Only if DB interactions are complex. Must use the `try { $db->beginTransaction(); ... } finally { $db->rollBack(); }` pattern found in `tests/Integration/`.\n\n### 4. Output Format\nProvide the full, drop-in PHP file ending in `Test.php`."},"lastSynced":"2026-03-08T02:14:51.160Z","agentAnalysis":{"suitability":{"en":"Perfect for Laravel Development Agents needing standardized unit testing procedures with Mockery and assertion helpers.","zh":"非常适合需要标准化单元测试程序的Laravel开发代理，包括Mockery和断言辅助工具。","ja":"Laravel開発エージェントが標準化されたユニットテスト手順を必要とする場合に最適です。Mockeryとアサーションヘルパーを使用します。","ko":"표준화된 유닛 테스트 절차 및 Mockery 및 assertion 헬퍼가 필요한 Laravel 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de Laravel que necesitan procedimientos de pruebas unitarias estandarizadas con Mockery y ayudantes de aserción.","fr":"Parfait pour les agents de développement Laravel qui ont besoin de procédures de tests unitaires standardisées avec Mockery et des aides d''assertion.","de":"Perfekt für Laravel-Entwicklungsagenten, die standardisierte Einheitentestverfahren mit Mockery und Behauptungshilfen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Laravel que necessitam de procedimentos de teste unitário padronizados com Mockery e ajudantes de afirmação.","ru":"Идеально подходит для агентов разработки Laravel, которым необходимы стандартизированные процедуры модульного тестирования с Mockery и помощниками утверждения.","ar":"مثالي للوكلاء النمطية لارافيل الذين يحتاجون إلى إجراءات اختبار الوحدة المعيارية مع Mockery ومساعدي التحقق."},"recommendation":{"en":"Empowers agents to enforce mocking standards for Config and Repositories, and provides specific assertion helpers for ServiceResponse objects using Laravel''s testing framework, ensuring consistent test-driven development with TDD principles and Mockery''s mocking capabilities.","zh":"赋予代理人执行Config和存储库的模拟标准的能力，并为使用Laravel测试框架的ServiceResponse对象提供特定的断言辅助工具，确保遵循TDD原则和Mockery的模拟能力的驱动开发。","ja":"エージェントがConfigとリポジトリのモッキング標準を適用できるようにし、Laravelのテストフレームワークを使用するServiceResponseオブジェクトのための特定のアサーションヘルパーを提供することで、TDDの原則とMockeryのモッキング機能を使用した一貫したテスト駆動開発を可能にします。","ko":"에이전트가 Config 및 저장소의 모킹 표준을 적용할 수 있도록 하며 Laravel의 테스트 프레임워크를 사용하는 ServiceResponse 개체에 대한 특정 assertion 헬퍼를 제공하여 TDD 원칙 및 Mockery의 모킹 기능을 사용한 일관된 테스트 주도 개발을 보장합니다.","es":"Habilita a los agentes a aplicar estándares de simulación para Config y Repositories, y proporciona ayudantes de aserción específicos para objetos ServiceResponse utilizando el marco de pruebas de Laravel, garantizando un desarrollo impulsado por pruebas coherente con los principios de TDD y las capacidades de simulación de Mockery.","fr":"Permet aux agents d''appliquer des normes de mocking pour Config et Repositories, et fournit des aides d''assertion spécifiques pour les objets ServiceResponse en utilisant le framework de test de Laravel, garantissant un développement piloté par les tests cohérent avec les principes de TDD et les capacités de mocking de Mockery.","de":"Ermächtigt die Agenten, Mocking-Standards für Config und Repositories durchzusetzen und bietet spezifische Behauptungshilfen für ServiceResponse-Objekte unter Verwendung von Laravels Testframework, um ein konsistentes testgetriebenes Entwicklung mit TDD-Prinzipien und Mockerys Mocking-Funktionen sicherzustellen.","pt":"Habilita os agentes a impor padrões de simulação para Config e Repositórios, e fornece ajudantes de afirmação específicos para objetos ServiceResponse usando o framework de teste do Laravel, garantindo desenvolvimento orientado a testes consistentes com princípios TDD e capacidades de simulação do Mockery.","ru":"Наделяет агентов возможностью обеспечивать соблюдение стандартов имитации для Config и Repositories, и предоставляет специальные помощники утверждения для объектов ServiceResponse с использованием тестового фреймворка Laravel, обеспечивая последовательное разработку, управляемую тестами, на основе принципов TDD и возможностей имитации Mockery.","ar":"يمنح الوكلاء القدرة على فرض معايير المحاكاة للمكونات Config والRepositories ، ويوفر مساعدين للتحقق المحدد للكائنات ServiceResponse باستخدام إطار الاختبار في لارافيل، مما يضمن تنمية متسقة قادرة على الاختبار باستخدام مبادئ TDD وقدرات المحاكاة للموكاري."},"useCases":{"en":["Enforcing Config mocking standards with $this->mockConfig->shouldReceive(''get'')","Generating ServiceResponse assertions with $this->assertServiceSuccess($response) and $this->assertServiceFailure($response)","Standardizing Repository mocking to return Entities instead of raw arrays"],"zh":["执行Config模拟标准，使用$this->mockConfig->shouldReceive(''get'')","生成ServiceResponse断言，使用$this->assertServiceSuccess($response)和$this->assertServiceFailure($response)","标准化存储库模拟以返回实体而不是原始数组"],"ja":["Configのモッキング標準を適用する、$this->mockConfig->shouldReceive(''get'')を使用","ServiceResponseのアサーションを生成する、$this->assertServiceSuccess($response)と$this->assertServiceFailure($response)を使用","リポジトリのモッキングを標準化する、エンティティを返すようにする、生の配列ではなく"],"ko":["Config 모킹 표준 적용, $this->mockConfig->shouldReceive(''get'') 사용","ServiceResponse assertion 생성, $this->assertServiceSuccess($response) 및 $this->assertServiceFailure($response) 사용","저장소 모킹 표준화, 엔티티 반환, 원시 배열이 아닌"],"es":["Aplicar estándares de simulación de Config con $this->mockConfig->shouldReceive(''get'')","Generar aserciones de ServiceResponse con $this->assertServiceSuccess($response) y $this->assertServiceFailure($response)","Establecer estándares de simulación de Repositorio para devolver Entidades en lugar de matrices crudas"],"fr":["Appliquer des normes de mocking de Config avec $this->mockConfig->shouldReceive(''get'')","Générer des assertions de ServiceResponse avec $this->assertServiceSuccess($response) et $this->assertServiceFailure($response)","Normaliser le mocking de Repository pour renvoyer des Entités au lieu de tableaux bruts"],"de":["Durchsetzen von Mocking-Standards für Config mit $this->mockConfig->shouldReceive(''get'')","Generieren von ServiceResponse-Behauptungen mit $this->assertServiceSuccess($response) und $this->assertServiceFailure($response)","Standardisieren des Repository-Mockings, um Entitäten anstelle von rohen Arrays zurückzugeben"],"pt":["Impor padrões de simulação Config com $this->mockConfig->shouldReceive(''get'')","Gerar afirmações ServiceResponse com $this->assertServiceSuccess($response) e $this->assertServiceFailure($response)","Padronizar simulação de Repositório para retornar Entidades em vez de matrizes brutas"],"ru":["Обеспечить соблюдение стандартов имитации Config с помощью $this->mockConfig->shouldReceive(''get'')","Генерировать утверждения ServiceResponse с помощью $this->assertServiceSuccess($response) и $this->assertServiceFailure($response)","Стандартизировать имитацию Repositories для возврата сущностей вместо сырых массивов"],"ar":["فرض معايير المحاكاة Config باستخدام $this->mockConfig->shouldReceive(''get'')","توليد تحقق ServiceResponse باستخدام $this->assertServiceSuccess($response) و $this->assertServiceFailure($response)","توحيد محاكاة Repository لإرجاع الكيانات بدلاً من صفائف غير مُعالجة"]},"limitations":{"en":["Requires Laravel development environment","Limited to unit testing with PHPUnit and Mockery","Laravel-specific, may not be compatible with other PHP frameworks"],"zh":["需要Laravel开发环境","仅限于使用PHPUnit和Mockery的单元测试","特定于Laravel，可能与其他PHP框架不兼容"],"ja":["Laravel開発環境が必要","PHPUnitとMockeryを使用したユニットテストのみに限定","Laravel専用であり、他のPHPフレームワークと互換性がない可能性がある"],"ko":["Laravel 개발 환경 필요","PHPUnit 및 Mockery를 사용한 유닛 테스트만 제한","Laravel 전용으로, 다른 PHP 프레임워크와 호환되지 않을 수 있음"],"es":["Requiere un entorno de desarrollo de Laravel","Limitado a pruebas unitarias con PHPUnit y Mockery","Específico de Laravel, puede que no sea compatible con otros frameworks PHP"],"fr":["Nécessite un environnement de développement Laravel","Limité aux tests unitaires avec PHPUnit et Mockery","Spécifique à Laravel, peut ne pas être compatible avec d''autres frameworks PHP"],"de":["Benötigt eine Laravel-Entwicklungsumgebung","Begrenzt auf Einheitentests mit PHPUnit und Mockery","Laravel-spezifisch, möglicherweise nicht kompatibel mit anderen PHP-Frameworks"],"pt":["Requer ambiente de desenvolvimento Laravel","Limitado a testes unitários com PHPUnit e Mockery","Específico do Laravel, pode não ser compatível com outros frameworks PHP"],"ru":["Требует среды разработки Laravel","Ограничен модульным тестированием с помощью PHPUnit и Mockery","Специфичен для Laravel, может быть несовместим с другими фреймворками PHP"],"ar":["يتطلب بيئة تطوير لارافيل","محدود بالاختبارات الوحدوية مع PHPUnit و Mockery","ملائم لارافيل فقط، قد لا يكون متوافقًا مع إطارات عمل PHP الأخرى"]},"version":4},"contentHash":"4406f56412956c1a153af7a2f7610b0c91ea0bcf129b2db5c856b40e7cd79324","qualityScore":26}');
