INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mungus451/starlight_v2/Test Commander', 'Test Commander', 'mungus451', 'starlight_v2', 'community', 'Test Commander mungus451 starlight_v2 community Test Commander is an AI Agent Skill that provides procedural guidance for writing unit tests in Laravel. It enforces mocking standards for Config and Repositories and provides specific assertion helpers for ServiceResponse objects, benefiting Laravel developers implementing TDD. how to use Test Commander Laravel Test Commander vs PHPUnit Test Commander setup guide Laravel unit testing best practices mock Laravel config in tests mock Laravel repository assertServiceSuccess method install Test Commander AI agent what is Test Commander AI skill Enforces test base class inheritance from `Tests\Unit\TestCase` Provides Config mocking via `$this->mockConfig->shouldReceive(''get'')` Mocks repositories to return Entities instead of raw arrays Includes ServiceResponse assertion helpers `assertServiceSuccess` and `assertServiceFailure` Test Commander is an AI Agent Skill designed for Laravel developers. It provides a structured framework for writing unit tests by enforcing specific mocking protocols for configuration and repositories and offering dedicated assertion methods for service responses.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RafaellsAlmeida/lifetrek/bmad-agent-cis-storyteller', 'community', 'RafaellsAlmeida', 'lifetrek', 'RafaellsAlmeida/lifetrek', 'bmad-agent-cis-storyteller', 0, 0, 26, '2026-03-05T19:36:44Z', '2026-03-08T02:16:14.246Z', '745c01f0b24f8d4dd95e7fde8daf5946ff8cf64373f17b95d33635a67e5c4a75', '{"id":"RafaellsAlmeida/lifetrek/bmad-agent-cis-storyteller","name":"bmad-agent-cis-storyteller","description":{"en":"The bmad-agent-cis-storyteller skill provides a medical manufacturing platform with AI-assisted content, operations, and sales workflows, benefiting developers and manufacturers. It utilizes React and AI automation for efficient processes.","zh":"bmad-agent-cis-storyteller是一个医疗制造平台，具有AI辅助内容、操作和销售工作流程，使用React等技术","ja":"bmad-agent-cis-storytellerは、AIエージェントを活用したメディカル製造プラットフォームで、Reactなどの技術を使用しています","ko":"bmad-agent-cis-storyteller는 AI 에이전트를 활용한 의료 제조 플랫폼으로 React 등의 기술을 사용합니다","es":"bmad-agent-cis-storyteller es una plataforma de manufactura médica con flujos de trabajo asistidos por AI para contenido, operaciones y ventas. Se basa en React para una integración fluida.","fr":"bmad-agent-cis-storyteller est une plate-forme de fabrication médicale avec des flux de travail assistés par l''IA pour le contenu, les opérations et les ventes. Elle repose sur React pour une intégration fluide.","de":"bmad-agent-cis-storyteller ist eine Plattform für die medizinische Fertigung mit AI-gestützten Arbeitsabläufen für Inhalt, Betrieb und Vertrieb. Sie basiert auf React für eine nahtlose Integration.","pt":"O bmad-agent-cis-storyteller é uma plataforma de manufatura médica com fluxos de trabalho assistidos por IA para conteúdo, operações e vendas, construída com React","ru":"bmad-agent-cis-storyteller - медицинская производственная платформа с потоками контента, операций и продаж, автоматизированными при помощи ИИ, построенная на основе React","ar":"العامل bmad-agent-cis-storyteller هو منصة تصنيع طبية مع تدفقات عمل محتوى وتشغيل ومبيعات مدعومة بالذكاء الاصطناعي، مبنية باستخدام React"},"seo":{"title":{"en":"bmad-agent-cis-storyteller: AI-Assisted Medical Manufactu...","zh":"bmad-agent-cis-storyteller AI工具集成指南","ja":"bmad-agent-cis-storyteller AIエージェントのセットアップガイド","ko":"bmad-agent-cis-storyteller AI 에이전트 설정 가이드","es":"Guía de configuración de bmad-agent-cis-storyteller para ...","fr":"Guide de mise en œuvre de bmad-agent-cis-storyteller pour...","de":"Einrichtungsleitfaden für bmad-agent-cis-storyteller in d...","pt":"Guia de Configuração do bmad-agent-cis-storyteller para P...","ru":"Настройка bmad-agent-cis-storyteller для медицинских прои...","ar":"دليل إعداد العامل bmad-agent-cis-storyteller لأنظمة التصن..."},"description":{"en":"Unlock the full potential of bmad-agent-cis-storyteller with our expert guide. Learn how to activate and utilize this AI-assisted medical manufacturing platf...","zh":"了解bmad-agent-cis-storyteller的技术能力，包括AI辅助内容、操作和销售工作流程，使用React等技术","ja":"bmad-agent-cis-storytellerの技術的な能力を学び、AIエージェントを活用してメディカル製造プラットフォームを最適化する","ko":"bmad-agent-cis-storyteller의 기술적 능력을 익히고 AI 도구를 사용하여 의료 제조 플랫폼을 최적화하는 방법을 알아보세요","es":"Descubre cómo implementar bmad-agent-cis-storyteller para automatizar flujos de trabajo en la manufactura médica con AI y React","fr":"Découvrez comment mettre en œuvre bmad-agent-cis-storyteller pour automatiser les flux de travail dans la fabrication médicale avec l''IA et React","de":"Erfahren Sie, wie Sie bmad-agent-cis-storyteller implementieren, um Arbeitsabläufe in der medizinischen Fertigung mit KI und React zu automatisieren","pt":"Aprenda a configurar o bmad-agent-cis-storyteller para automatizar fluxos de trabalho de conteúdo, operações e vendas em plataformas de manufatura médica","ru":"Узнайте, как настроить bmad-agent-cis-storyteller для автоматизации потоков контента, операций и продаж на медицинских производственных платформах","ar":"تعلم كيفية إعداد ال