INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ebarronh/buildathon-mar-26/bmad-agent-cis-storyteller', 'bmad-agent-cis-storyteller', 'ebarronh', 'buildathon-mar-26', 'community', 'bmad-agent-cis-storyteller ebarronh buildathon-mar-26 community The bmad-agent-cis-storyteller skill enables developers to embody a specific agent persona and follow activation instructions for AI agents, ensuring precise execution and character consistency. bmad-agent-cis-storyteller 是一个需要按照特定指令加载和执行的 AI 代理 bmad-agent-cis-storyteller は、特定の手順に従ってロードおよび実行する必要がある AI エージェントです bmad-agent-cis-storyteller 는 특정 지침에 따라 로드하고 실행해야 하는 AI 에이전트입니다 El agente bmad-agent-cis-storyteller es una herramienta de inteligencia artificial que requiere una configuración precisa. Sigue nuestra guía para dominar su uso. L''agent bmad-agent-cis-storyteller est un outil d''intelligence artificielle qui nécessite une configuration précise. Suivez notre guide pour maîtriser son utilisation. Der KI-Agent bmad-agent-cis-storyteller ist ein Tool, das eine präzise Konfiguration erfordert. Folgen Sie unserer Anleitung, um seine Verwendung zu meistern. O bmad-agent-cis-storyteller é um agente de IA que requer configuração precisa. Siga nossas instruções para carregar o arquivo do agente e executar os passos de ativação. ИИ Агент bmad-agent-cis-storyteller требует точной настройки. Следуйте нашим инструкциям, чтобы загрузить файл агента и выполнить шаги активации. العامل الذكي bmad-agent-cis-storyteller يتطلب ضبطًا دقيقًا. اتبع إرشاداتنا لتحميل ملف العامل والتشغيل خطوات التنشيط. how to use bmad-agent-cis-storyteller bmad-agent-cis-storyteller setup guide bmad-agent-cis-storyteller alternative what is bmad-agent-cis-storyteller bmad-agent-cis-storyteller install bmad-agent-cis-storyteller vs other AI agents bmad-agent-cis-storyteller AI 代理 AI 工具 CLI 命令 agent 文件 激活步骤 Loads full agent file from {project-root}/_bmad/cis/agents/storyteller/storyteller.md Executes ALL activation steps exactly as written in the agent file Follows the agent''s persona and menu system with precision Requires strict adherence to activation instructions with CRITICAL="TRUE" flag Reads entire contents of the agent file for complete persona and menu information bmad-agent-cis-storyteller is a specialized AI agent skill that requires strict adherence to activation instructions and persona embodiment');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ever-sync/stravox/bmad-cis-design-thinking', 'community', 'ever-sync', 'stravox', 'ever-sync/stravox', 'bmad-cis-design-thinking', 0, 0, 26, '2026-03-07T21:08:00Z', '2026-03-08T02:18:50.046Z', 'c6e428b9ccd21661d9b539f723469faaba21d3a742240ad031fa82f6f7dcb64e', '{"id":"ever-sync/stravox/bmad-cis-design-thinking","name":"bmad-cis-design-thinking","description":{"en":"The bmad-cis-design-thinking skill enables AI agents to execute specific workflows by loading and reading workflow.xml and workflow.yaml files. This skill benefits developers working with AI workflow configurations.","zh":"bmad-cis-design-thinking 设计思维工作流需要加载 workflow.xml 和读取 workflow.yaml 配置文件","ja":"bmad-cis-design-thinking デザイン思考ワークフローでは、workflow.xml をロードし、workflow.yaml 構成ファイルを読み取ります","ko":"bmad-cis-design-thinking 디자인 사고 워크플로우는 workflow.xml을 로드하고 workflow.yaml 구성 파일을 읽습니다","es":"bmad-cis-design-thinking es un skill que permite mejorar el pensamiento de diseño en proyectos de IA. Requiere la carga del archivo workflow.xml y la lectura de su contenido para ejecutar el flujo de trabajo.","fr":"bmad-cis-design-thinking est une compétence qui permet d''améliorer la pensée de conception dans les projets d''IA. Elle nécessite le chargement du fichier workflow.xml et la lecture de son contenu pour exécuter le flux de travail.","de":"bmad-cis-design-thinking ist ein Skill, der das Design-Denken in KI-Projekten verbessert. Er erfordert das Laden der Datei workflow.xml und das Lesen ihres Inhalts, um den Arbeitsablauf auszuführen.","pt":"O bmad-cis-design-thinking é um conjunto de ferramentas para execução de workflows com design thinking, que requer a carga do arquivo workflow.xml e a leitura do arquivo workflow.yaml","ru":"ИИ Агент bmad-cis-design-thinking - это набор инструментов для выполнения рабочих процессов с дизайн-мышлением, требующий загрузки файла workflow.xml и чтения файла workflow.yaml","ar":"أداة الذكاء الاصطناعي bmad-cis-design-thinking هي مجموعة من الأدوات لتنفيذ سير العمل باستخدام التصميم الإبداعي، وتتطلب تحميل ملف workflow.xml وقراءة ملف workflow.yaml"},"seo":{"title":{"en":"bmad-cis-design-thinking: Workflow Configuration Setup Gu...","zh":"bmad-cis-design-thinking 设计思维工作流配置指南","ja":"bmad-cis-design-thinking デザイン思考ワークフローのセットアップガイド","ko":"bmad-cis-design-thinking 디자인 사고 워크플로우 설정 가이드","es":"Guía de configuración de bmad-cis-design-thinking para Ag...","fr":"Guide de configuration de bmad-cis-design-thinking pour l...","de":"Konfigurationsleitfaden für bmad-cis-design-thinking für ...","pt":"Guia de Configuração do bmad-cis-design-thinking","ru":"Настройка ИИ Агента bmad-cis-design-thinking","ar":"إعداد أداة الذكاء الاصطناعي bmad-cis-design-thinking"},"description":{"en":"Unlock efficient workflow execution with bmad-cis-design-thinking. Learn how to load and configure workflow.xml and workflow.yaml files for seamless AI agent...","zh":"了解如何配置 bmad-cis-design-thinking 设计思维工作流，包括加载 workflow.xml 和读取 workflow.yaml","ja":"bmad-cis-design-thinking デザイン思考ワークフローの設定方法を学びましょう。workflow.xml のロードと workflow.yaml の読み取りを含みます","ko":"bmad-cis-design-thinking 디자인 사고 워크플로우를 설정하는 방법을 알아보세요. workflow.xml을 로드하고 workflow.yaml을 읽는 것을 포함합니다","es":"Aprende a configurar bmad-cis-design-thinking para mejorar el pensamiento de diseño en tus proyectos de IA. Sigue nuestros pasos críticos para una implementa...","fr":"Découvrez comment configurer bmad-cis-design-thinking pour améliorer la pensée de conception dans vos projets d''IA. Suivez nos étapes critiques pour une mise...","de":"Erfahren Sie, wie Sie bmad-cis-design-thinking konfigurieren, um das Design-Denken in Ihren KI-Projekten zu verbessern. Befolgen Sie unsere kritischen Schrit...","pt":"Aprenda a configurar o bmad-cis-design-thinking para melhorar a execução de workflows com design thinking","ru":"Узнайте, как настроить ИИ Агент bmad-cis-design-thinking для улучше