INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ever-sync/stravox/bmad-cis-design-thinking', 'bmad-cis-design-thinking', 'ever-sync', 'stravox', 'community', 'bmad-cis-design-thinking ever-sync stravox community The bmad-cis-design-thinking skill enables AI agents to execute specific workflows by loading and reading workflow.xml and workflow.yaml files. This skill benefits developers working with AI workflow configurations. bmad-cis-design-thinking 设计思维工作流需要加载 workflow.xml 和读取 workflow.yaml 配置文件 bmad-cis-design-thinking デザイン思考ワークフローでは、workflow.xml をロードし、workflow.yaml 構成ファイルを読み取ります bmad-cis-design-thinking 디자인 사고 워크플로우는 workflow.xml을 로드하고 workflow.yaml 구성 파일을 읽습니다 bmad-cis-design-thinking es un skill que permite mejorar el pensamiento de diseño en proyectos de IA. Requiere la carga del archivo workflow.xml y la lectura de su contenido para ejecutar el flujo de trabajo. bmad-cis-design-thinking est une compétence qui permet d''améliorer la pensée de conception dans les projets d''IA. Elle nécessite le chargement du fichier workflow.xml et la lecture de son contenu pour exécuter le flux de travail. bmad-cis-design-thinking ist ein Skill, der das Design-Denken in KI-Projekten verbessert. Er erfordert das Laden der Datei workflow.xml und das Lesen ihres Inhalts, um den Arbeitsablauf auszuführen. O bmad-cis-design-thinking é um conjunto de ferramentas para execução de workflows com design thinking, que requer a carga do arquivo workflow.xml e a leitura do arquivo workflow.yaml ИИ Агент bmad-cis-design-thinking - это набор инструментов для выполнения рабочих процессов с дизайн-мышлением, требующий загрузки файла workflow.xml и чтения файла workflow.yaml أداة الذكاء الاصطناعي bmad-cis-design-thinking هي مجموعة من الأدوات لتنفيذ سير العمل باستخدام التصميم الإبداعي، وتتطلب تحميل ملف workflow.xml وقراءة ملف workflow.yaml how to use bmad-cis-design-thinking bmad-cis-design-thinking setup guide bmad-cis-design-thinking workflow configuration bmad-cis-design-thinking alternative bmad-cis-design-thinking vs workflow automation tools what is bmad-cis-design-thinking bmad-cis-design-thinking install bmad-cis-design-thinking tutorial bmad-cis-design-thinking AI agent integration bmad-cis-design-thinking 设计思维工作流 workflow.xml workflow.yaml AI 工具 工作流配置 XML 配置 YAML 配置 Loads full workflow.xml from {project-root}/_bmad/core/tasks/ Reads entire contents of workflow.xml for core OS execution Passes yaml path as ''workflow-config'' parameter to workflow.xml Utilizes _bmad/cis/workflows/design-thinking/workflow.yaml for specific workflow configuration Executes workflows using workflow.xml and workflow.yaml files Supports critical workflow configuration and execution for AI agents bmad-cis-design-thinking is a skill that facilitates workflow configuration and execution for AI agents using workflow.xml and workflow.yaml files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AILouis/RMBI_Capstone/Attachments UI', 'community', 'AILouis', 'RMBI_Capstone', 'AILouis/RMBI_Capstone', 'Attachments UI', 0, 0, 26, '2026-03-06T17:12:48Z', '2026-03-08T02:19:08.048Z', '057f42bd636cf14f201bc80182b5a71377029745c1da0698428d50c2af21d94a', '{"id":"AILouis/RMBI_Capstone/Attachments UI","name":"Attachments UI","description":{"en":"Attachments UI is a full-stack web app that enables AI agents to detect and visualize stock patterns. It benefits developers by providing interactive file management capabilities.","zh":"Attachments UI 是一个全栈 web 应用，允许用户与 AI エージェント交互，检测和可视化股票图表模式","ja":"Attachments UI は、AI エージェントと交互して株式チャートパターンを検出および視覚化するフルスタック Web アプリケーションです","ko":"Attachments UI는 사용자가 AI 에이전트와 상호 작용하여 주가 차트 패턴을 감지하고 시각화할 수 있는 풀스택 웹 애플리케이션입니다","es":"La interfaz de usuario de adjuntos es una aplicación web de pila completa que permite a los desarrolladores interactuar con un agente de inteligencia artificial para detectar patrones de velas y gráficos en acciones bursátiles","fr":"L''interface utilisateur des pièces jointes est une application web full-stack qui permet aux développeurs d''interagir avec un agent d''intelligence artificielle pour détecter des modèles de chandeliers et de graphiques sur les actions boursières","de":"Die Benutzeroberfläche für Anlagen ist eine Full-Stack-Webanwendung, die es Entwicklern ermöglicht, mit einem KI-Agenten zu interagieren, um Kerzen- und Chartmuster an Aktienmärkten zu erkennen","pt":"Attachments UI é uma ferramenta de interface do usuário que permite aos desenvolvedores criar visualizações de arquivos e uploads de progresso personalizadas","ru":"Attachments UI - это инструмент интерфейса пользователя, который позволяет разработчикам создавать индивидуальные визуализации файлов и прогресс-бары загрузки","ar":"Attachments UI هي أداة واجهة المستخدم التي تمكن المط