INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AILouis/RMBI_Capstone/Attachments UI', 'Attachments UI', 'AILouis', 'RMBI_Capstone', 'community', 'Attachments UI AILouis RMBI_Capstone community Attachments UI is a full-stack web app that enables AI agents to detect and visualize stock patterns. It benefits developers by providing interactive file management capabilities. Attachments UI 是一个全栈 web 应用，允许用户与 AI エージェント交互，检测和可视化股票图表模式 Attachments UI は、AI エージェントと交互して株式チャートパターンを検出および視覚化するフルスタック Web アプリケーションです Attachments UI는 사용자가 AI 에이전트와 상호 작용하여 주가 차트 패턴을 감지하고 시각화할 수 있는 풀스택 웹 애플리케이션입니다 La interfaz de usuario de adjuntos es una aplicación web de pila completa que permite a los desarrolladores interactuar con un agente de inteligencia artificial para detectar patrones de velas y gráficos en acciones bursátiles L''interface utilisateur des pièces jointes est une application web full-stack qui permet aux développeurs d''interagir avec un agent d''intelligence artificielle pour détecter des modèles de chandeliers et de graphiques sur les actions boursières Die Benutzeroberfläche für Anlagen ist eine Full-Stack-Webanwendung, die es Entwicklern ermöglicht, mit einem KI-Agenten zu interagieren, um Kerzen- und Chartmuster an Aktienmärkten zu erkennen Attachments UI é uma ferramenta de interface do usuário que permite aos desenvolvedores criar visualizações de arquivos e uploads de progresso personalizadas Attachments UI - это инструмент интерфейса пользователя, который позволяет разработчикам создавать индивидуальные визуализации файлов и прогресс-бары загрузки Attachments UI هي أداة واجهة المستخدم التي تمكن المطورين من إنشاء معارض ملفات وشرائح تحميل مخصصة how to use Attachments UI Attachments UI alternative Attachments UI setup guide what is Attachments UI Attachments UI vs competitor Attachments UI install interactive file management AI agent file upload stock pattern visualization Attachments UI AI エージェント 文件上传 交互式界面 进度条 大文件上传 AI 工具 全栈 web 应用 Displays thumbnail previews for image attachments Features clear iconography banners for non-image files (e.g., PDF) Allows users to remove attachments via ''X'' or ''Trash'' icons Shows percentage progress bars for large file uploads Supports interactive visualization of detected stock patterns Attachments UI is a web application feature that handles record attachments with visual cues, interaction, and progress tracking for improved user experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Manuel-kl/Hazon/wayfinder-development', 'community', 'Manuel-kl', 'Hazon', 'Manuel-kl/Hazon', 'wayfinder-development', 0, 0, 26, '2026-03-07T01:49:01.580Z', '2026-03-07T02:08:13.264Z', '2f0edd3ba15dfe0856cae88144ae95c57c88c9b1293da7d9e6ac25041c9c1b24', '{"id":"Manuel-kl/Hazon/wayfinder-development","name":"wayfinder-development","description":{"en":"wayfinder-development is a personal vision and productivity hub that tracks todos, wishlist ideas, saved links, and vision boards with a unified analytics dashboard, benefiting developers who work with Laravel and TypeScript/JavaScript.","zh":"Wayfinder开发是一种个人生产力和分析仪表盘，帮助开发者跟踪任务、想法和链接","ja":"Wayfinder開発は、個人用の生産性と分析ダッシュボードで、開発者がタスク、アイデア、リンクを追跡するのを支援します","ko":"Wayfinder 개발은 개인의 생산성 및 분석 대시보드로, 개발자가 작업, 아이디어, 링크를 추적하도록 도와줍니다","es":"Wayfinder Development es una herramienta para mejorar la productividad y la visión en proyectos con Laravel y TypeScript","fr":"Wayfinder Development est un outil pour améliorer la productivité et la vision dans les projets avec Laravel et TypeScript","de":"Wayfinder Development ist ein Tool zur Verbesserung der Produktivität und Vision in Projekten mit Laravel und TypeScript","pt":"O Wayfinder Development é uma plataforma de produtividade que oferece recursos como tracking de tarefas e análise unificada para melhorar a eficiência","ru":"Wayfinder Development - это платформа для повышения производительности, которая предлагает функции, такие как отслеживание задач и объединенный анализ, для повышения эффективности","ar":"Wayfinder Development هو منصة لتحسين الإنتاجية التي توفر ميزات مثل تتبع المهام والتحليل الموحد لتحسين الكفاءة"},"seo":{"title":{"en":"wayfinder-development: Unified Analytics Setup Guide | AI...","zh":"Wayfinder开发设置指南 - AI工具","ja":"Wayfinder開発ベストプラクティス - AIエージェント","ko":"Wayfinder 개발 가이드 - AI 도구","es":"Guía de configuración de Wayfinder Development para desar...","fr":"Guide de configuration de Wayfinder Development pour les ...","de":"Einrichtungsleitfaden für Wayfinder Development für Entwi...","pt":"Guia de Configuração do Wayfinder Development","ru":"Настройка Wayfinder Development: ИИ Агенты для Продуктивн...","ar":"دليل إعداد Wayfinder Development: أدوات ذكاء اصطناعي للتنمية"},"description":{"en":"Unlock efficient backend route management with wayfinder-development. Learn how to generate routes and integrate with Laravel for seamless navigation.","zh":"了解Wayfinder开发的技术细节，包括路由生成和Laravel集成。提高开发效率，优化代码质量","ja":"Wayfinder開発のテクニカルな詳細を学び、ルーティング生成とLaravel統合をマスターして開発効率を上げる","ko":"Wayfinder 개발의 기술적인 세부 정보를 확인하고, 라우팅 생성 및 Laravel 통합을 통해 개발 효율을 향상시키세요","es":"Aprende a utilizar Wayfinder Development para mejorar la productividad y la visión en tu proyecto con Laravel y TypeScript","fr":"Découvrez comment utiliser Wayfinder Development pour améliorer la productivité et la vision dans votre projet avec Laravel et TypeScript","de":"Erfahren Sie, wie Sie Wayfinder Development verwenden können, um die Produktivität und Vision in Ihrem Projekt mit Laravel und TypeScript zu verbessern","pt":"Aprenda a configurar o Wayfinder Development para melhorar a produtividade com recursos como tracking de tarefas e análise unificada","ru":"Узнайте, как настроить Wayfinder Development для повышения производительности с помощью функций, таких как отслеживание задач и объединенный анализ","ar":"تعرف على كيفية إعداد Wayfinder Development لتحسين الإنتاجية باستخدام ميزات مثل تتبع المهام والتحليل الموحد"},"definition":{"en":"wayfinder-development is a technical skill that provides a unified analytics dashboard for tracking various development-related tasks and ideas.","zh":"Wayfinder开发是一种AI工具，提供路由生成、Laravel集成和分析仪表盘等功能","ja":"Wayfinder開発は、AIエージェントの一種で、ルーティング生成、Laravel統合、分析ダッシュボードなどの機能を提供します","ko":"Wayfinder 개발은 AI 도구의 일종으로, 라우팅 생성, Laravel 통합, 분석 대시보드 등의 기능을 제공합니다","es":"Wayfinder Development es un sistema de seguimiento de tareas y enlaces para desarrolladores","fr":"Wayfinder Development est un système de suivi de tâches et de liens pour les développeurs","de":"Wayfinder Development ist ein System zur Verfolgung von Aufgaben und Links für Entwickler","pt":"O que é Wayfinder Development? É uma plataforma de produtividade que integra recursos como tracking de tarefas e análise unificada","ru":"Что такое Wayfinder Development? Это платформа для повышения производительности, которая объединяет функции, такие как отслеживание задач и объединенный анализ","ar":"ما هو Wayfinder Development? هو منصة لتحسين الإنتاجية التي تدمج ميزات مثل تتبع المهام والتحليل الموحد"},"features":{"en":["Generates routes using the php artisan wayfinder:generate command","Integrates with Laravel for seamless backend endpoint management","Supports importing from @/actions/ or @/routes/ in frontend components","Enables calling Laravel routes from TypeScript/JavaScript","Creates links or navigation to backend endpoints","Works with Vite plugin for efficient route generation"],"zh":["路由生成","Laravel集成","分析仪表盘","任务跟踪","想法管理","链接保存"],"ja":["ルーティング生成","Laravel統合","分析ダッシュボード","タスク追跡","アイデア管理","リンク保存"],"ko":["라우팅 생성","Laravel 통합","분석 대시보드","작업 추적","아이디어 관리","링크 저장"],"es":["Generación de rutas con php artisan wayfinder:generate","Integración con Laravel y TypeScript","Creación de enlaces y navegación a puntos finales de backend","Importación de acciones y rutas desde @/actions/ y @/routes/","Uso de search-docs para documentación detallada"],"fr":["Génération de routes avec php artisan wayfinder:generate","Intégration avec Laravel et TypeScript","Création de liens et de navigation vers les points de terminaison de backend","Importation d''actions et de routes depuis @/actions/ et @/routes/","Utilisation de search-docs pour la documentation détaillée"],"de":["Generierung von Routen mit php artisan wayfinder:generate","Integration mit Laravel und TypeScript","Erstellung von Links und Navigation zu Backend-Endpunkten","Import von Aktionen und Routen von @/actions/ und @/routes/","Verwendung von search-docs für detaillierte Dokumentation"],"pt":["Importação de rotas do Laravel","Chamadas de rotas do Laravel em TypeScript/JavaScript","Criação de links e navegação para endpoints de backend","Geração de rotas com o comando ''php artisan wayfinder:generate''","Integração com o plugin Vite"],"ru":["Импорт маршрутов Laravel","Вызовы маршрутов Laravel из TypeScript/JavaScript","Создание ссылок и навигации для конечных точек бэкенда","Генерация маршрутов с помощью команды ''php artisan wayfinder:generate''","Интеграция с плагином Vite"],"ar":["استيراد مسارات Laravel","استدعاء مسارات Laravel من TypeScript/JavaScript","إنشاء روابط وتوجيه لنقاط النهاية الخلفية","توليد المسارات باستخدام الأمر ''php artisan wayfinder:generate''","التكامل مع إضافة Vite"]},"keywords":{"en":["how to use wayfinder-development","wayfinder-development setup guide","wayfinder-development vs Laravel","wayfinder-development install","what is wayfinder-development","wayfinder-development alternative","wayfinder-development and TypeScript","wayfinder-development for AI agents","wayfinder-development with Vite","wayfinder-development documentation"],"zh":["Wayfinder开发","AI工具","路由生成","Laravel集成","分析仪表盘","任务跟踪","想法管理","链接保存","开发效率"],"ja":["Wayfinder開発","AIエージェント","ルーティング生成","Laravel統合","分析ダッシュボード","タスク追跡","アイデア管理","リンク保存","開発効率"],"ko":["Wayfinder 개발","AI 도구","라우팅 생성","Laravel 통합","분석 대시보드","작업 추적","아이디어 관리","링크 저장","개발 효율"],"es":["Wayfinder Development","desarrollo de software","Laravel","TypeScript","gestión de tareas","enlaces y navegación","generación de rutas","herramientas de desarrollo"],"fr":["Wayfinder Development","développement de logiciels","Laravel","TypeScript","gestion de tâches","liens et navigation","génération de routes","outils de développement"],"de":["Wayfinder Development","Software-Entwicklung","Laravel","TypeScript","Aufgabenverwaltung","Links und Navigation","Routen-Generierung","Entwicklungstools"],"pt":["wayfinder development","produtividade","tracking de tarefas","análise unificada","laravel","typescript","javascript","vite","desenvolvimento de software"],"ru":["wayfinder development","производительность","отслеживание задач","объединенный анализ","laravel","typescript","javascript","vite","разработка программного обеспечения"],"ar":["wayfinder development","الإنتاجية","تتبع المهام","التحليل الموحد","laravel","typescript","javascript","vite","تطوير البرمجيات"]}},"owner":"Manuel-kl","repo":"Hazon","repoPath":"Manuel-kl/Hazon","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.580Z","topics":[],"category":"community","skillMd":{"name":"wayfinder-development","description":">-","bodyPreview":"# Wayfinder Development\n\n## When to Apply\n\nActivate whenever referencing backend routes in frontend components:\n- Importing from `@/actions/` or `@/routes/`\n- Calling Laravel routes from TypeScript/JavaScript\n- Creating links or navigation to backend endpoints\n\n## Documentation\n\nUse `search-docs` for detailed Wayfinder patterns and documentation.\n\n## Quick Reference\n\n### Generate Routes\n\nRun after route changes if Vite plugin isn''t installed:\n\nphp artisan wayfinder:generate --no-interaction\n\nFor","body":"# Wayfinder Development\n\n## When to Apply\n\nActivate whenever referencing backend routes in frontend components:\n- Importing from `@/actions/` or `@/routes/`\n- Calling Laravel routes from TypeScript/JavaScript\n- Creating links or navigation to backend endpoints\n\n## Documentation\n\nUse `search-docs` for detailed Wayfinder patterns and documentation.\n\n## Quick Reference\n\n### Generate Routes\n\nRun after route changes if Vite plugin isn''t installed:\n\nphp artisan wayfinder:generate --no-interaction\n\nFor form helpers, use `--with-form` flag:\n\nphp artisan wayfinder:generate --with-form --no-interaction\n\n### Import Patterns\n\n<code-snippet name=\"Controller Action Imports\" lang=\"typescript\">\n\n// Named imports for tree-shaking (preferred)...\nimport { show, store, update } from ''@/actions/App/Http/Controllers/PostController''\n\n// Named route imports...\nimport { show as postShow } from ''@/routes/post''\n\n</code-snippet>\n\n### Common Methods\n\n<code-snippet name=\"Wayfinder Methods\" lang=\"typescript\">\n\n// Get route object...\nshow(1) // { url: \"/posts/1\", method: \"get\" }\n\n// Get URL string...\nshow.url(1) // \"/posts/1\"\n\n// Specific HTTP methods...\nshow.get(1)\nstore.post()\nupdate.patch(1)\ndestroy.delete(1)\n\n// Form attributes for HTML forms...\nstore.form() // { action: \"/posts\", method: \"post\" }\n\n// Query parameters...\nshow(1, { query: { page: 1 } }) // \"/posts/1?page=1\"\n\n</code-snippet>\n\n## Wayfinder + Inertia\n\nUse Wayfinder with the `<Form>` component:\n<code-snippet name=\"Wayfinder Form (Vue)\" lang=\"vue\">\n\n<Form v-bind=\"store.form()\"><input name=\"title\" /></Form>\n\n</code-snippet>\n\n## Verification\n\n1. Run `php artisan wayfinder:generate` to regenerate routes if Vite plugin isn''t installed\n2. Check TypeScript imports resolve correctly\n3. Verify route URLs match expected paths\n\n## Common Pitfalls\n\n- Using default imports instead of named imports (breaks tree-shaking)\n- Forgetting to regenerate after route changes\n- Not using type-safe parameter objects for route model binding"},"lastSynced":"2026-03-07T02:08:13.264Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents working with Laravel and TypeScript/JavaScript needing unified analytics and productivity tools.","zh":"适合使用Laravel和TypeScript/JavaScript的全栈代理，需要统一的分析和生产力工具。","ja":"LaravelとTypeScript/JavaScriptを使用するフルスタックエージェントに適しています。統一された分析と生産性ツールが必要です。","ko":"Laravel과 TypeScript/JavaScript를 사용하는 풀스택 에이전트에게 적합합니다. 통일된 분석 및 생산성 도구가 필요합니다.","es":"Perfecto para Agentes de Full Stack que trabajan con Laravel y TypeScript/JavaScript y necesitan herramientas de análisis y productividad unificadas.","fr":"Parfait pour les agents Full Stack travaillant avec Laravel et TypeScript/JavaScript qui ont besoin d''outils d''analyse et de productivité unifiés.","de":"Perfekt für Full-Stack-Agents, die mit Laravel und TypeScript/JavaScript arbeiten und einheitliche Analyse- und Produktivitätstools benötigen.","pt":"Perfeito para Agentes Full Stack que trabalham com Laravel e TypeScript/JavaScript e precisam de ferramentas de análise e produtividade unificadas.","ru":"Идеально подходит для полнофункциональных агентов, работающих с Laravel и TypeScript/JavaScript, которым необходимы унифицированные инструменты аналитики и производительности.","ar":"مثالي لعميل كامل يعمل مع Laravel وTypeScript/JavaScript و يحتاج إلى أدوات تحليل وإنتاجية موحدة."},"recommendation":{"en":"Empowers agents to track todos, wishlist ideas, saved links, and vision boards with a unified analytics dashboard, streamlining development workflows with Laravel routes and TypeScript/JavaScript integrations.","zh":"赋予代理跟踪待办事项、愿望清单、保存的链接和愿景板的能力，通过统一的分析仪表盘，简化Laravel路由和TypeScript/JavaScript集成的开发工作流程。","ja":"エージェントがTODO、ウィッシュリストアイデア、保存したリンク、ビジョンボードを追跡できるようにし、統一された分析ダッシュボードを使用して、LaravelルートとTypeScript/JavaScriptの統合で開発ワークフローを最適化します。","ko":"에이전트가 할 일, 소원 목록 아이디어, 저장된 링크 및 비전 보드를 추적할 수 있도록 해줌으로써, 통일된 분석 대시보드를 통해 Laravel 라우트 및 TypeScript/JavaScript 통합의 개발 워크플로우를 최적화합니다.","es":"Permite a los agentes realizar un seguimiento de los elementos pendientes, ideas de lista de deseos, enlaces guardados y tableros de visión con un panel de análisis unificado, simplificando los flujos de trabajo de desarrollo con rutas de Laravel y integraciones de TypeScript/JavaScript.","fr":"Permet aux agents de suivre les éléments à faire, les idées de liste de souhaits, les liens sauvegardés et les tableaux de vision avec un tableau de bord d''analyse unifié, rationalisant les flux de travail de développement avec des routes Laravel et des intégrations TypeScript/JavaScript.","de":"Ermöglicht es Agenten, Todos, Wunschideen, gespeicherte Links und Vision-Boards mit einem einheitlichen Analyse-Dashboard zu verfolgen und entwickelt Arbeitsabläufe mit Laravel-Routen und TypeScript/JavaScript-Integrationen zu rationalisieren.","pt":"Habilita os agentes a rastrear tarefas, ideias de lista de desejos, links salvos e quadros de visão com um painel de análise unificado, otimizando fluxos de trabalho de desenvolvimento com rotas Laravel e integrações TypeScript/JavaScript.","ru":"Наделяет агентов возможностью отслеживать задачи, идеи списка желаний, сохраненные ссылки и доски видения с помощью унифицированного аналитического панеля, оптимизируя потоки разработки с использованием маршрутов Laravel и интеграций TypeScript/JavaScript.","ar":"يمنح الوكلاء القدرة على تتبع المهام وأفكار قائمة الرغبات والروابط المحفوظة واللوحات المرئية مع لوحة تحليل موحدة، ويعزز سير عمل التطوير باستخدام طرق Laravel وتكاملات TypeScript/JavaScript."},"useCases":{"en":["Automating route generation with php artisan wayfinder:generate","Creating links or navigation to backend endpoints with Laravel and TypeScript/JavaScript","Debugging frontend components referencing backend routes"],"zh":["使用php artisan wayfinder:generate自动生成路由","使用Laravel和TypeScript/JavaScript创建链接或导航到后端端点","调试引用后端路由的前端组件"],"ja":["php artisan wayfinder:generateを使用してルートを自動生成する","LaravelとTypeScript/JavaScriptを使用してバックエンドエンドポイントへのリンクまたはナビゲーションを作成する","バックエンドルートを参照するフロントエンドコンポーネントのデバッグ"],"ko":["php artisan wayfinder:generate를 사용하여 라우트를 자동 생성","Laravel과 TypeScript/JavaScript를 사용하여 백엔드 엔드ポイント로의 링크 또는 네비게이션を作成","백엔드 라우트를 참조하는 프론트엔드 컴포넌트의 디버깅"],"es":["Automatizar la generación de rutas con php artisan wayfinder:generate","Crear enlaces o navegación a puntos de conexión de backend con Laravel y TypeScript/JavaScript","Depurar componentes frontend que hacen referencia a rutas de backend"],"fr":["Automatiser la génération de routes avec php artisan wayfinder:generate","Créer des liens ou une navigation vers les points de terminaison de backend avec Laravel et TypeScript/JavaScript","Déboguer les composants frontend qui font référence aux routes de backend"],"de":["Automatisieren der Generierung von Routen mit php artisan wayfinder:generate","Erstellen von Links oder Navigation zu Backend-Endpunkten mit Laravel und TypeScript/JavaScript","Fehlerbehebung von Frontend-Komponenten, die auf Backend-Routen verweisen"],"pt":["Automatizar geração de rotas com php artisan wayfinder:generate","Criar links ou navegação para endpoints de backend com Laravel e TypeScript/JavaScript","Depurar componentes frontend que referenciam rotas de backend"],"ru":["Автоматизировать генерацию маршрутов с помощью php artisan wayfinder:generate","Создавать ссылки или навигацию на конечные точки бэкэнда с помощью Laravel и TypeScript/JavaScript","Отлаживать компоненты frontend, ссылающиеся на маршруты бэкэнда"],"ar":["التلقائي لإنشاء طرق باستخدام php artisan wayfinder:generate","إنشاء روابط أو التنقل إلى نقاط النهاية الخلفية مع Laravel وTypeScript/JavaScript","تصحيح الأخطاء في مكونات واجهة المستخدم التي تشير إلى طرق خلفية"]},"limitations":{"en":["Requires Laravel and TypeScript/JavaScript setup","Vite plugin installation recommended for automatic route updates"],"zh":["需要Laravel和TypeScript/JavaScript的设置","建议安装Vite插件以实现自动路由更新"],"ja":["LaravelとTypeScript/JavaScriptの設定が必要","自動ルート更新のためにViteプラグインのインストールを推奨"],"ko":["Laravel과 TypeScript/JavaScript 설정이 필요","자동 라우트 업데이트를 위해 Vite 플러그인 설치를 권장"],"es":["Requiere configuración de Laravel y TypeScript/JavaScript","Se recomienda la instalación del plugin Vite para actualizaciones de rutas automáticas"],"fr":["Nécessite une configuration de Laravel et TypeScript/JavaScript","L''installation du plugin Vite est recommandée pour les mises à jour de routes automatiques"],"de":["Benötigt eine Konfiguration von Laravel und TypeScript/JavaScript","Die Installation des Vite-Plugins wird für automatische Routen-Updates empfohlen"],"pt":["Requer configuração do Laravel e TypeScript/JavaScript","Recomenda-se a instalação do plugin Vite para atualizações de rotas automáticas"],"ru":["Требует настройки Laravel и TypeScript/JavaScript","Рекомендуется установка плагина Vite для автоматических обновлений маршрутов"],"ar":["يتطلب إعداد Laravel وTypeScript/JavaScript","ينصح بتثبيت إضافة Vite لتحديثات الطرق التلقائية"]},"version":4},"contentHash":"2f0edd3ba15dfe0856cae88144ae95c57c88c9b1293da7d9e6ac25041c9c1b24","qualityScore":26}');
