INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Manuel-kl/Hazon/wayfinder-development', 'wayfinder-development', 'Manuel-kl', 'Hazon', 'community', 'wayfinder-development Manuel-kl Hazon community wayfinder-development is a personal vision and productivity hub that tracks todos, wishlist ideas, saved links, and vision boards with a unified analytics dashboard, benefiting developers who work with Laravel and TypeScript/JavaScript. Wayfinder开发是一种个人生产力和分析仪表盘，帮助开发者跟踪任务、想法和链接 Wayfinder開発は、個人用の生産性と分析ダッシュボードで、開発者がタスク、アイデア、リンクを追跡するのを支援します Wayfinder 개발은 개인의 생산성 및 분석 대시보드로, 개발자가 작업, 아이디어, 링크를 추적하도록 도와줍니다 Wayfinder Development es una herramienta para mejorar la productividad y la visión en proyectos con Laravel y TypeScript Wayfinder Development est un outil pour améliorer la productivité et la vision dans les projets avec Laravel et TypeScript Wayfinder Development ist ein Tool zur Verbesserung der Produktivität und Vision in Projekten mit Laravel und TypeScript O Wayfinder Development é uma plataforma de produtividade que oferece recursos como tracking de tarefas e análise unificada para melhorar a eficiência Wayfinder Development - это платформа для повышения производительности, которая предлагает функции, такие как отслеживание задач и объединенный анализ, для повышения эффективности Wayfinder Development هو منصة لتحسين الإنتاجية التي توفر ميزات مثل تتبع المهام والتحليل الموحد لتحسين الكفاءة how to use wayfinder-development wayfinder-development setup guide wayfinder-development vs Laravel wayfinder-development install what is wayfinder-development wayfinder-development alternative wayfinder-development and TypeScript wayfinder-development for AI agents wayfinder-development with Vite wayfinder-development documentation Wayfinder开发 AI工具 路由生成 Laravel集成 分析仪表盘 任务跟踪 想法管理 链接保存 开发效率 Generates routes using the php artisan wayfinder:generate command Integrates with Laravel for seamless backend endpoint management Supports importing from @/actions/ or @/routes/ in frontend components Enables calling Laravel routes from TypeScript/JavaScript Creates links or navigation to backend endpoints Works with Vite plugin for efficient route generation wayfinder-development is a technical skill that provides a unified analytics dashboard for tracking various development-related tasks and ideas.');
