INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('junwen-k/cookie-store/vitest', 'vitest', 'junwen-k', 'cookie-store', 'community', 'vitest junwen-k cookie-store community vitest提供了Cookie Store API的反应绑定，帮助开发者简化开发流程 vitestはCookie Store APIのリアクティブバインディングを提供し、開発者が開発を簡素化できるようにします vitest는 Cookie Store API의 반응형 바인딩을 제공하여 개발자가 개발을 단순화할 수 있습니다 vitest ofrece enlaces reactivos para la Cookie Store API, mejorando la eficiencia del desarrollo vitest propose des liens réactifs pour l''API Cookie Store, améliorant l''efficacité du développement vitest bietet reaktive Bindungen für die Cookie Store API, die Entwicklungseffizienz verbessern O Vitest oferece bindings reativos para a Cookie Store API, melhorando a experiência de desenvolvimento para os desenvolvedores Vitest предоставляет реактивные связи для Cookie Store API, улучшая опыт разработки для разработчиков يقدم Vitest ربطًا تفاعليًا لواجهة برمجة تطبيقات Cookie Store، مما يعزز تجربة التطوير للمطورين Reactive bindings for the Cookie Store API. vitest AIエージェント Cookie Store API 反应绑定 如何使用vitest vitest安装 vitest设置指南 vitest替代品 vitest和其他工具的比较 Reactive bindings for the Cookie Store API.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ixahmedxi/vitest-perf-benchmarks/vitest', 'community', 'ixahmedxi', 'vitest-perf-benchmarks', 'ixahmedxi/vitest-perf-benchmarks', 'vitest', 0, 0, 26, '2026-03-05T06:20:06.284Z', '2026-03-05T08:25:31.864Z', '87c8cf025987d1f1a0e9c0fd0b8605946a0ebd5478676471ce296d8f0adc0f07', '{"id":"ixahmedxi/vitest-perf-benchmarks/vitest","name":"vitest","description":{"zh":"vitest是一种JavaScript测试框架，支持jsdom和浏览器模式","ja":"vitestはJavaScriptテストフレームワークで、jsdomとブラウザモードをサポート","ko":"vitest는 JavaScript 테스트 프레임워크로 jsdom과 브라우저 모드를 지원","es":"vitest es una herramienta de prueba que ofrece dos modos: jsdom y navegador. Conoce sus diferencias y elige el mejor para tus necesidades","fr":"vitest est un outil de test qui offre deux modes : jsdom et navigateur. Découvrez leurs différences et choisissez le meilleur pour vos besoins","de":"vitest ist ein Testtool, das zwei Modi bietet: jsdom und Browser. Erfahren Sie mehr über ihre Unterschiede und wählen Sie den besten für Ihre Bedürfnisse","pt":"Vitest é uma ferramenta de teste para desenvolvedores, com JSdom e modo navegador como opções de execução.","ru":"Vitest - это инструмент для тестирования для разработчиков, с JSdom и режимом браузера как вариантами выполнения.","ar":"Vitest هي أداة اختبار لمنطقي التطبيقات، مع JSdom ووضع المتصفح كخيارين للتشغيل.","en":"vitest jsdom vs browser mode"},"seo":{"title":{"zh":"vitest AI工具：jsdom vs 浏览器模式","ja":"vitest AIエージェント：jsdom vs ブラウザモード","ko":"vitest AI 에이전트：jsdom vs 브라우저 모드","es":"Herramientas de vitest: jsdom vs modo navegador","fr":"Outils vitest : jsdom vs mode navigateur","de":"vitest Tools: jsdom vs Browser-Modus","pt":"Ferramentas de IA: Vitest JSdom vs Modo Navegador","ru":"ИИ Агенты: Vitest JSdom vs Режим Браузера","ar":"أدوات الذكاء الاصطناعي: Vitest JSdom مقابل وضع المتصفح","en":"vitest"},"description":{"zh":"vitest是一种JavaScript测试框架，支持jsdom和浏览器模式","ja":"vitestはJavaScriptテストフレームワークで、jsdomとブラウザモードをサポート","ko":"vitest는 JavaScript 테스트 프레임워크로 jsdom과 브라우저 모드를 지원","es":"vitest es una herramienta de prueba que ofrece dos modos: jsdom y navegador. Conoce sus diferencias y elige el mejor para tus necesidades","fr":"vitest est un outil de test qui offre deux modes : jsdom et navigateur. Découvrez leurs différences et choisissez le meilleur pour vos besoins","de":"vitest ist ein Testtool, das zwei Modi bietet: jsdom und Browser. Erfahren Sie mehr über ihre Unterschiede und wählen Sie den besten für Ihre Bedürfnisse","pt":"Vitest é uma ferramenta de teste para desenvolvedores, com JSdom e modo navegador como opções de execução.","ru":"Vitest - это инструмент для тестирования для разработчиков, с JSdom и режимом браузера как вариантами выполнения.","ar":"Vitest هي أداة اختبار لمنطقي التطبيقات، مع JSdom ووضع المتصفح كخيارين للتشغيل.","en":"vitest jsdom vs browser mode"},"definition":{"en":"vitest jsdom vs browser mode"},"features":{"zh":["支持jsdom和浏览器模式","提高开发效率","易于使用","支持多种测试框架","高性能测试"],"ja":["jsdomとブラウザモードをサポート","開発効率を上げる","使いやすい","多種のテストフレームワークをサポート","高性能テスト"],"ko":["jsdom과 브라우저 모드를 지원","개발 효율성을 높여라","사용하기 쉽다","다양한 테스트 프레임워크를 지원","고성능 테스트"],"es":["Pruebas en jsdom para un rendimiento óptimo","Pruebas en modo navegador para una experiencia de usuario realista","Compatibilidad con frameworks populares como React y Vue","Soporte para pruebas unitarias y de integración","Informes de prueba detallados y personalizables"],"fr":["Tests en jsdom pour des performances optimales","Tests en mode navigateur pour une expérience utilisateur réaliste","Compatibilité avec des frameworks populaires tels que React et Vue","Prise en charge des tests unitaires et d''intégration","Rapports de test détaillés et personnalisables"],"de":["Tests in jsdom für optimale Leistung","Tests im Browser-Modus für eine realistische Benutzeroberfläche","Kompatibilität mit beliebten Frameworks wie React und Vue","Unterstützung für Einheitstests und Integrations-tests","Detaillierte und anpassbare Testberichte"],"pt":["Execução de testes em JSdom","Execução de testes em modo navegador","Suporte a frameworks JavaScript","Relatórios de teste detalhados","Integração com outras ferramentas de desenvolvimento"],"ru":["Выполнение тестов в JSdom","Выполнение тестов в режиме браузера","Поддержка фреймворков JavaScript","Детальные отчеты о тестировании","Интеграция с другими инструментами разработки"],"ar":["تشغيل الاختبارات في JSdom","تشغيل الاختبارات في وضع المتصفح","دعم إطارات جافا سكريبت","تقارير اختبار مفصلة","التكامل مع أدوات تطوير أخرى"]},"keywords":{"zh":["vitest","jsdom","浏览器模式","JavaScript测试","如何使用vitest","vitest安装","vitest设置指南"],"ja":["vitest","jsdom","ブラウザモード","JavaScriptテスト","vitestの使い方","vitestのインストール","vitestの設定ガイド"],"ko":["vitest","jsdom","브라우저 모드","JavaScript 테스트","vitest 사용법","vitest 설치","vitest 설정 가이드"],"es":["vitest vs jest","cómo usar vitest","qué es jsdom","pruebas en navegador","herramientas de prueba JavaScript","instalación de vitest","guía de configuración de vitest"],"fr":["vitest vs jest","comment utiliser vitest","quoi est jsdom","tests dans un navigateur","outils de test JavaScript","installation de vitest","guide de configuration de vitest"],"de":["vitest vs jest","wie man vitest verwendet","was ist jsdom","Tests im Browser","JavaScript-Testtools","Installation von vitest","Konfigurationsanleitung für vitest"],"pt":["vitest","jsdom","modo navegador","ferramentas de teste","desenvolvimento de software","javascript","teste de unidade","como usar vitest","vitest vs jest"],"ru":["vitest","jsdom","режим браузера","инструменты тестирования","разработка программного обеспечения","javascript","модульное тестирование","как использовать vitest","vitest vs jest"],"ar":["vitest","jsdom","وضع المتصفح","أدوات الاختبار","تطوير البرمجيات","جافا سكريبت","اختبار الوحدة","كيفية استخدام vitest","vitest مقابل jest"]}},"owner":"ixahmedxi","repo":"vitest-perf-benchmarks","repoPath":"ixahmedxi/vitest-perf-benchmarks","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.284Z","topics":[],"category":"community","skillMd":{"name":"vitest","description":"Vitest fast unit testing framework powered by Vite with Jest-compatible API. Use when writing tests, mocking, configuring coverage, or working with test filtering and fixtures.","version":"2026.1.28","bodyPreview":"Vitest is a next-generation testing framework powered by Vite. It provides a Jest-compatible API with native ESM, TypeScript, and JSX support out of the box. Vitest shares the same config, transformers, resolvers, and plugins with your Vite app.\n\n**Key Features:**\n- Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates\n- Jest-compatible: Drop-in replacement for most Jest test suites\n- Smart watch mode: Only reruns affected tests based on module graph\n- Native ESM, TypeS","body":"Vitest is a next-generation testing framework powered by Vite. It provides a Jest-compatible API with native ESM, TypeScript, and JSX support out of the box. Vitest shares the same config, transformers, resolvers, and plugins with your Vite app.\n\n**Key Features:**\n- Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates\n- Jest-compatible: Drop-in replacement for most Jest test suites\n- Smart watch mode: Only reruns affected tests based on module graph\n- Native ESM, TypeScript, JSX support without configuration\n- Multi-threaded workers for parallel test execution\n- Built-in coverage via V8 or Istanbul\n- Snapshot testing, mocking, and spy utilities\n\n> The skill is based on Vitest 3.x, generated at 2026-01-28.\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | Vitest and Vite config integration, defineConfig usage | [core-config](references/core-config.md) |\n| CLI | Command line interface, commands and options | [core-cli](references/core-cli.md) |\n| Test API | test/it function, modifiers like skip, only, concurrent | [core-test-api](references/core-test-api.md) |\n| Describe API | describe/suite for grouping tests and nested suites | [core-describe](references/core-describe.md) |\n| Expect API | Assertions with toBe, toEqual, matchers and asymmetric matchers | [core-expect](references/core-expect.md) |\n| Hooks | beforeEach, afterEach, beforeAll, afterAll, aroundEach | [core-hooks](references/core-hooks.md) |\n\n## Features\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Mocking | Mock functions, modules, timers, dates with vi utilities | [features-mocking](references/features-mocking.md) |\n| Snapshots | Snapshot testing with toMatchSnapshot and inline snapshots | [features-snapshots](references/features-snapshots.md) |\n| Coverage | Code coverage with V8 or Istanbul providers | [features-coverage](references/features-coverage.md) |\n| Test Context | Test fixtures, context.expect, test.extend for custom fixtures | [features-context](references/features-context.md) |\n| Concurrency | Concurrent tests, parallel execution, sharding | [features-concurrency](references/features-concurrency.md) |\n| Filtering | Filter tests by name, file patterns, tags | [features-filtering](references/features-filtering.md) |\n\n## Advanced\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Vi Utilities | vi helper: mock, spyOn, fake timers, hoisted, waitFor | [advanced-vi](references/advanced-vi.md) |\n| Environments | Test environments: node, jsdom, happy-dom, custom | [advanced-environments](references/advanced-environments.md) |\n| Type Testing | Type-level testing with expectTypeOf and assertType | [advanced-type-testing](references/advanced-type-testing.md) |\n| Projects | Multi-project workspaces, different configs per project | [advanced-projects](references/advanced-projects.md) |\n"},"lastSynced":"2026-03-05T08:25:31.864Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript Agents requiring high-performance testing frameworks with native ESM and TypeScript support.","zh":"适合需要高性能测试框架的JavaScript代理，具有原生ESM和TypeScript支持。","ja":"高性能テストフレームワークのネイティブESMとTypeScriptサポートを必要とするJavaScriptエージェントに最適。","ko":"원生 ESM 및 TypeScript 지원이 있는 고성능 테스트 프레임워크가 필요한 JavaScript 에이전트에 적합합니다.","es":"Ideal para agentes de JavaScript que requieren frameworks de pruebas de alto rendimiento con soporte nativo para ESM y TypeScript.","fr":"Idéal pour les agents JavaScript nécessitant des frameworks de test haute performance avec une prise en charge native de ESM et TypeScript.","de":"Ideal für JavaScript-Agents, die Frameworks für Hochleistungs-Tests mit nativer ESM- und TypeScript-Unterstützung erfordern.","pt":"Ideal para agentes JavaScript que exigem frameworks de teste de alto desempenho com suporte nativo a ESM e TypeScript.","ru":"Идеально подходит для агентов JavaScript, требующих фреймворков для тестирования с высокими показателями производительности и поддержкой родных ESM и TypeScript.","ar":"مثالي لعميل جافا سكريبت الذي يتطلب إطارات اختبار عالية الأداء مع دعم أصلي لـ ESM و TypeScript."},"recommendation":{"en":"Empowers agents to leverage Vite-native testing with Jest-compatible APIs, utilizing jsdom and browser modes for efficient test updates and smart watch modes for optimized test reruns, all while supporting JSX and native ESM.","zh":"赋予代理利用Vite原生测试的能力，具有Jest兼容的API，利用jsdom和浏览器模式实现高效的测试更新和智能监视模式实现优化的测试重新运行，同时支持JSX和原生ESM。","ja":"エージェントにViteネイティブのテストを利用する力を与え、Jest互換のAPIを利用し、jsdomとブラウザモードを使用して効率的なテスト更新とスマートなウォッチモードを使用して最適化されたテストの再実行を実現し、JSXとネイティブESMもサポートします。","ko":"에이전트가 Vite 네이티브 테스트를 활성화 할 수 있도록 하며 Jest 호환 API를 사용하여 jsdom 및 브라우저 모드를 사용하여 효율적인 테스트 업데이트 및 스마트 감시 모드를 사용하여 최적화 된 테스트 재실행을 지원하며 JSX 및 네이티브 ESM도 지원합니다.","es":"Permite a los agentes aprovechar las pruebas nativas de Vite con API compatibles con Jest, utilizando jsdom y modos de navegador para actualizaciones de pruebas eficientes y modos de vigilancia inteligentes para repeticiones de pruebas optimizadas, todo ello mientras se admite JSX y ESM nativo.","fr":"Permet aux agents d''exploiter les tests natifs Vite avec des API compatibles Jest, en utilisant jsdom et les modes navigateur pour des mises à jour de tests efficaces et des modes de surveillance intelligents pour des réexécutions de tests optimisées, le tout en prenant en charge JSX et ESM natif.","de":"Ermöglicht es Agenten, Vite-native Tests mit Jest-kompatiblen APIs zu nutzen, wobei jsdom und Browsermodi für effiziente Testaktualisierungen und intelligente Beobachtungsmodi für optimierte Testwiederholungen verwendet werden, während JSX und native ESM unterstützt werden.","pt":"Permite que os agentes utilizem testes nativos do Vite com APIs compatíveis com Jest, utilizando jsdom e modos de navegador para atualizações de teste eficientes e modos de observação inteligentes para repetições de teste otimizadas, tudo isso enquanto oferece suporte a JSX e ESM nativo.","ru":"Предоставляет агентам возможность использовать родные тесты Vite с API, совместимыми с Jest, используя jsdom и режимы браузера для эффективных обновлений тестов и умных режимов наблюдения для оптимизированных повторных запусков тестов, все это при поддержке JSX и родного ESM.","ar":"يمنح العميل khảية استخدام اختبارات Vite الأصلي مع واجهات برمجة تطبيقات متوافقة مع Jest، مستخدما jsdom ووضع المتصفح لتحديثات الاختبار الفعالة ووضع مراقبة ذكي لتشغيل الاختبار المتكرر الأمثل، مع دعم JSX و ESM الأصلي في نفس الوقت."},"useCases":{"en":["Rerunning affected tests based on module graphs","Utilizing Vite''s transformation pipeline for fast HMR-like test updates","Migrating Jest test suites to Vitest for improved performance"],"zh":["基于模块图重新运行受影响的测试","利用Vite的转换管道实现快速的HMR样式测试更新","将Jest测试套件迁移到Vitest以提高性能"],"ja":["モジュールグラフに基づいて影響を受けたテストを再実行する","Viteの変換パイプラインを利用して高速なHMRのようなテスト更新を実現する","JestテストスイートをVitestに移行してパフォーマンスを向上させる"],"ko":["모듈 그래프를 기반으로 영향을 받는 테스트를 다시 실행하는 것","Vite의 변환 파이프라인을 사용하여 빠른 HMR와 같은 테스트 업데이트를 구현하는 것","Jest 테스트 스위트를 Vitest로 마이그레이션하여 성능을 개선하는 것"],"es":["Reejecución de pruebas afectadas en función de gráficos de módulos","Uso de la canalización de transformación de Vite para actualizaciones de pruebas rápidas similares a HMR","Migración de conjuntos de pruebas de Jest a Vitest para un mejor rendimiento"],"fr":["Réexécution de tests affectés en fonction de graphiques de modules","Utilisation du pipeline de transformation de Vite pour des mises à jour de tests rapides similaires à HMR","Migration de suites de tests Jest vers Vitest pour une meilleure performance"],"de":["Neuausführung betroffener Tests basierend auf Modulgraphen","Verwendung von Vites Transformationpipeline für schnelle HMR-ähnliche Testaktualisierungen","Migration von Jest-Test-Suiten zu Vitest für verbesserte Leistung"],"pt":["Reexecução de testes afetados com base em gráficos de módulos","Utilização do pipeline de transformação do Vite para atualizações de teste rápidas semelhantes ao HMR","Migração de conjuntos de testes Jest para Vitest para melhorar o desempenho"],"ru":["Повторный запуск затронутых тестов на основе графиков модулей","Использование конвейера преобразования Vite для быстрых обновлений тестов, подобных HMR","Миграция наборов тестов Jest в Vitest для улучшения производительности"],"ar":["إعادة تشغيل الاختبارات المتأثرة بالاعتماد على رسوم بيانية للوحدات","استخدام محول Vite لتحديثات الاختبار السريعة المماثلة ل HMR","هجرة مجموعات الاختبار Jest إلى Vitest لتحسين الأداء"]},"limitations":{"en":["Requires Vite configuration and setup","Limited to JavaScript and TypeScript environments"],"zh":["需要Vite配置和设置","仅限于JavaScript和TypeScript环境"],"ja":["Viteの設定とセットアップが必要","JavaScriptとTypeScriptの環境のみに限定"],"ko":["Vite 구성 및 설정이 필요합니다.","JavaScript 및 TypeScript 환경에만 제한됨"],"es":["Requiere configuración y configuración de Vite","Limitado a entornos de JavaScript y TypeScript"],"fr":["Nécessite une configuration et une installation de Vite","Limité aux environnements JavaScript et TypeScript"],"de":["Erfordert Vite-Konfiguration und -Einrichtung","Begrenzt auf JavaScript- und TypeScript-Umgebungen"],"pt":["Exige configuração e instalação do Vite","Limitado a ambientes JavaScript e TypeScript"],"ru":["Требует настройки и установки Vite","Ограничен средами JavaScript и TypeScript"],"ar":["يتطلب تهيئة وتثبيت Vite","محدود بيئات جافا سكريبت و TypeScript"]},"version":3},"contentHash":"87c8cf025987d1f1a0e9c0fd0b8605946a0ebd5478676471ce296d8f0adc0f07","qualityScore":26}');
