INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ixahmedxi/vitest-perf-benchmarks/vitest', 'vitest', 'ixahmedxi', 'vitest-perf-benchmarks', 'community', 'vitest ixahmedxi vitest-perf-benchmarks community vitest是一种JavaScript测试框架，支持jsdom和浏览器模式 vitestはJavaScriptテストフレームワークで、jsdomとブラウザモードをサポート vitest는 JavaScript 테스트 프레임워크로 jsdom과 브라우저 모드를 지원 vitest es una herramienta de prueba que ofrece dos modos: jsdom y navegador. Conoce sus diferencias y elige el mejor para tus necesidades vitest est un outil de test qui offre deux modes : jsdom et navigateur. Découvrez leurs différences et choisissez le meilleur pour vos besoins vitest ist ein Testtool, das zwei Modi bietet: jsdom und Browser. Erfahren Sie mehr über ihre Unterschiede und wählen Sie den besten für Ihre Bedürfnisse Vitest é uma ferramenta de teste para desenvolvedores, com JSdom e modo navegador como opções de execução. Vitest - это инструмент для тестирования для разработчиков, с JSdom и режимом браузера как вариантами выполнения. Vitest هي أداة اختبار لمنطقي التطبيقات، مع JSdom ووضع المتصفح كخيارين للتشغيل. vitest jsdom vs browser mode vitest jsdom 浏览器模式 JavaScript测试 如何使用vitest vitest安装 vitest设置指南 vitest jsdom vs browser mode');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danthegoodman1/netfence/integrity-checks', 'community', 'danthegoodman1', 'netfence', 'danthegoodman1/netfence', 'integrity-checks', 87, 2, 25, '2026-02-22T06:10:53Z', '2026-03-06T06:33:13.527Z', 'ae6cd7539480d3ef45970850fcf9ca448ecead210e81cd60b980dc90e4ea6cd7', '{"id":"danthegoodman1/netfence/integrity-checks","name":"integrity-checks","description":{"en":"Integrity-checks ensures eBPF filters are free from deadlocks and race conditions, benefiting developers working with Envoy xDS. This skill guarantees efficient lock management.","zh":"integrity-checks 是一种确保 eBPF 过滤器正确性和高效性的技术，防止死锁和竞态条件。通过设置 integrity-checks，开发者可以确保代码的可靠性和性能。","ja":"Integrity Checks は、eBPF フィルタの正しさと効率性を確保する技術です。デッドロックとレースコンディションを防ぎます。Integrity Checks を設定すると、開発者はコードの信頼性とパフォーマンスを確保できます。","ko":"integrity-checks는 eBPF 필터의 정확성과 효율성을 보장하는 기술로, 데드락과 경쟁 상태를 방지합니다. integrity-checks를 설정하면 개발자는 코드의 신뢰성과 성능을 보장할 수 있습니다.","es":"Integrity-checks garantiza la integridad del código después de ediciones, previniendo deadlocks y condiciones de carrera","fr":"Les integrity-checks assurent l''intégrité du code après édition, en prévenant les deadlocks et les conditions de course","de":"Integrity-checks gewährleisten die Integrität des Codes nach Bearbeitungen, indem Deadlocks und Race-Bedingungen vermieden werden","pt":"As verificações de integridade garantem que o código não contenha deadlocks ou condições de corrida após edições, otimizando o uso de locks.","ru":"Проверки целостности обеспечивают отсутствие замков и гонок в коде после правок, оптимизируя использование блокировок.","ar":"تضمن فحوصات الصحة أن الكود لا يحتوي على أقفال أو ظروف تنافسية بعد التعديلات، وتهدف إلى تحسين استخدام الأقفال."},"seo":{"title":{"en":"Integrity-Checks: Deadlock Prevention for eBPF Filters | ...","zh":"integrity-checks 设置指南：防止死锁和竞态条件","ja":"Integrity Checks のベストプラクティス：デッドロックとレースコンディションを回避する","ko":"integrity-checks 설정 가이드: 데드락과 경쟁 상태 피하기","es":"Guía de configuración de integrity-checks para evitar dea...","fr":"Mise en place de integrity-checks pour prévenir les deadl...","de":"Einrichtungsleitfaden für integrity-checks zur Vermeidung...","pt":"Guia de Configuração de Integridade de Código com eBPF","ru":"ИИ Агенты: Настройка Проверок Целостности для eBPF Фильтров","ar":"دليل إعداد فحص الصحة مع مرشحات eBPF"},"description":{"en":"Learn how to implement integrity-checks for eBPF filters, ensuring deadlock-free code. Get started with our expert guide and optimize your workflow today!","zh":"了解 integrity-checks 的技术细节，确保 eBPF 过滤器的正确性和高效性。AIエージェント","ja":"Integrity Checks の詳細を学び、eBPF フィルタの信頼性とパフォーマンスを確保する。AIエージェント","ko":"integrity-checks의 기술 세부 사항을 배우고 eBPF 필터의 정확성과 효율성을 보장하십시오. AI 도구","es":"Aprende a implementar integrity-checks para prevenir deadlocks y condiciones de carrera en tus proyectos de eBPF","fr":"Découvrez comment mettre en place les integrity-checks pour éviter les deadlocks et les conditions de course dans vos projets eBPF","de":"Erfahren Sie, wie Sie integrity-checks implementieren, um Deadlocks und Race-Bedingungen in Ihren eBPF-Projekten zu vermeiden","pt":"Aprenda a garantir a integridade do código com verificações de deadlocks e condições de corrida para eBPF","ru":"Узнайте, как обеспечить целостность кода с помощью проверок на замки и гонки для фильтров eBPF","ar":"تعلم كيفية ضمان صحة الكود مع فحوصات الأقفال والظروف التنافسية لمرشحات eBPF"},"definition":{"en":"integrity-checks is a skill that verifies eBPF filter code for potential deadlocks and race conditions, promoting secure and efficient programming practices.","zh":"integrity-checks 是一种技术，确保 eBPF 过滤器在编辑后不会引入死锁或竞态条件","ja":"Integrity Checks は、eBPF フィルタが編集後にデッドロックやレースコンディションを導入しないことを保証する技術です","ko":"integrity-checks는 eBPF 필터가 편집 후에 데드락이나 경쟁 상태를 발생시키지 않는 것을 보장하는 기술입니다","es":"Integrity-checks es una técnica para verificar la integridad del código eBPF después de ediciones","fr":"Les integrity-checks sont une technique pour vérifier l''intégrité du code eBPF après édition","de":"Integrity-checks ist eine Technik zur Überprüfung der Integrität von eBPF-Code nach Bearbeitungen","pt":"Verificações de integridade são processos que garantem a segurança e eficiência do código após modificações.","ru":"Проверки целостности - это процессы, обеспечивающие безопасность и эффективность кода после изменений.","ar":"فحوصات الصحة هي عمليات تضمن أمان وكفاءة الكود بعد التعديلات."},"features":{"en":["Prevents deadlocks in eBPF filter code","Detects race conditions after code edits","Optimizes lock management for efficient programming","Ensures compatibility with Envoy xDS","Verifies code integrity after modifications","Supports efficient debugging and testing"],"zh":["防止死锁和竞态条件","确保 eBPF 过滤器的正确性和高效性","设置 integrity-checks 后，代码的可靠性和性能得到保证","支持 Envoy xDS 和 eBPF 过滤器","有效减少锁定开销"],"ja":["デッドロックとレースコンディションを防ぐ","eBPF フィルタの正しさと効率性を確保する","Integrity Checks を設定後、コードの信頼性とパフォーマンスが確保される","Envoy xDS と eBPF フィルタをサポートする","ロックのオーバーヘッドを減らす"],"ko":["데드락과 경쟁 상태를 방지합니다","eBPF 필터의 정확성과 효율성을 보장합니다","integrity-checks를 설정한 후 코드의 신뢰성과 성능이 보장됩니다","Envoy xDS와 eBPF 필터를 지원합니다","잠금 오버헤드를 줄입니다"],"es":["Prevención de deadlocks en el código eBPF","Detección de condiciones de carrera","Optimización del uso de bloqueos","Compatibilidad con Envoy xDS","Implementación de filtros eBPF"],"fr":["Prévention des deadlocks dans le code eBPF","Détection des conditions de course","Optimisation de l''utilisation des verrous","Compatibilité avec Envoy xDS","Mise en œuvre de filtres eBPF"],"de":["Vermeidung von Deadlocks im eBPF-Code","Erkennung von Race-Bedingungen","Optimierung der Sperrennutzung","Kompatibilität mit Envoy xDS","Implementierung von eBPF-Filtern"],"pt":["Verificação de deadlocks","Prevenção de condições de corrida","Otimização do uso de locks","Compatibilidade com eBPF","Melhoria da segurança do código"],"ru":["Проверка на замки","Предотвращение гонок","Оптимизация использования блокировок","Совместимость с eBPF","Улучшение безопасности кода"],"ar":["فحص الأقفال","منع الظروف التنافسية","تحسين استخدام الأقفال","التأثير مع مرشحات eBPF","تحسين أمان الكود"]},"keywords":{"en":["how to use integrity-checks","integrity-checks alternative to Envoy xDS","what is integrity-checks","integrity-checks setup guide","integrity-checks vs eBPF","integrity-checks install for eBPF filters","deadlock prevention in eBPF","race condition detection in eBPF","integrity-checks for AI agents","eBPF filter optimization"],"zh":["integrity-checks","eBPF 过滤器","Envoy xDS","死锁","竞态条件","AIエージェント","代码可靠性","性能优化"],"ja":["Integrity Checks","eBPF フィルタ","Envoy xDS","デッドロック","レースコンディション","AIエージェント","コードの信頼性","パフォーマンス最適化"],"ko":["integrity-checks","eBPF 필터","Envoy xDS","데드락","경쟁 상태","AI 도구","코드 신뢰성","성능 최적화"],"es":["integrity-checks","eBPF","deadlocks","condiciones de carrera","Envoy xDS","filtros eBPF","desarrollo de software","herramientas de desarrollo","agentes de IA"],"fr":["integrity-checks","eBPF","deadlocks","conditions de course","Envoy xDS","filtres eBPF","développement de logiciels","outils de développement","agents d''IA","outils d''IA"],"de":["integrity-checks","eBPF","Deadlocks","Race-Bedingungen","Envoy xDS","eBPF-Filter","Softwareentwicklung","Entwicklungstools","KI-Agenten","KI-Tools"],"pt":["verificações de integridade","eBPF","deadlocks","condições de corrida","otimização de locks","segurança de código","desenvolvimento de software"],"ru":["проверки целостности","eBPF","замки","гонки","оптимизация блокировок","безопасность кода","разработка программного обеспечения"],"ar":["فحوصات الصحة","eBPF","أقفال","ظروف تنافسية","تحسين الأقفال","أمان الكود","تطوير البرمجيات"]}},"owner":"danthegoodman1","repo":"netfence","repoPath":"danthegoodman1/netfence","stars":87,"forks":2,"updatedAt":"2026-02-22T06:10:53Z","topics":[],"category":"community","skillMd":{"name":"integrity-checks","description":"Integrity checks","bodyPreview":"# Integrity checks\n\nAfter edits, ensure that the new code does not introduce any deadlocks or race conditions. Additionally, do not be wasteful with holding locks when something doesn''t need it.","body":"# Integrity checks\n\nAfter edits, ensure that the new code does not introduce any deadlocks or race conditions. Additionally, do not be wasteful with holding locks when something doesn''t need it.\n"},"lastSynced":"2026-03-06T06:33:13.527Z","agentAnalysis":{"suitability":{"en":"Ideal for Systems Programming Agents requiring eBPF filter optimization and deadlock prevention in Envoy xDS environments.","zh":"适用于需要在 Envoy xDS 环境中进行 eBPF 过滤器优化和死锁预防的系统编程代理。","ja":"Envoy xDS 環境での eBPF フィルタの最適化とデッドロック防止を必要とするシステムプログラミングエージェントに適しています。","ko":"Envoy xDS 환경에서 eBPF 필터 최적화 및 데드락 방지를 요구하는 시스템 프로그래밍 에이전트에 적합합니다.","es":"Ideal para Agentes de Programación de Sistemas que requieren optimización de filtros eBPF y prevención de deadlocks en entornos Envoy xDS.","fr":"Idéal pour les agents de programmation de systèmes nécessitant une optimisation de filtres eBPF et une prévention de deadlocks dans les environnements Envoy xDS.","de":"Ideal für Systemprogrammierungsagenten, die eine Optimierung von eBPF-Filtern und eine Verhinderung von Deadlocks in Envoy-xDS-Umgebungen erfordern.","pt":"Ideal para Agentes de Programação de Sistemas que requerem otimização de filtro eBPF e prevenção de deadlocks em ambientes Envoy xDS.","ru":"Идеально подходит для агентов системного программирования, требующих оптимизации фильтра eBPF и предотвращения deadlock в средах Envoy xDS.","ar":"مثالي لعمليات برمجة النظام التي تتطلب تحسين مرشح eBPF ومنع تعطل الموت في بيئات Envoy xDS."},"recommendation":{"en":"Empowers agents to ensure efficient lock management and prevent race conditions in eBPF filters, guaranteeing reliable and efficient Envoy xDS operations using comprehensive integrity checks and deadlock detection.","zh":"赋予代理确保 eBPF 过滤器中的锁管理效率和防止竞态条件，保证 Envoy xDS 操作的可靠性和效率，使用全面性的完整性检查和死锁检测。","ja":"eBPF フィルタ内のロック管理の効率性と競合状態の防止をエージェントが確保できるようにし、包括的な整合性チェックとデッドロック検出を使用して、Envoy xDS 操作の信頼性と効率性を保証します。","ko":"에이전트가 eBPF 필터의 잠금 관리 효율성과 경쟁 상태 방지를 보장하도록 하여, 포괄적인 무결성 검사와 데드락 감지를 사용하여 Envoy xDS 작업의 신뢰성과 효율성을 보장합니다.","es":"Permite a los agentes garantizar una gestión de bloqueos eficiente y prevenir condiciones de carrera en filtros eBPF, asegurando operaciones Envoy xDS confiables y eficientes mediante controles de integridad comprehensivos y detección de deadlocks.","fr":"Permet aux agents de garantir une gestion de verrous efficace et de prévenir les conditions de course dans les filtres eBPF, assurant des opérations Envoy xDS fiables et efficaces grâce à des contrôles d''intégrité complets et à la détection de deadlocks.","de":"Ermächtigt Agenten, eine effiziente Verwaltung von Sperren sicherzustellen und Rennbedingungen in eBPF-Filtern zu verhindern, um zuverlässige und effiziente Envoy-xDS-Operationen mit umfassenden Integritätsprüfungen und Deadlock-Erkennung zu gewährleisten.","pt":"Habilita os agentes a garantir um gerenciamento de bloqueio eficiente e prevenir condições de corrida em filtros eBPF, garantindo operações Envoy xDS confiáveis e eficientes usando verificações de integridade abrangentes e detecção de deadlock.","ru":"Наделяет агентов возможностью обеспечить эффективное управление блокировками и предотвратить гонку в фильтрах eBPF, гарантируя надежные и эффективные операции Envoy xDS с помощью комплексных проверок целостности и обнаружения deadlock.","ar":"يمكن الوكلاء من ضمان إدارة قفل فعال ومنع حالات السباق في مرشحات eBPF، مما يضمن عمليات Envoy xDS الموثوقة والفعالة باستخدام فحوصات شمولية للسلامة واكتشاف تعطل الموت."},"useCases":{"en":["Debugging eBPF filters for deadlocks","Optimizing lock management in Envoy xDS","Validating eBPF filter integrity after code edits"],"zh":["调试 eBPF 过滤器以防止死锁","在 Envoy xDS 中优化锁管理","代码编辑后验证 eBPF 过滤器完整性"],"ja":["デッドロックの防止のための eBPF フィルタのデバッグ","Envoy xDS でのロック管理の最適化","コード編集後の eBPF フィルタの完全性の検証"],"ko":["데드락을 방지하기 위한 eBPF 필터 디버깅","Envoy xDS에서 잠금 관리 최적화","코드 편집 후 eBPF 필터 무결성 검증"],"es":["Depuración de filtros eBPF para deadlocks","Optimización de la gestión de bloqueos en Envoy xDS","Validación de la integridad de los filtros eBPF después de ediciones de código"],"fr":["Débogage des filtres eBPF pour les deadlocks","Optimisation de la gestion de verrous dans Envoy xDS","Validation de l''intégrité des filtres eBPF après des modifications de code"],"de":["Entfernen von Deadlocks in eBPF-Filtern","Optimierung der Sperrenverwaltung in Envoy xDS","Überprüfung der Integrität von eBPF-Filtern nach Codebearbeitungen"],"pt":["Depuração de filtros eBPF para deadlocks","Otimização do gerenciamento de bloqueio em Envoy xDS","Validação da integridade do filtro eBPF após edições de código"],"ru":["Отладка фильтров eBPF для deadlock","Оптимизация управления блокировками в Envoy xDS","Проверка целостности фильтра eBPF после редактирования кода"],"ar":["تصحيح أخطاء مرشحات eBPF لتعطل الموت","تحسين إدارة القفل في Envoy xDS","التحقق من سلامة مرشح eBPF بعد تحرير الشفرة"]},"limitations":{"en":["Requires eBPF filter access","Envoy xDS compatibility required"],"zh":["需要 eBPF 过滤器访问","需要 Envoy xDS 兼容性"],"ja":["eBPF フィルタへのアクセスが必要","Envoy xDS との互換性が必要"],"ko":["eBPF 필터 접근 필요","Envoy xDS와의 호환성 필요"],"es":["Requiere acceso a filtros eBPF","Se requiere compatibilidad con Envoy xDS"],"fr":["Nécessite un accès aux filtres eBPF","La compatibilité avec Envoy xDS est requise"],"de":["Benötigt Zugriff auf eBPF-Filter","Envoy-xDS-Kompatibilität erforderlich"],"pt":["Requer acesso ao filtro eBPF","Compatibilidade Envoy xDS necessária"],"ru":["Требуется доступ к фильтру eBPF","Требуется совместимость Envoy xDS"],"ar":["يتطلب الوصول إلى مرشح eBPF","مطلوبة توافق Envoy xDS"]},"version":4},"contentHash":"ae6cd7539480d3ef45970850fcf9ca448ecead210e81cd60b980dc90e4ea6cd7","qualityScore":25}');
