INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('space-sunrise/sunrise-station/ss14-graphics-animation-player', 'ss14-graphics-animation-player', 'space-sunrise', 'sunrise-station', 'community', 'ss14-graphics-animation-player space-sunrise sunrise-station community c-sharp game hacktoberfest space-station-13 space-station-14 ss13 ss14 sunrise The ss14-graphics-animation-player skill enables developers to build and animate graphics for Space Station 14 using C#. It benefits game developers and designers working with the Sunrise Station game server. ss14-graphics-animation-player 是一种用于构建 Sunrise Station 服务器的技能，用于游戏 Space Station 14 的图形动画播放。它支持 C# 编程语言。 ss14-graphics-animation-player は、ゲーム Space Station 14 のグラフィックアニメーションを再生するために Sunrise Station サーバーを構築するスキルです。C# プログラミング言語をサポートしています。 ss14-graphics-animation-player는 게임 Space Station 14의 그래픽 애니메이션을 재생하기 위해 Sunrise Station 서버를 구축하는 스킬입니다. C# 프로그래밍 언어를 지원합니다. El ss14-graphics-animation-player es un componente clave para la creación de experiencias de juego inmersivas en Space Station 14. Utiliza C# y Sunrise Station para crear animaciones y gráficos personalizados. Le ss14-graphics-animation-player est un composant essentiel pour la création d''expériences de jeu immersives dans Space Station 14. Il utilise C# et Sunrise Station pour créer des animations et des graphiques personnalisés. Der ss14-graphics-animation-player ist ein wichtiger Bestandteil für die Erstellung von immersiven Spiel-Erfahrungen in Space Station 14. Er verwendet C# und Sunrise Station, um benutzerdefinierte Animationen und Grafiken zu erstellen. O ss14-graphics-animation-player é um agente de animação gráfica para jogos Space Station 14, construído com C# e integrado ao Hacktoberfest. ИИ Агент ss14-graphics-animation-player - это агент анимации графики для игры Space Station 14, построенный на C# и интегрированный с Hacktoberfest. الـ ss14-graphics-animation-player هو وسيط رسومات متحركة للاستفادة من العاب الفضاء 14، مبني على C# ومتوافق مع Hacktoberfest how to use ss14-graphics-animation-player ss14-graphics-animation-player setup guide C# game development for Space Station 14 Sunrise Station game server tutorial ss14-graphics-animation-player vs Space Station 13 install ss14-graphics-animation-player for game development ss14-graphics-animation-player Sunrise Station 服务器 Space Station 14 C# 编程语言 AI 工具 图形动画播放 Cursor Bridge Hacktoberfest Utilizes C# programming language for game development Supports Sunrise Station game server for Space Station 14 Follows source mapping from the Canonical bridge skill file References the SKILL.md file for technical implementation details Integrates with Space Station 14 game environment for graphics animation ss14-graphics-animation-player is a C#-based skill for building and animating graphics in Space Station 14, utilizing the Sunrise Station game server.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TEN-framework/portal/ac-execute', 'community', 'TEN-framework', 'portal', 'TEN-framework/portal', 'ac-execute', 33, 8, 25, '2026-03-04T07:20:39Z', '2026-03-06T06:38:50.795Z', 'd2cc4360a2fbc99ffb04986803df33ace98099fc877f0843001ddcc61661a98b', '{"id":"TEN-framework/portal/ac-execute","name":"ac-execute","description":{"en":"The ac-execute skill enables developers to manage execution contracts efficiently by verifying PLAN_FROZEN and setting CURRENT_ROLE to executor. It benefits developers working with Fumadocs and TEN''s official website.","zh":"ac-execute 是一个用于构建 Official TEN Website 的技能，基于 Fumadocs。它提供了一套详细的步骤来执行和验证计划","ja":"ac-execute は、Official TEN Website を構築するためのスキルです。Fumadocs に基づいています。計画を実行して検証するための詳細な手順を提供します","ko":"ac-execute는 Official TEN Website를 구축하기 위한 스킬로 Fumadocs에 기반합니다. 계획을 실행하고 검증하기 위한 자세한 단계를 제공합니다","es":"ac-execute es una habilidad que permite la ejecución de contratos y la actualización de archivos de manera segura y eficiente. Sigue nuestros pasos para configurarlo","fr":"ac-execute est une compétence qui permet l''exécution de contrats et la mise à jour de fichiers de manière sécurisée et efficace. Suivez nos étapes pour la configurer","de":"ac-execute ist eine Fähigkeit, die die Ausführung von Verträgen und die Aktualisierung von Dateien auf sichere und effiziente Weise ermöglicht. Befolgen Sie unsere Schritte zur Einrichtung","pt":"O ac-execute é um agente de IA que executa contratos de execução, permitindo a automação de tarefas. Ele é configurado para verificar a completude do contrato e executar as etapas necessárias.","ru":"ac-execute - это агент ИИ, который запускает контракты исполнения, позволяя автоматизировать задачи. Он настроен для проверки полноты контракта и выполнения необходимых шагов.","ar":"ac-execute هو وكيل ذكاء اصطناعي ينفذ عقود التنفيذ، مما يسمح بالتأشير التلقائي للمهام. إنه معدة للتحقق من اكتمال العقد وتنفيذ الخطوات الضرورية."},"seo":{"title":{"en":"ac-execute: Execution Contract Setup Guide | AI Agent Skill","zh":"ac-execute Setup Guide: Official TEN Website Builder","ja":"ac-execute セットアップガイド: Official TEN Website Builder with F...","ko":"ac-execute 설정 가이드: TEN 공식 웹사이트 구축","es":"Guía de configuración de ac-execute para Agentes de IA","fr":"Guide de mise en œuvre de ac-execute pour Outils d''IA","de":"Einrichtungsleitfaden für ac-execute in KI-Agents","pt":"Guia de Configuração do ac-execute: Execução de Contratos...","ru":"Настройка ac-execute: Руководство по запуску контрактов и...","ar":"دليل إعداد ac-execute: تنفيذ عقود التنفيذ"},"description":{"en":"Discover how to implement ac-execute for seamless execution contract management. Learn to set CURRENT_ROLE and follow steps for efficient workflow","zh":"了解 ac-execute 的技术细节，用于构建 Official TEN Website 和 Fumadocs","ja":"ac-execute の技術的な詳細を学び、Official TEN Website と Fumadocs を構築する","ko":"ac-execute의 기술적인 세부 사항을 알아보고 Official TEN Website 및 Fumadocs를 구축하세요","es":"Aprende a configurar ac-execute para Agentes de IA con nuestra guía paso a paso y mejora la eficiencia en tus proyectos","fr":"Découvrez comment mettre en œuvre ac-execute pour Outils d''IA avec notre guide étape par étape et améliorez l''efficacité de vos projets","de":"Erfahren Sie, wie Sie ac-execute für KI-Agents einrichten und die Effizienz Ihrer Projekte verbessern","pt":"Aprenda a configurar e executar o ac-execute, um agente de IA para execução de contratos de execução. Descubra como aproveitar ao máximo essa ferramenta.","ru":"Узнайте, как настроить и запустить ac-execute, агент ИИ для запуска контрактов исполнения. Откройте для себя возможности этого инструмента.","ar":"تعرف على كيفية إعداد وتشغيل ac-execute، وهو وكيل ذكاء اصطناعي لتنفيذ عقود التنفيذ. اكتشف كيفية استخدامه بشكل فعال."},"definition":{"en":"ac-execute is a skill that automates the execution contract process, ensuring completeness and accuracy by following specific steps and checks","zh":"ac-execute 是一个用于构建和执行计划的技能，具有特定的步骤和检查","ja":"ac-execute は、特定の手順とチェックを備えた計画を構築して実行するスキルです","ko":"ac-execute는 특정 단계와 검사를 갖춘 계획을 구축하고 실행하기 위한 스킬입니다","es":"ac-execute es una habilidad de Agentes de IA que automatiza la ejecución de contratos y la actualización de archivos","fr":"ac-execute est une compétence d''Outils d''IA qui automatise l''exécution de contrats et la mise à jour de fichiers","de":"ac-execute ist eine Fähigkeit von KI-Agents, die die Ausführung von Verträgen und die Aktualisierung von Dateien automatisiert","pt":"O ac-execute é um agente de IA que executa contratos de execução, automatizando tarefas e melhorando a eficiência.","ru":"ac-execute - это агент ИИ, который запускает контракты исполнения, автоматизируя задачи и повышая эффективность.","ar":"ac-execute هو وكيل ذكاء اصطناعي ينفذ عقود التنفيذ، مما يؤدي إلى التأشير التلقائي للمهام وتحسين الكفاءة."},"features":{"en":["Verifies PLAN_FROZEN and Execution Contract completeness","Sets CURRENT_ROLE to executor for efficient workflow","Changes only specified files in Files to change","Follows exact Steps and runs required Checks","Records results in 验收证据（Evidence） and updates Top 3 completion","Hands off to $ac-review for further processing"],"zh":["验证 PLAN_FROZEN 和 Execution Contract 的完整性","设置 CURRENT_ROLE 为 executor","仅更改 Files to change 中列出的文件","按照 Steps 中的指示运行 required Checks","记录结果并更新 Top 3 完成情况"],"ja":["PLAN_FROZEN と Execution Contract の完全性を検証する","CURRENT_ROLE を executor に設定する","Files to change に列挙されたファイルのみを変更する","Steps に従って必須の Checks を実行する","結果を記録して Top 3 完了状況を更新する"],"ko":["PLAN_FROZEN 및 Execution Contract의 완전성을 검증","CURRENT_ROLE을 executor로 설정","Files to change에 나열된 파일만 변경","Steps에 따라 필수 Checks를 실행","결과를 기록하고 Top 3 완료 상황을 업데이트"],"es":["Verificación de PLAN_FROZEN y contratos de ejecución","Actualización de archivos según la lista de archivos a cambiar","Ejecución de pasos y comprobaciones requeridos","Registro de resultados en el Evidence y actualización del Top 3","Entrega a ac-review y desbloqueo de fallback"],"fr":["Vérification de PLAN_FROZEN et de contrats d''exécution","Mise à jour de fichiers selon la liste des fichiers à modifier","Exécution des étapes et des vérifications requises","Enregistrement des résultats dans l''Evidence et mise à jour du Top 3","Remise à ac-review et déblocage de fallback"],"de":["Überprüfung von PLAN_FROZEN und Ausführungsverträgen","Aktualisierung von Dateien gemäß der Liste der zu ändernden Dateien","Ausführung der Schritte und Überprüfungen","Aufzeichnung der Ergebnisse im Evidence und Aktualisierung des Top 3","Übergabe an ac-review und Freigabe von Fallback"],"pt":["Verificação da completude do contrato de execução","Execução das etapas necessárias para a conclusão do contrato","Gravação dos resultados em ''Evidence''","Atualização do Top 3 de conclusão","Integração com o $ac-review"],"ru":["Проверка полноты контракта исполнения","Выполнение необходимых шагов для завершения контракта","Запись результатов в ''Evidence''","Обновление Top 3 завершения","Интеграция с $ac-review"],"ar":["التحقق من اكتمال عقد التنفيذ","تنفيذ الخطوات الضرورية لإكمال العقد","تسجيل النتائج في ''Evidence''","تحديث أعلى 3 إكمال","التكامل مع $ac-review"]},"keywords":{"en":["how to use ac-execute","ac-execute setup guide","what is ac-execute","ac-execute alternative","ac-execute vs Fumadocs","ac-execute install","ac-execute for TEN website","execution contract management","CURRENT_ROLE setup"],"zh":["ac-execute","Official TEN Website","Fumadocs","AIエージェント","构建网站","计划执行","验证检查"],"ja":["ac-execute","Official TEN Website","Fumadocs","AIエージェント","ウェブサイト構築","計画実行","検証チェック"],"ko":["ac-execute","Official TEN Website","Fumadocs","AI 에이전트","웹사이트 구축","계획 실행","검증 체크"],"es":["ac-execute","Agentes de IA","configuración de ac-execute","ejecución de contratos","actualización de archivos","automatización de procesos","desarrollo de software","tecnologías de IA"],"fr":["ac-execute","Outils d''IA","configuration de ac-execute","exécution de contrats","mise à jour de fichiers","automatisation de processus","développement de logiciels","technologies d''IA"],"de":["ac-execute","KI-Agents","Einrichtung von ac-execute","Ausführung von Verträgen","Aktualisierung von Dateien","Automatisierung von Prozessen","Softwareentwicklung","KI-Technologien"],"pt":["ac-execute","agente de IA","execução de contratos","automação de tarefas","ferramentas de desenvolvimento","desenvolvimento de software","tecnologias de IA"],"ru":["ac-execute","агент ИИ","запуск контрактов","автоматизация задач","инструменты разработки","разработка программного обеспечения","технологии ИИ"],"ar":["ac-execute","وكيل ذكاء اصطناعي","تنفيذ عقود","تأشير تلقائي للمهام","أدوات التطوير","تطوير البرمجيات","تقنيات الذكاء الاصطناعي"]}},"owner":"TEN-framework","repo":"portal","repoPath":"TEN-framework/portal","stars":33,"forks":8,"updatedAt":"2026-03-04T07:20:39Z","topics":[],"category":"community","skillMd":{"name":"ac-execute","description":"Execute a frozen workflow contract and collect evidence by implementing only approved scope/files and checks. Use when PLAN_FROZEN=true and Execution Contract is complete, then hand off to review.","bodyPreview":"1. Verify `PLAN_FROZEN=true` and `Execution Contract` completeness.\n2. Set `CURRENT_ROLE: executor`.\n3. Change only files listed in `Files to change`.\n4. Follow `Steps` exactly and run required `Checks`.\n5. Record results in `验收证据（Evidence）` and update Top 3 completion.\n6. Hand off to `$ac-review`.\n\nUnfreeze fallback (mandatory):\n1. Stop execution immediately when new design/scope appears.\n2. Append a decision log entry with date, decision, and impact.\n3. Set `PLAN_FROZEN: false` and `CURRENT_RO","body":"1. Verify `PLAN_FROZEN=true` and `Execution Contract` completeness.\n2. Set `CURRENT_ROLE: executor`.\n3. Change only files listed in `Files to change`.\n4. Follow `Steps` exactly and run required `Checks`.\n5. Record results in `验收证据（Evidence）` and update Top 3 completion.\n6. Hand off to `$ac-review`.\n\nUnfreeze fallback (mandatory):\n1. Stop execution immediately when new design/scope appears.\n2. Append a decision log entry with date, decision, and impact.\n3. Set `PLAN_FROZEN: false` and `CURRENT_ROLE: planner`.\n4. Return to `$ac-plan` for a new Contract.\n\nHard rules:\n- Do not add design alternatives during execution.\n- Do not edit files outside the Contract scope.\n"},"lastSynced":"2026-03-06T06:38:50.795Z","agentAnalysis":{"suitability":{"en":"Ideal for Contract Management Agents requiring efficient execution contract verification and role management.","zh":"适合需要高效执行合同验证和角色管理的合同管理代理。","ja":"契約管理エージェントが効率的な契約の検証と役割管理を必要とする場合に最適です。","ko":"계약 관리 에이전트가 효율적인 계약 검증 및 역할 관리를 필요로 할 때 적합합니다.","es":"Ideal para agentes de gestión de contratos que requieren una ejecución eficiente de la verificación de contratos y la gestión de roles.","fr":"Idéal pour les agents de gestion de contrats nécessitant une exécution efficace de la vérification de contrats et de la gestion de rôles.","de":"Ideal für Vertragsmanagement-Agenten, die eine effiziente Ausführung der Vertragsverifizierung und Rollenverwaltung erfordern.","pt":"Ideal para Agentes de Gerenciamento de Contratos que exigem execução eficiente de verificação de contrato e gerenciamento de funções.","ru":"Идеально для агентов управления контрактами, требующих эффективного выполнения проверки контракта и управления ролями.","ar":"مثالي للوكلاء إدارة العقود الذين يتطلبون تنفيذا فعالا للتحقق من العقد وإدارة الأدوار."},"recommendation":{"en":"Empowers agents to verify PLAN_FROZEN and manage CURRENT_ROLE settings, ensuring seamless execution contract handling and compliance with protocols like Fumadocs and TEN''s official website, while following specific steps and checks.","zh":"赋予代理人验证 PLAN_FROZEN 和管理 CURRENT_ROLE 设置的能力，确保无缝的执行合同处理和遵守 Fumadocs 和 TEN 官方网站等协议，同时遵循特定的步骤和检查。","ja":"エージェントが PLAN_FROZEN を検証し、CURRENT_ROLE 設定を管理する能力を提供し、Fumadocs や TEN 公式ウェブサイトなどのプロトコルに準拠しながら、特定の手順とチェックに従った実行契約の処理とハンドリングを円滑にします。","ko":"에이전트가 PLAN_FROZEN을 검증하고 CURRENT_ROLE 설정을 관리할 수 있는 능력을 제공하여 Fumadocs 및 TEN 공식 웹사이트 등의 프로토콜을 준수하면서 특정 단계 및 조사를 따르는 실행 계약 처리 및 컴플라이언스를 원활하게 합니다.","es":"Habilita a los agentes a verificar PLAN_FROZEN y gestionar la configuración de CURRENT_ROLE, asegurando una ejecución de contratos sin problemas y el cumplimiento de protocolos como Fumadocs y el sitio web oficial de TEN, siguiendo pasos y controles específicos.","fr":"Permet aux agents de vérifier PLAN_FROZEN et de gérer les paramètres de CURRENT_ROLE, assurant une exécution de contrats sans heurts et le respect des protocoles tels que Fumadocs et le site Web officiel de TEN, en suivant des étapes et des vérifications spécifiques.","de":"Ermächtigt Agenten, PLAN_FROZEN zu überprüfen und CURRENT_ROLE-Einstellungen zu verwalten, um eine reibungslose Vertragsausführung und die Einhaltung von Protokollen wie Fumadocs und der offiziellen Website von TEN sicherzustellen, indem sie bestimmte Schritte und Kontrollen befolgen.","pt":"Habilita os agentes a verificar PLAN_FROZEN e gerenciar configurações de CURRENT_ROLE, garantindo tratamento de contrato de execução sem problemas e conformidade com protocolos como Fumadocs e site oficial da TEN, seguindo etapas e verificações específicas.","ru":"Наделяет агентов возможностью проверять PLAN_FROZEN и управлять настройками CURRENT_ROLE, обеспечивая бесперебойное выполнение контракта и соблюдение протоколов, таких как Fumadocs и официальный сайт TEN, при соблюдении определенных шагов и проверок.","ar":"يمنح الوكلاء التحقق من PLAN_FROZEN وإدارة إعدادات CURRENT_ROLE، مما يضمن التعامل السلس مع عقود التنفيذ والامتثال لبروتوكولات مثل Fumadocs وموقع TEN الرسمي، متبعة خطوات وعمليات التحقق المحددة."},"useCases":{"en":["Verifying PLAN_FROZEN and execution contract completeness","Automating CURRENT_ROLE setting to executor","Updating evidence records and Top 3 completion","Handling unfreeze fallback for new design or scope changes"],"zh":["验证 PLAN_FROZEN 和执行合同的完整性","自动将 CURRENT_ROLE 设置为执行者","更新证据记录和 Top 3 完成情况","处理新设计或范围变化的解冻回退"],"ja":["PLAN_FROZEN と実行契約の完全性を検証する","CURRENT_ROLE を実行者に自動的に設定する","証拠レコードと Top 3 完了状況を更新する","新しいデザインまたは範囲の変更のために凍結を回避する"],"ko":["PLAN_FROZEN 및 실행 계약의 완전성을 검증하는 것","CURRENT_ROLE을 실행자로 자동 설정하는 것","증거 기록 및 Top 3 완료 상황을 업데이트하는 것","새로운 디자인 또는 범위 변경에 대한 해동 대책을 취하는 것"],"es":["Verificar PLAN_FROZEN y la completitud del contrato de ejecución","Automatizar la configuración de CURRENT_ROLE al ejecutor","Actualizar registros de evidencia y completar los 3 mejores","Gestionar la reversión de desbloqueo para nuevos diseños o cambios de alcance"],"fr":["Vérifier PLAN_FROZEN et l''exhaustivité du contrat d''exécution","Automatiser la configuration de CURRENT_ROLE à l''exécuteur","Mettre à jour les enregistrements de preuve et compléter les 3 meilleurs","Gérer le retour en arrière pour de nouveaux designs ou des changements de portée"],"de":["Überprüfen von PLAN_FROZEN und Vollständigkeit des Ausführungsvertrags","Automatisieren der CURRENT_ROLE-Einstellung zum Ausführenden","Aktualisieren von Beweisunterlagen und Vervollständigen der Top 3","Verwalten des Aufhebens für neue Designs oder Änderungen des Umfangs"],"pt":["Verificar PLAN_FROZEN e completude do contrato de execução","Automatizar definição de CURRENT_ROLE para executor","Atualizar registros de evidências e conclusão dos 3 principais","Lidar com fallback de descongelamento para novos designs ou alterações de escopo"],"ru":["Проверка PLAN_FROZEN и полноты контракта выполнения","Автоматизация установки CURRENT_ROLE наexecutor","Обновление записей доказательств и завершение трех основных","Обработка отступа от разморозки для новых дизайнов или изменений объема"],"ar":["التحقق من PLAN_FROZEN واكتمال عقد التنفيذ","تأتمة تعيين CURRENT_ROLE إلى المنفذ","تحديث سجلات الأدلة واكتمال الثلاثة الأولى","التعامل مع الإرجاع عن إلغاء التجميد لتصاميم جديدة أو تغييرات في النطاق"]},"limitations":{"en":["Requires access to specific files and variables like PLAN_FROZEN and CURRENT_ROLE","Must follow exact steps and checks as outlined","Limited to execution contract management within Fumadocs and TEN''s ecosystem"],"zh":["需要访问特定的文件和变量，如 PLAN_FROZEN 和 CURRENT_ROLE","必须按照概述的确切步骤和检查进行","仅限于 Fumadocs 和 TEN 生态系统内的执行合同管理"],"ja":["特定のファイルや変数 (PLAN_FROZEN や CURRENT_ROLE など) にアクセスする必要がある","概説された正確な手順とチェックに従う必要がある","Fumadocs や TEN エコシステム内での実行契約管理のみに限定される"],"ko":["특정 파일 및 변수(PLAN_FROZEN, CURRENT_ROLE 등)에 접근해야 함","概요된 정확한 단계 및 조사에 따라야 함","Fumadocs 및 TEN 생태계 내의 실행 계약 관리에만 제한됨"],"es":["Requiere acceso a archivos y variables específicos como PLAN_FROZEN y CURRENT_ROLE","Debe seguir los pasos y controles exactos descritos","Limitado a la gestión de contratos de ejecución dentro de Fumadocs y el ecosistema de TEN"],"fr":["Nécessite l''accès à des fichiers et des variables spécifiques tels que PLAN_FROZEN et CURRENT_ROLE","Doit suivre les étapes et les vérifications exactes décrites","Limité à la gestion des contrats d''exécution au sein de Fumadocs et de l''écosystème de TEN"],"de":["Erfordert Zugriff auf bestimmte Dateien und Variablen wie PLAN_FROZEN und CURRENT_ROLE","Muss die genauen Schritte und Kontrollen befolgen, wie beschrieben","Begrenzt auf die Verwaltung von Ausführungsverträgen innerhalb von Fumadocs und dem TEN-Ökosystem"],"pt":["Exige acesso a arquivos e variáveis específicos como PLAN_FROZEN e CURRENT_ROLE","Deve seguir etapas e verificações exatas como delineadas","Limitado ao gerenciamento de contrato de execução dentro do ecossistema da Fumadocs e da TEN"],"ru":["Требует доступа к определенным файлам и переменным, таким как PLAN_FROZEN и CURRENT_ROLE","Должно следовать точным шагам и проверкам, как это описано","Ограничен управлением контрактом выполнения в рамках экосистемы Fumadocs и TEN"],"ar":["يتطلب الوصول إلى ملفات ومتغيرات محددة مثل PLAN_FROZEN و CURRENT_ROLE","يجب اتباع خطوات وعمليات التحقق الدقيقة كما هو محدد","محدود بإدارة عقد التنفيذ داخل نظام Fumadocs و TEN"]},"version":4},"contentHash":"d2cc4360a2fbc99ffb04986803df33ace98099fc877f0843001ddcc61661a98b","qualityScore":25}');
