INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TEN-framework/portal/ac-execute', 'ac-execute', 'TEN-framework', 'portal', 'community', 'ac-execute TEN-framework portal community The ac-execute skill enables developers to manage execution contracts efficiently by verifying PLAN_FROZEN and setting CURRENT_ROLE to executor. It benefits developers working with Fumadocs and TEN''s official website. ac-execute 是一个用于构建 Official TEN Website 的技能，基于 Fumadocs。它提供了一套详细的步骤来执行和验证计划 ac-execute は、Official TEN Website を構築するためのスキルです。Fumadocs に基づいています。計画を実行して検証するための詳細な手順を提供します ac-execute는 Official TEN Website를 구축하기 위한 스킬로 Fumadocs에 기반합니다. 계획을 실행하고 검증하기 위한 자세한 단계를 제공합니다 ac-execute es una habilidad que permite la ejecución de contratos y la actualización de archivos de manera segura y eficiente. Sigue nuestros pasos para configurarlo ac-execute est une compétence qui permet l''exécution de contrats et la mise à jour de fichiers de manière sécurisée et efficace. Suivez nos étapes pour la configurer ac-execute ist eine Fähigkeit, die die Ausführung von Verträgen und die Aktualisierung von Dateien auf sichere und effiziente Weise ermöglicht. Befolgen Sie unsere Schritte zur Einrichtung O ac-execute é um agente de IA que executa contratos de execução, permitindo a automação de tarefas. Ele é configurado para verificar a completude do contrato e executar as etapas necessárias. ac-execute - это агент ИИ, который запускает контракты исполнения, позволяя автоматизировать задачи. Он настроен для проверки полноты контракта и выполнения необходимых шагов. ac-execute هو وكيل ذكاء اصطناعي ينفذ عقود التنفيذ، مما يسمح بالتأشير التلقائي للمهام. إنه معدة للتحقق من اكتمال العقد وتنفيذ الخطوات الضرورية. how to use ac-execute ac-execute setup guide what is ac-execute ac-execute alternative ac-execute vs Fumadocs ac-execute install ac-execute for TEN website execution contract management CURRENT_ROLE setup ac-execute Official TEN Website Fumadocs AIエージェント 构建网站 计划执行 验证检查 Verifies PLAN_FROZEN and Execution Contract completeness Sets CURRENT_ROLE to executor for efficient workflow Changes only specified files in Files to change Follows exact Steps and runs required Checks Records results in 验收证据（Evidence） and updates Top 3 completion Hands off to $ac-review for further processing ac-execute is a skill that automates the execution contract process, ensuring completeness and accuracy by following specific steps and checks');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danilonovaisv/PORTFOLIO-DANILO-FINAL/nextjs-best-practices', 'community', 'danilonovaisv', 'PORTFOLIO-DANILO-FINAL', 'danilonovaisv/PORTFOLIO-DANILO-FINAL', 'nextjs-best-practices', 1, 0, 25, '2026-03-06T01:57:05Z', '2026-03-06T13:11:12.454Z', '40b71b0b1a922899ff3fb7c444b6b36f2273bf92070cf55f1fa107502f044db5', '{"id":"danilonovaisv/PORTFOLIO-DANILO-FINAL/nextjs-best-practices","name":"nextjs-best-practices","description":{"en":"The nextjs-best-practices skill provides developers with principles for Next.js App Router development, covering key topics such as server vs client components and data flow optimization.","zh":"Next.js 最佳实践是指在构建 Next.js 应用时需要遵循的原则和指南，包括 Server vs Client 组件、路由组织和数据流等","ja":"Next.js ベストプラクティスは、Next.js アプリケーションを構築する際に従うべき原則とガイドラインです","ko":"Next.js 최적화는 Next.js 애플리케이션을 개발할 때 따라야 하는 원칙과 지침입니다","es":"Next.js es un framework para desarrollar aplicaciones web escalables y eficientes. Aprende a configurar Next.js con las mejores prácticas para un desarrollo de aplicaciones óptimo","fr":"Next.js est un framework pour développer des applications web évolutives et efficaces. Découvrez comment configurer Next.js avec les meilleures pratiques pour un développement d''applications optimal","de":"Next.js ist ein Framework für die Entwicklung von skalierbaren und effizienten Webanwendungen. Erfahren Sie, wie Sie Next.js mit Best Practices für eine optimale App-Entwicklung konfigurieren","pt":"As melhores práticas do Next.js para desenvolver aplicativos escaláveis e eficientes, com foco em roteamento e gerenciamento de dados","ru":"Лучшие практики Next.js для разработки масштабируемых и эффективных приложений, с фокусом на маршрутизации и управлении данными","ar":"أفضل الممارسات ل Next.js لتطوير تطبيقات قابلة للتحجيم وفعالة، مع التركيز على التوجيه وإدارة البيانات"},"seo":{"title":{"en":"nextjs-best-practices: Best Practices for Next.js App Rou...","zh":"Next.js 最佳实践指南 - 优化应用性能","ja":"Next.js ベストプラクティス - AIエージェントを使用したアプリケーションの最適化","ko":"Next.js 최적화 가이드 - 개발자 위한 최고의 实践","es":"Guía de configuración de Next.js con mejores prácticas de...","fr":"Configurer Next.js avec les meilleures pratiques de routage","de":"Next.js-Setup mit Best Practices für App-Router-Entwicklung","pt":"Melhores Práticas do Next.js: Guia de Configuração","ru":"Лучшие практики Next.js: Настройка и разработка","ar":"أفضل الممارسات ل Next.js: إعداد وتطوير"},"description":{"en":"Unlock efficient Next.js development with our expert guide to App Router best practices - learn how to optimize your workflow and improve performance today!","zh":"了解 Next.js 应用的最佳实践，包括 Server vs Client 组件、路由组织和数据流等，优化您的应用性能","ja":"Next.js ベストプラクティスを学ぶ - AIエージェントを使用してアプリケーションのパフォーマンスを最適化する","ko":"Next.js 애플리케이션을 최적화하는 방법을 알아보세요 - 서버 대 클라이언트 구성 요소, 라우팅 및 데이터 흐름 등","es":"Aprende a configurar Next.js con las mejores prácticas para un desarrollo de aplicaciones escalables y eficientes","fr":"Découvrez comment configurer Next.js avec les meilleures pratiques pour un développement d''applications évolutives et efficaces","de":"Erfahren Sie, wie Sie Next.js mit Best Practices für eine skalierbare und effiziente App-Entwicklung konfigurieren","pt":"Aprenda as melhores práticas para desenvolver aplicativos Next.js escaláveis e eficientes, incluindo roteamento e gerenciamento de dados","ru":"Узнайте лучшие практики для разработки масштабируемых и эффективных приложений Next.js, включая маршрутизацию и управление данными","ar":"تعلم أفضل الممارسات لتطوير تطبيقات Next.js القابلة للتحجيم والفعالة، بما في ذلك التوجيه وإدارة البيانات"},"definition":{"en":"nextjs-best-practices is a set of guidelines for developing efficient and scalable Next.js applications using the App Router, covering aspects like decision trees and file conventions.","zh":"Next.js 最佳实践是指在构建 Next.js 应用时需要遵循的原则和指南","ja":"Next.js ベストプラクティスとは、Next.js アプリケーションを構築する際に従うべき原則とガイドラインのこと","ko":"Next.js 최적화는 Next.js 애플리케이션을 개발할 때 따라야 하는 원칙과 지침","es":"Las mejores prácticas de Next.js son principios para desarrollar aplicaciones web escalables y eficientes con el framework Next.js","fr":"Les meilleures pratiques de Next.js sont des principes pour développer des applications web évolutives et efficaces avec le framework Next.js","de":"Die Best Practices von Next.js sind Prinzipien für die Entwicklung von skalierbaren und effizienten Webanwendungen mit dem Next.js-Framework","pt":"As melhores práticas do Next.js são um conjunto de diretrizes para desenvolver aplicativos escaláveis e eficientes","ru":"Лучшие практики Next.js - это набор руководств для разработки масштабируемых и эффективных приложений","ar":"أفضل الممارسات ل Next.js هي مجموعة من الإرشادات لتطوير تطبيقات قابلة للتحجيم وفعالة"},"features":{"en":["Utilizes Decision Tree modules for informed development decisions","Applies By Default principles for streamlined component rendering","Supports Fetch Strategy optimization for improved data loading","Enables efficient Data Flow management for complex applications","Follows File Conventions for organized and maintainable codebases","Facilitates Route Organization for intuitive and scalable routing"],"zh":["Server vs Client 组件","路由组织和数据流","Fetch Strategy 和数据获取","File Conventions 和代码组织","Route Organization 和路由管理","Decision Tree 和逻辑决策"],"ja":["サーバー vs クライアント コンポーネント","ルーティングとデータ フロー","フェッチ戦略とデータ取得","ファイル規約とコード組織","ルート組織とルーティング管理","デシジョン ツリーとロジック デシジョン"],"ko":["서버 대 클라이언트 구성 요소","라우팅 및 데이터 흐름","페치 전략 및 데이터 가져오기","파일 규칙 및 코드 조직","라우트 조직 및 라우팅 관리","결정 트리 및 논리 결정"],"es":["Componentes del servidor vs cliente","Estrategias de recuperación de datos","Flujo de datos eficiente","Convenciones de archivos y organización de rutas","Árbol de decisión para la elección de componentes","Configuración por defecto para una implementación rápida"],"fr":["Composants serveur vs client","Stratégies de récupération de données","Flux de données efficace","Conve