INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danilonovaisv/PORTFOLIO-DANILO-FINAL/nextjs-best-practices', 'nextjs-best-practices', 'danilonovaisv', 'PORTFOLIO-DANILO-FINAL', 'community', 'nextjs-best-practices danilonovaisv PORTFOLIO-DANILO-FINAL community The nextjs-best-practices skill provides developers with principles for Next.js App Router development, covering key topics such as server vs client components and data flow optimization. Next.js 最佳实践是指在构建 Next.js 应用时需要遵循的原则和指南，包括 Server vs Client 组件、路由组织和数据流等 Next.js ベストプラクティスは、Next.js アプリケーションを構築する際に従うべき原則とガイドラインです Next.js 최적화는 Next.js 애플리케이션을 개발할 때 따라야 하는 원칙과 지침입니다 Next.js es un framework para desarrollar aplicaciones web escalables y eficientes. Aprende a configurar Next.js con las mejores prácticas para un desarrollo de aplicaciones óptimo Next.js est un framework pour développer des applications web évolutives et efficaces. Découvrez comment configurer Next.js avec les meilleures pratiques pour un développement d''applications optimal Next.js ist ein Framework für die Entwicklung von skalierbaren und effizienten Webanwendungen. Erfahren Sie, wie Sie Next.js mit Best Practices für eine optimale App-Entwicklung konfigurieren As melhores práticas do Next.js para desenvolver aplicativos escaláveis e eficientes, com foco em roteamento e gerenciamento de dados Лучшие практики Next.js для разработки масштабируемых и эффективных приложений, с фокусом на маршрутизации и управлении данными أفضل الممارسات ل Next.js لتطوير تطبيقات قابلة للتحجيم وفعالة، مع التركيز على التوجيه وإدارة البيانات how to use nextjs-best-practices nextjs-best-practices setup guide what is nextjs-best-practices nextjs-best-practices vs react nextjs-best-practices alternative nextjs-best-practices install nextjs app router development nextjs server vs client components nextjs data flow optimization Next.js 最佳实践 Server vs Client 组件 路由组织 数据流 Fetch Strategy File Conventions Route Organization Decision Tree Next.js 性能优化 Utilizes Decision Tree modules for informed development decisions Applies By Default principles for streamlined component rendering Supports Fetch Strategy optimization for improved data loading Enables efficient Data Flow management for complex applications Follows File Conventions for organized and maintainable codebases Facilitates Route Organization for intuitive and scalable routing nextjs-best-practices is a set of guidelines for developing efficient and scalable Next.js applications using the App Router, covering aspects like decision trees and file conventions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RMF112018/Project-Controls/Schedule Performance Optimization', 'community', 'RMF112018', 'Project-Controls', 'RMF112018/Project-Controls', 'Schedule Performance Optimization', 0, 0, 25, '2026-02-22T10:05:07Z', '2026-03-07T04:09:18.640Z', '346a228310fc1ecb2eb6855ba461517cab380f72b942b1cd4e776de073b6a529', '{"id":"RMF112018/Project-Controls/Schedule Performance Optimization","name":"Schedule Performance Optimization","description":{"en":"Schedule Performance Optimization enhances large schedule performance for AI agents by applying optimization guides and offloading work to Web Workers. It benefits developers working with complex scheduling systems.","zh":"调度性能优化技能涉及应用性能优化指南、虚拟化和Web Workers来优化大规模调度的性能","ja":"スケジュール性能最適化スキルには、大規模スケジュールのパフォーマンスを最適化するために、パフォーマンス最適化ガイド、仮想化、Web Workersを適用することが含まれます","ko":"스케줄 성능 최적화 기능에는 대규모 스케줄의 성능을 최적화하기 위해 성능 최적화 가이드, 가상화, Web Workers를 적용하는 것이 포함됩니다","es":"La optimización de rendimiento de programación implica aplicar guías de optimización de rendimiento y virtualizar superficies para mejorar el rendimiento","fr":"L''optimisation des performances de planification consiste à appliquer des guides d''optimisation des performances et à virtualiser des surfaces pour améliorer les performances","de":"Die Terminplan-Performance-Optimierung beinhaltet die Anwendung von Leistungsoptimierungsleitfäden und die Virtualisierung von Oberflächen, um die Leistung zu verbessern","pt":"Otimização de desempenho de agendamento é uma habilidade que melhora a eficiência de agendas grandes. Isso é alcançado através da aplicação de diretrizes de otimização de desempenho e da utilização de tecnologias como Web Workers.","ru":"Оптимизация производительности расписания - это навык, который улучшает эффективность больших расписаний. Это достигается за счет применения руководств по оптимизации производительности и использования технологий, таких как Web Workers.","ar":"تحسين أداء الجدولة هو مهارة تهدف إلى تحسين كفاءة الجداول الكبيرة. يتم تحقيق ذلك من خلال تطبيق إرشادات تحسين الأداء واستخدام تقنيات مثل Web Workers."},"seo":{"title":{"en":"Schedule Performance Optimization: Setup Guide for AI Agents","zh":"AI工具调度性能优化设置指南","ja":"AIエージェントのスケジュール性能最適化ガイド","ko":"AI 에이전트 스케줄 성능 최적화 설정 가이드","es":"Optimización de Rendimiento de Programación: Guía de Conf...","fr":"Optimisation des Performances de Planification: Meilleure...","de":"Terminplan-Performance-Optimierung: Einrichtungsleitfaden","pt":"Otimização de Desempenho de Agendamento: Guia de Configur...","ru":"Оптимизация Производительности Расписания: Настройка с ИИ...","ar":"تحسين أداء الجدولة: دليل الإعداد باستخدام أدوات ذكاء اصطناعي"},"description":{"en":"Unlock faster scheduling with our expert guide to performance optimization. Learn how to apply PERFORMANCE_OPTIMIZATION_GUIDE.md and boost your AI agent''s ef...","zh":"提高大规模调度性能，通过应用性能优化指南、虚拟化和Web Workers来优化性能","ja":"大規模スケジュールのパフォーマンスを向上させるために、パフォーマンス最適化ガイド、仮想化、Web Workersを適用してパフォーマンスを最適化します","ko":"대규모 스케줄 성능 향상을 위해 성능 최적화 가이드, 가상화, Web Workers를 적용하여 성능을 최적화합니다","es":"Aprende a optimizar el rendimiento de tus programaciones con nuestra guía de configuración y mejores prácticas para herramientas de inteligencia artificial","fr":"Découvrez comment optimiser les performances de vos planifications avec notre guide de configuration et les meilleures pratiques pour les outils d''intelligen...","de":"Erfahren Sie, wie Sie die Leistung Ihrer Terminpläne optimieren können, mit unserer Einrichtungsanleitung und den besten Praktiken für KI-Tools","pt":"Aprenda a otimizar o desempenho de agendamento com nosso guia de configuração, incluindo virtualização de superfícies e uso de Web Workers para melhorar a ef...","ru":"Узнайте, как оптимизировать производительность расписания с нашим руководством по настройке, включая виртуализацию поверхностей и использование Web Workers д...","ar":"تعرف على كيفية تحسين أداء الجدولة باستخدام دليل الإعداد الخاص بنا، بما في ذلك توفير السطوح وتحويل العمل الشاق إلى Web Workers لتحسين الكفاءة."},"definition":{"en":"Schedule Performance Optimization is a skill that applies specific protocols to optimize large schedule performance, including virtualizing surfaces and measuring performance with Profiler and bundle analyzer.","zh":"调度性能优化是指优化大规模调度的性能，以提高系统的效率和响应速度","ja":"スケジュール性能最適化とは、大規模スケジュールのパフォーマンスを最適化して、システムの効率と応答速度を向上させることです","ko":"스케줄 성능 최적화는 대규모 스케줄의 성능을 최적화하여 시스템의 효율과 응답 속도를 향상시키는 것을 의미합니다","es":"La optimización de rendimiento de programación es una técnica para mejorar el rendimiento de grandes programaciones","fr":"L''optimisation des performances de planification est une technique pour améliorer les performances de grandes planifications","de":"Die Terminplan-Performance-Optimierung ist eine Technik zur Verbesserung der Leistung von großen Terminplänen","pt":"Otimização de desempenho de agendamento é uma técnica que visa melhorar a eficiência de agendas grandes através da aplicação de diretrizes de otimização e uso de tecnologias específicas.","ru":"Оптимизация производительности расписания - это техника, направленная на улучшение эффективности больших расписаний посредством применения руководств по оптимизации и использования конкретных технологий.","ar":"تحسين أداء الجدولة هو تقنية تهدف إلى تحسين كفاءة الجداول الكبيرة من خلال تطبيق إرشادات تحسين الأداء واستخدام تقنيات محددة."},"features":{"en":["Applies PERFORMANCE_OPTIMIZATION_GUIDE.md §2 verbatim for optimized performance","Virtualizes all qualifying surfaces for improved efficiency","Offloads heavy work to Web Workers for enhanced productivity","Measures before/after performance with Profiler and bundle analyzer for data-driven optimization","Enforces npm run verify:sprint3 for verified performance"],"zh":["应用性能优化指南","虚拟化所有合格的表面","将重负荷工作卸载到Web Workers","使用Profiler和bundle analyzer进行性能测量","执行npm run verify:sprint3"],"ja":["パフォーマンス最適化ガイドの適用","すべての適格な表面の仮想化","重い作業のWeb Workersへのオフロード","Profilerとbundle analyzerを使用したパフォーマンス測定","npm run verify:sprint3の実行"],"ko":["성능 최적화 가이드의 적용","모든 적격 표면의 가상화","무거운 작업의 Web Workers로의 오프로드","Profiler와 bundle analyzer를 사용한 성능 측정","npm run verify:sprint3의 실행"],"es":["Aplicación de guías de optimización de rendimiento","Virtualización de superficies","Uso de Web Workers para tareas pesadas","Medición del rendimiento con Profiler y análisis de paquetes","Verificación con npm run verify:sprint3"],"fr":["Application de guides d''optimisation des performances","Virtualisation de surfaces","Utilisation de Web Workers pour les tâches lourdes","Mesure des performances avec Profiler et analyse de paquets","Vérification avec npm run verify:sprint3"],"de":["Anwendung von Leistungsoptimierungsleitfäden","Virtualisierung von Oberflächen","Verwendung von Web Workers für schwere Aufgaben","Leistungsmessung mit Profiler und Paketanalyse","Verifizierung mit npm run verify:sprint3"],"pt":["Aplicação de diretrizes de otimização de desempenho","Virtualização de superfícies qualificadas","Uso de Web Workers para offload de trabalho pesado","Medição de desempenho com Profiler e bundle analyzer","Verificação de sprint com npm run verify:sprint3"],"ru":["Применение руководств по оптимизации производительности","Виртуализация квалифицированных поверхностей","Использование Web Workers для offload тяжелой работы","Измерение производительности с помощью Profiler и bundle analyzer","Проверка спринта с помощью npm run verify:sprint3"],"ar":["تطبيق إرشادات تحسين الأداء","توفير السطوح المؤهلة","استخدام Web Workers لتحويل العمل الشاق","قياس الأداء باستخدام Profiler وbundle analyzer","التحقق من سباق مع npm run verify:sprint3"]},"keywords":{"en":["how to use Schedule Performance Optimization","Schedule Performance Optimization setup guide","what is Schedule Performance Optimization","Schedule Performance Optimization vs other optimization techniques","Schedule Performance Optimization install","PERFORMANCE_OPTIMIZATION_GUIDE.md implementation","Web Workers for performance optimization","Profiler and bundle analyzer for performance measurement"],"zh":["AI工具","调度性能优化","性能优化指南","虚拟化","Web Workers","Profiler","bundle analyzer","npm run verify:sprint3"],"ja":["AIエージェント","スケジュール性能最適化","パフォーマンス最適化ガイド","仮想化","Web Workers","Profiler","bundle analyzer","npm run verify:sprint3"],"ko":["AI 에이전트","스케줄 성능 최적화","성능 최적화 가이드","가상화","Web Workers","Profiler","bundle analyzer","npm run verify:sprint3"],"es":["optimización de rendimiento de programación","herramientas de inteligencia artificial","guías de optimización de rendimiento","virtualización de superficies","Web Workers","Profiler","análisis de paquetes","npm run verify:sprint3"],"fr":["optimisation des performances de planification","outils d''intelligence artificielle","guides d''optimisation des performances","virtualisation de surfaces","Web Workers","Profiler","analyse de paquets","npm run verify:sprint3"],"de":["Terminplan-Performance-Optimierung","KI-Tools","Leistungsoptimierungsleitfäden","Virtualisierung von Oberflächen","Web Workers","Profiler","Paketanalyse","npm run verify:sprint3"],"pt":["otimização de desempenho de agendamento","ferramentas de IA para agendamento","virtualização de superfícies","Web Workers para agendamento","Profiler e bundle analyzer","npm run verify:sprint3","desempenho de agendamento","agendamento eficiente"],"ru":["оптимизация производительности расписания","ИИ Агенты для расписания","виртуализация поверхностей","Web Workers для расписания","Profiler и bundle analyzer","npm run verify:sprint3","производительность расписания","эффективное расписание"],"ar":["تحسين أداء الجدولة","أدوات ذكاء اصطناعي للجدولة","توفير السطوح","Web Workers للجدولة","Profiler وbundle analyzer","npm run verify:sprint3","أداء الجدولة","جدولة فعالة"]}},"owner":"RMF112018","repo":"Project-Controls","repoPath":"RMF112018/Project-Controls","stars":0,"forks":0,"updatedAt":"2026-02-22T10:05:07Z","topics":[],"category":"community","skillMd":{"name":"Schedule Performance Optimization","description":"Extreme-scale optimization for 10k+ activity schedules under bundle and React 18 constraints","version":"1.0","bodyPreview":"# Schedule Performance Optimization Skill\n\n**Activation**  \nAny performance discussion specific to large schedules.\n\n**Protocol**  \n1. Apply `PERFORMANCE_OPTIMIZATION_GUIDE.md` §2 verbatim.  \n2. Virtualize all qualifying surfaces.  \n3. Offload heavy work to Web Workers.  \n4. Measure before/after with Profiler + bundle analyzer.  \n5. Enforce `npm run verify:sprint3`.\n\nReference: `PERFORMANCE_OPTIMIZATION_GUIDE.md` §1 risks.","body":"# Schedule Performance Optimization Skill\n\n**Activation**  \nAny performance discussion specific to large schedules.\n\n**Protocol**  \n1. Apply `PERFORMANCE_OPTIMIZATION_GUIDE.md` §2 verbatim.  \n2. Virtualize all qualifying surfaces.  \n3. Offload heavy work to Web Workers.  \n4. Measure before/after with Profiler + bundle analyzer.  \n5. Enforce `npm run verify:sprint3`.\n\nReference: `PERFORMANCE_OPTIMIZATION_GUIDE.md` §1 risks."},"lastSynced":"2026-03-07T04:09:18.640Z","agentAnalysis":{"suitability":{"en":"Perfect for Complex Scheduling Agents needing enhanced performance optimization capabilities through Web Workers and optimization guides.","zh":"非常适合需要通过 Web Workers 和优化指南提高性能优化能力的复杂调度代理","ja":"Web Workers と最適化ガイドを通じてパフォーマンス最適化能力を強化する必要がある複雑なスケジューリング エージェントに最適","ko":"Web Workers와 최적화 가이드를 통해 성능 최적화 기능을 향상해야 하는 복잡한 스케줄링 에이전트에 적합","es":"Perfecto para Agentes de Programación Compleja que necesitan capacidades de optimización de rendimiento mejoradas a través de Web Workers y guías de optimización.","fr":"Parfait pour les Agents de Planification Complexes ayant besoin de capacités d''optimisation de performances améliorées via Web Workers et des guides d''optimisation.","de":"Perfekt für komplexe Scheduling-Agents, die erweiterte Leistungsoptimierungsfähigkeiten durch Web Workers und Optimierungsleitfäden benötigen.","pt":"Perfeito para Agentes de Agendamento Complexos que precisam de capacidades de otimização de desempenho aprimoradas por meio de Web Workers e guias de otimização.","ru":"Идеально подходит для сложных агентов планирования, которым необходимы улучшенные возможности оптимизации производительности с помощью Web Workers и руководств по оптимизации.","ar":"مثالي للوكلاء الجدول الزمني المعقدة التي تحتاج إلى تعزيز قدرات تحسين الأداء من خلال عمال الويب وإرشادات التحسين."},"recommendation":{"en":"Empowers agents to apply PERFORMANCE_OPTIMIZATION_GUIDE.md protocols, virtualize surfaces, and offload work to Web Workers, significantly enhancing large schedule performance with tools like Profiler and bundle analyzers.","zh":"赋予代理应用 PERFORMANCE_OPTIMIZATION_GUIDE.md 协议、虚拟化表面并将工作卸载到 Web Workers，显著提高大型调度性能，使用 Profiler 和包分析器等工具","ja":"PERFORMANCE_OPTIMIZATION_GUIDE.md プロトコルを適用し、サーフェスを仮想化し、Web Workers に作業をオフロードすることで、大規模なスケジューリング パフォーマンスを大幅に向上させることができるようにエージェントを活用する。Profiler やバンドル アナライザーなどのツールを使用","ko":"PERFORMANCE_OPTIMIZATION_GUIDE.md 프로토콜을 적용하고, 표면을 가상화하고, 웹 워커로 작업을 오프로드하여 대규모 스케줄링 성능을 크게 향상시킬 수 있도록 에이전트를 활성화한다. 프로파일러 및 번들 분석기와 같은 도구를 사용","es":"Habilita a los agentes a aplicar protocolos de PERFORMANCE_OPTIMIZATION_GUIDE.md, virtualizar superficies y descargar trabajo a Web Workers, lo que mejora significativamente el rendimiento de grandes horarios con herramientas como Profiler y analizadores de paquetes.","fr":"Permet aux agents d''appliquer des protocoles PERFORMANCE_OPTIMIZATION_GUIDE.md, de virtualiser des surfaces et de décharger des tâches vers Web Workers, améliorant ainsi considérablement les performances de grands horaires avec des outils tels que Profiler et des analyseurs de bundles.","de":"Ermächtigt Agents, PERFORMANCE_OPTIMIZATION_GUIDE.md-Protokolle anzuwenden, Oberflächen zu virtualisieren und Arbeit an Web Workers auszulagern, wodurch die Leistung großer Zeitpläne mit Tools wie Profiler und Bundle-Analyzern erheblich verbessert wird.","pt":"Habilita agentes a aplicar protocolos PERFORMANCE_OPTIMIZATION_GUIDE.md, virtualizar superfícies e transferir trabalho para Web Workers, melhorando significativamente o desempenho de grandes agendas com ferramentas como Profiler e analisadores de pacotes.","ru":"Позволяет агентам применять протоколы PERFORMANCE_OPTIMIZATION_GUIDE.md, виртуализировать поверхности и передавать работу веб-работникам, что значительно улучшает производительность больших расписаний с помощью инструментов, таких как Profiler и анализаторы пакетов.","ar":"تمكين الوكلاء من تطبيق بروتوكولات PERFORMANCE_OPTIMIZATION_GUIDE.md، وتحويل السطوح إلى الوضع الافتراضي، وتنفيذ مهام على عمال الويب، مما يعزز الأداء الكبير للجداول الزمنية بشكل كبير باستخدام أدوات مثل Profiler ومحلل الحزم."},"useCases":{"en":["Optimizing large schedule performance through guide-based protocols","Offloading heavy computations to Web Workers for improved efficiency","Measuring and analyzing performance enhancements with Profiler and bundle analyzers"],"zh":["通过指南基于协议优化大型调度性能","将重计算卸载到 Web Workers 以提高效率","使用 Profiler 和包分析器测量和分析性能增强"],"ja":["ガイドベースのプロトコルを使用して大規模なスケジューリング パフォーマンスを最適化する","Web Workers に重い計算をオフロードして効率を向上させる","Profiler とバンドル アナライザーを使用してパフォーマンスの向上を測定して分析する"],"ko":["가이드 기반 프로토콜을 사용하여 대규모 스케줄링 성능을 최적화","웹 워커에 무거운 계산을 오프로드하여 효율성을 향상","프로파일러 및 번들 분석기를 사용하여 성능 향상을 측정 및 분석"],"es":["Optimizar el rendimiento de grandes horarios mediante protocolos basados en guías","Descargar cálculos pesados a Web Workers para mejorar la eficiencia","Medir y analizar mejoras de rendimiento con Profiler y analizadores de paquetes"],"fr":["Optimiser les performances de grands horaires via des protocoles basés sur des guides","Décharger des calculs lourds vers Web Workers pour améliorer l''efficacité","Mesurer et analyser les améliorations de performances avec Profiler et des analyseurs de bundles"],"de":["Optimieren des Leistungsverhaltens großer Zeitpläne durch leitfadenbasierte Protokolle","Auslagern von rechenintensiven Berechnungen an Web Workers zur Effizienzsteigerung","Messen und Analysieren von Leistungsverbesserungen mit Profiler und Bundle-Analyzern"],"pt":["Otimizando o desempenho de grandes agendas por meio de protocolos baseados em guias","Transferindo cálculos pesados para Web Workers para melhorar a eficiência","Medindo e analisando melhorias de desempenho com Profiler e analisadores de pacotes"],"ru":["Оптимизация производительности больших расписаний посредством протоколов на основе руководств","Передача тяжелых вычислений веб-работникам для улучшения эффективности","Измерение и анализ улучшений производительности с помощью Profiler и анализаторов пакетов"],"ar":["تحسين أداء الجداول الزمنية الكبيرة من خلال بروتوكولات قائم على الإرشادات","نقل الحسابات الثقيلة إلى عمال الويب لتحسين الكفاءة","قياس وتحليل تحسينات الأداء باستخدام Profiler ومحلل الحزم"]},"limitations":{"en":["Requires access to PERFORMANCE_OPTIMIZATION_GUIDE.md","Dependent on Web Workers compatibility","Needs npm environment for verification scripts like ''npm run verify:sprint3''"],"zh":["需要访问 PERFORMANCE_OPTIMIZATION_GUIDE.md","依赖于 Web Workers 兼容性","需要 npm 环境以运行验证脚本，如 ''npm run verify:sprint3''"],"ja":["PERFORMANCE_OPTIMIZATION_GUIDE.md にアクセスする必要がある","Web Workers の互換性に依存している","バージョン確認スクリプトを実行するために npm 環境が必要である。例: ''npm run verify:sprint3''"],"ko":["PERFORMANCE_OPTIMIZATION_GUIDE.md에 액세스해야 함","웹 워커 호환성에 종속","버전 확인 스크립트를 실행하는 데 npm 환경이 필요하다. 예: ''npm run verify:sprint3''"],"es":["Requiere acceso a PERFORMANCE_OPTIMIZATION_GUIDE.md","Dependiente de la compatibilidad de Web Workers","Necesita entorno npm para scripts de verificación como ''npm run verify:sprint3''"],"fr":["Nécessite un accès à PERFORMANCE_OPTIMIZATION_GUIDE.md","Dépend de la compatibilité de Web Workers","Nécessite un environnement npm pour des scripts de vérification tels que ''npm run verify:sprint3''"],"de":["Benötigt Zugriff auf PERFORMANCE_OPTIMIZATION_GUIDE.md","Abhängig von der Kompatibilität von Web Workers","Benötigt npm-Umgebung für Verifizierungsskripte wie ''npm run verify:sprint3''"],"pt":["Requer acesso a PERFORMANCE_OPTIMIZATION_GUIDE.md","Dependente da compatibilidade com Web Workers","Necessita de ambiente npm para scripts de verificação como ''npm run verify:sprint3''"],"ru":["Требует доступа к PERFORMANCE_OPTIMIZATION_GUIDE.md","Зависит от совместимости с веб-работниками","Требует среды npm для скриптов проверки, таких как ''npm run verify:sprint3''"],"ar":["يتطلب الوصول إلى PERFORMANCE_OPTIMIZATION_GUIDE.md","يعتمد على توافق عمال الويب","يحتاج إلى بيئة npm لScripts التحقق مثل ''npm run verify:sprint3''"]},"version":4},"contentHash":"346a228310fc1ecb2eb6855ba461517cab380f72b942b1cd4e776de073b6a529","qualityScore":25}');
