INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Tirael/cursor-template/c4-modeling', 'c4-modeling', 'Tirael', 'cursor-template', 'community', 'c4-modeling Tirael cursor-template community c4-modeling is a skill for system modeling, helping developers design containers, components, and connections. It benefits developers by providing a structured approach to system design. C4 Modeling 是一种系统设计方法，帮助开发者明确系统边界和容器，优化组件设计 C4 Modeling は、システム設計を明確化し、コンポーネント設計を最適化するための方法論です C4 Modeling은 시스템 경계와 컨테이너를 명확하게 하고 구성 요소 디자인을 최적화하는 시스템 디자인 방법입니다 C4 Modeling es una técnica de modelado de sistemas que ayuda a los desarrolladores a entender y documentar la arquitectura de sus aplicaciones La modélisation C4 est une technique de modélisation de systèmes qui aide les développeurs à comprendre et à documenter l''architecture de leurs applications C4-Modellierung ist eine Technik zur Modellierung von Systemen, die Entwicklern hilft, die Architektur ihrer Anwendungen zu verstehen und zu dokumentieren O C4 Modeling é uma técnica de modelagem de sistemas que ajuda a entender e projetar contêineres e componentes C4 Моделирование - это техника моделирования систем, которая помогает понять и спроектировать контейнеры и компоненты نموذج C4 هو تقنية لنمذجة الأنظمة التي تساعد على فهم وتصميم الحاويات والمكونات how to use c4-modeling c4-modeling vs UML c4-modeling setup guide system modeling techniques c4-modeling alternative tools what is c4-modeling c4-modeling install c4-modeling for AI agents C4 Modeling 系统设计 容器设计 组件设计 LikeC4 PNG 导出 系统架构 开发效率 Exports PNG diagrams via the `export-likec4-png-white` skill Stores C4 models in the `src/c4/` directory Follows rules for singular element purpose and connection labeling Supports detailed component level modeling for key containers Enforces view consistency to avoid model duplication c4-modeling is a system modeling technique for clarifying context and boundaries, designing containers and connections, and detailing component levels');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joseph0926/study-all/forge', 'community', 'joseph0926', 'study-all', 'joseph0926/study-all', 'forge', 2, 0, 25, '2026-02-26T06:41:25Z', '2026-02-26T08:41:54.024Z', 'fb879190b2cf802a45c182ea34270c15c56cbcab9d47ef470bdd847be053e8c9', '{"id":"joseph0926/study-all/forge","name":"forge","description":{"zh":"AI工具forge是一个开发者学习和记录开发技术的平台，帮助开发者提升开发效率","ja":"AIエージェントforgeは開発技術の学習と記録のためのプラットフォーム","ko":"AI 에이전트 forge는 개발자가 개발 기술을 학습하고 기록을 축적하는 레포입니다","es":"Forge es una herramienta de aprendizaje de desarrollo con AI que te permite mejorar tus habilidades y registrar tus logros.","fr":"Forge est un outil d''apprentissage de développement avec l''IA qui vous permet d''améliorer vos compétences et d''enregistrer vos réalisations.","de":"Forge ist ein Entwicklungstool mit KI, das es Ihnen ermöglicht, Ihre Fähigkeiten zu verbessern und Ihre Erfolge aufzuzeichnen.","pt":"O Forge é uma ferramenta de IA que ajuda os desenvolvedores a aprender e registrar técnicas de desenvolvimento","ru":"Forge - это инструмент ИИ, который помогает разработчикам изучать и записывать методы разработки","ar":"Forge هي أداة ذكاء اصطناعي تساعد المطورين على تعلم وتسجيل تقنيات التطوير","en":"AI와 함께 개발 기술를 학습하고, 기록을 축적하는 레포."},"seo":{"title":{"zh":"AI工具forge：开发技术学习与记录","ja":"AIエージェントforge：開発技術の学習と記録","ko":"AI 에이전트 forge: 개발 기술 학습 및 기록","es":"Herramientas de AI: Forge, aprende y registra","fr":"Outils d''IA: Forge, apprendre et enregistrer","de":"KI-Tools: Forge, lernen und aufzeichnen","pt":"Ferramentas de IA: Forge para Desenvolvedores","ru":"ИИ Агенты: Forge для разработчиков","ar":"أدوات الذكاء الاصطناعي: Forge لل مطورين","en":"forge"},"description":{"zh":"AI工具forge是一个开发者学习和记录开发技术的平台，帮助开发者提升开发效率","ja":"AIエージェントforgeは開発技術の学習と記録のためのプラットフォーム","ko":"AI 에이전트 forge는 개발자가 개발 기술을 학습하고 기록을 축적하는 레포입니다","es":"Forge es una herramienta de aprendizaje de desarrollo con AI que te permite mejorar tus habilidades y registrar tus logros.","fr":"Forge est un outil d''apprentissage de développement avec l''IA qui vous permet d''améliorer vos compétences et d''enregistrer vos réalisations.","de":"Forge ist ein Entwicklungstool mit KI, das es Ihnen ermöglicht, Ihre Fähigkeiten zu verbessern und Ihre Erfolge aufzuzeichnen.","pt":"O Forge é uma ferramenta de IA que ajuda os desenvolvedores a aprender e registrar técnicas de desenvolvimento","ru":"Forge - это инструмент ИИ, который помогает разработчикам изучать и записывать методы разработки","ar":"Forge هي أداة ذكاء اصطناعي تساعد المطورين على تعلم وتسجيل تقنيات التطوير","en":"AI와 함께 개발 기술를 학습하고, 기록을 축적하는 레포."},"definition":{"en":"AI와 함께 개발 기술를 학습하고, 기록을 축적하는 레포."},"features":{"zh":["开发技术学习","记录和跟踪进度","开发效率提升","AI驱动的学习","开发者社区支持"],"ja":["開発技術の学習","記録と進度の追跡","開発効率の向上","AI駆動の学習","開発者コミュニティのサポート"],"ko":["개발 기술 학습","기록 및 진행 상황 추적","개발 효율성 향상","AI 기반 학습","개발자 커뮤니티 지원"],"es":["Aprendizaje de desarrollo con AI","Registro de logros y progreso","Mejora de habilidades de programación","Integración con herramientas de desarrollo populares","Análisis de código y retroalimentación","Comunidad de desarrolladores y recursos"],"fr":["Apprentissage de développement avec l''IA","Enregistrement des réalisations et du progrès","Amélioration des compétences de programmation","Intégration avec des outils de développement populaires","Analyse de code et rétroaction","Communauté de développeurs et ressources"],"de":["Entwicklungslernen mit KI","Aufzeichnung von Erfolgen und Fortschritt","Verbesserung der Programmierfähigkeiten","Integration mit beliebten Entwicklungstools","Code-Analyse und Rückmeldung","Entwickler-Community und Ressourcen"],"pt":["Aprendizado de técnicas de desenvolvimento com IA","Registro de técnicas de desenvolvimento","Integração com ferramentas de desenvolvimento","Suporte a múltiplas linguagens de programação","Interface de usuário intuitiva"],"ru":["Изучение методов разработки с помощью ИИ","Запись методов разработки","Интеграция с инструментами разработки","Поддержка нескольких языков программирования","Интуитивно понятный интерфейс пользователя"],"ar":["تعلم تقنيات التطوير مع الذكاء الاصطناعي","تسجيل تقنيات التطوير","التكامل مع أدوات التطوير","دعم لعدة لغات برمجة","واجهة مستخدم سهلة الاستخدام"]},"keywords":{"zh":["AI工具","开发技术学习","开发效率提升","AI驱动的学习","开发者社区","如何使用AI工具","AI工具forge alternative","AI工具forge vs competitive"],"ja":["AIエージェント","開発技術の学習","開発効率の向上","AI駆動の学習","開発者コミュニティ","AIエージェントの使い方","AIエージェントforge alternative","AIエージェントforge vs competitive"],"ko":["AI 에이전트","개발 기술 학습","개발 효율성 향상","AI 기반 학습","개발자 커뮤니티","AI 에이전트 사용법","AI 에이전트 forge alternative","AI 에이전트 forge vs competitive"],"es":["herramientas de AI para desarrolladores","cómo usar Forge","qué es la inteligencia artificial en el desarrollo","Forge vs otros herramientas de desarrollo","instalación de Forge","guía de configuración de Forge","mejora de habilidades de programación con AI"],"fr":["outils d''IA pour développeurs","comment utiliser Forge","quoi est l''intelligence artificielle dans le développement","Forge vs autres outils de développement","installation de Forge","guide de configuration de Forge","amélioration des compétences de programmation avec l''IA"],"de":["KI-Tools für Entwickler","wie man Forge verwendet","was ist die künstliche Intelligenz in der Entwicklung","Forge vs andere Entwicklungstools","Installation von Forge","Konfigurationsanleitung für Forge","Verbesserung der Programmierfähigkeiten mit KI"],"pt":["ferramentas de ia para desenvolvedores","como usar forge","o que é forge","forge vs outras ferramentas","guia de instalação do forge","configuração do forge","desenvolvimento de software com ia"],"ru":["инструменты ии для разработчиков","как использовать forge","что такое forge","forge vs другие инструменты","установка forge","настройка forge","разработка программного обеспечения с ии"],"ar":["أدوات الذكاء الاصطناعي للمطورين","كيفية استخدام forge","ما هي forge","forge مقابل أدوات أخرى","دليل تثبيت forge","إعداد forge","تطوير البرمجيات مع الذكاء الاصطناعي"]}},"owner":"joseph0926","repo":"study-all","repoPath":"joseph0926/study-all","stars":2,"forks":0,"updatedAt":"2026-02-26T06:41:25Z","topics":[],"category":"community","skillMd":{"name":"forge","description":"산발적 학습을 통합 멘탈모델 + 실전 판단 프레임워크로 결정화 — 통합 비유 + 핵심 원칙 + Q&A. Codex에서는 `$forge <skill> [scope]`로 호출한다.","bodyPreview":"# forge\n\n입력: `$forge <skill> [scope]` (예: `$forge react`, `$forge react rendering`)\n\n실행 순서:\n\n0. `mcp__study__context_resolve(mode=skill, skill=<skill>)`로 컨텍스트 확인\n1. `$ARGUMENTS`에서 `<skill> [scope]` 파싱 (`skill` 필수, `scope` 선택)\n\n---\n\n## Phase 0: 인벤토리\n\n1. `study/{skill}/` 하위 모든 `.md` 파일 목록 수집 (Glob)\n2. `study/learn/` 에서 해당 skill 관련 파일 교차 수집 (Grep으로 키워드 매칭)\n3. `mcp__study__progress_getPlan(context)`으로 plan.md 로드 → 완료/미완료 토픽 파악\n4. 각 토픽의 meta 파일 읽기 (Read) → 약점 추출:\n   - `wrong` 또는 `retry_pass` 점수의 개념 목","body":"# forge\n\n입력: `$forge <skill> [scope]` (예: `$forge react`, `$forge react rendering`)\n\n실행 순서:\n\n0. `mcp__study__context_resolve(mode=skill, skill=<skill>)`로 컨텍스트 확인\n1. `$ARGUMENTS`에서 `<skill> [scope]` 파싱 (`skill` 필수, `scope` 선택)\n\n---\n\n## Phase 0: 인벤토리\n\n1. `study/{skill}/` 하위 모든 `.md` 파일 목록 수집 (Glob)\n2. `study/learn/` 에서 해당 skill 관련 파일 교차 수집 (Grep으로 키워드 매칭)\n3. `mcp__study__progress_getPlan(context)`으로 plan.md 로드 → 완료/미완료 토픽 파악\n4. 각 토픽의 meta 파일 읽기 (Read) → 약점 추출:\n   - `wrong` 또는 `retry_pass` 점수의 개념 목록\n   - streak 0인 개념\n5. scope 지정 시: 관련 토픽만 필터링\n6. 사용자에게 인벤토리 보고:\n\n   ```\n   ## 인벤토리\n   - 대상 토픽: {N}개 (scope: {scope 또는 \"전체\"})\n   - 커버리지: plan.md 기준 {완료}/{전체}\n   - 약점 개념: {N}개 (wrong/retry_pass)\n   - 토픽 목록: ...\n   ```\n\n7. 사용자 확인 후 Phase 1 진행.\n\n---\n\n## Phase 1: 통합 비유 + 핵심 원칙\n\n### 1-A. 토픽 읽기\n\n각 토픽 파일을 Read하고 핵심 개념을 추출한다:\n- 토픽별 핵심 개념 (1~3문장)\n- 소스 경로 참조 (`file:line`)\n- 토픽 간 기존 연결 (파일 내 언급된 다른 토픽/개념)\n- 약점 개념 표시\n\n### 1-B. 통합 비유 (Mega-Analogy)\n\n모든 핵심 개념을 **하나의 세계관**으로 연결하는 비유를 구성한다.\n\n규칙:\n- 비유의 각 요소와 실제 개념 간 **1:1 대응**을 명시한다.\n- 대응 요소가 3개 미만이면 통합 비유를 생략하고 \"비유 한계:\" 설명만 남긴다.\n- 1:1 대응이 불가능한 부분은 \"비유 한계:\" 접두사로 이유와 부분 비유를 제시한다.\n- 비유를 위해 사실을 왜곡하지 않는다.\n\n제시 형식:\n```\n## 통합 비유: {비유 제목}\n\n{비유 세계관 설명}\n\n| 비유 요소 | 실제 개념 | 대응 이유 |\n|-----------|-----------|-----------|\n| ...       | ...       | ...       |\n\n{비유 한계가 있으면 여기에 명시}\n```\n\n### 1-C. 핵심 원칙 추출\n\n3~5개 핵심 원칙을 추출한다. 각 원칙의 구조:\n\n- **이름**: 2~5단어, 기억하기 쉬운 이름\n- **한 줄 요약**: 1문장\n- **근거**: 어떤 토픽에서 비롯되었는지 (토픽 참조 + `file:line` 가능 시 포함)\n- **기억법**: 통합 비유의 해당 요소 연결 또는 독립 비유/이미지\n- **약점 연결**: 해당 원칙과 관련된 약점 개념이 있으면 명시\n\n원칙 선정 기준:\n- 여러 토픽에 걸쳐 반복되는 패턴 우선\n- 실전 판단에 직접 영향을 주는 것 우선\n- 약점 개념이 포함된 영역 우선\n\n### 1-D. Q&A (L1 연결)\n\n통합 비유와 핵심 원칙을 제시한 후, **연결 이해**를 검증하는 Q&A를 출제한다.\n\n- L1 (연결): \"A와 B는 어떤 관계인가?\", \"비유에서 X에 해당하는 실제 개념은?\"\n- 1~2문제 출제\n- 오답 시: 보충 설명 후 재질문\n- 정답 시: 다음 Phase로\n\n사용자 `>>다음` 신호로 Phase 2 진행.\n\n---\n\n## Phase 2: 판단 프레임워크 + Q&A\n\n### 2-A. 실전 시나리오 구성\n\n핵심 원칙 + 약점 개념을 기반으로 실전 시나리오 3~7개를 구성한다.\n\n각 시나리오의 구조:\n- **상황**: 실제 코딩/설계/디버깅 시 마주치는 상황\n- **떠올려**: 어떤 원칙/개념을 떠올려야 하는지\n- **근거**: 왜 그 원칙이 적용되는지\n- **안티패턴**: \"이렇게 하면 안 되는 이유\" (선택, 관련 시)\n\n시나리오 구성 기준:\n- 약점 개념이 포함된 시나리오를 반드시 1개 이상 포함\n- 원칙이 2개 이상 교차하는 시나리오 우선\n- 추상적 상황보다 구체적 코드/설계 상황 선호\n\n### 2-B. Q&A (L2 판단, L3 설계)\n\n시나리오를 제시한 후, **판단/설계** 수준의 Q&A를 출제한다.\n\n- L2 (판단): \"상황 X에서 어떤 원칙을 적용해야 하나?\"\n- L3 (설계): \"Y를 구현한다면 어떤 트레이드오프를 고려해야 하나?\"\n- 2~3문제 출제\n- L2 정답 → L3 에스컬레이션. 오답 시 보충 설명 후 재질문.\n- 추가 질문/논의 자유롭게 이어갈 수 있다.\n\n사용자 `>>정리` 또는 `>>끝` 신호로 Phase 3 진행.\n\n---\n\n## Phase 3: 문서화\n\n`>>정리` 또는 `>>끝` 시:\n\n1. `study/{skill}/FORGE-{Name}.md`에 Write한다.\n\n   Name 규칙: 핵심 주제를 반영한 kebab-case (예: `FORGE-업데이트-처리-파이프라인.md`)\n\n2. `mcp__study__session_appendLog(context, topic=\"FORGE-{Name}\", content=<요약>)`로 세션 기록.\n\n문서 템플릿:\n\n```markdown\n# FORGE: {제목}\n\n> 생성일: {YYYY-MM-DD}\n> 기반 토픽: {토픽 목록}\n> 범위: {scope 또는 \"전체\"}\n\n---\n\n## 통합 비유: {비유 제목}\n\n{비유 세계관 설명}\n\n| 비유 요소 | 실제 개념 | 대응 이유 |\n|-----------|-----------|-----------|\n| ...       | ...       | ...       |\n\n{비유 한계가 있으면 여기에 명시}\n\n---\n\n## 핵심 원칙\n\n### 1. {원칙 이름}\n> {한 줄 요약}\n\n**근거**: {토픽 참조}\n**기억법**: {비유/이미지}\n\n### 2. ...\n\n---\n\n## 판단 프레임워크\n\n### 상황: {시나리오}\n**떠올려**: ...\n**근거**: ...\n**안티패턴**: ...\n\n### 상황: ...\n\n---\n\n## 약점 보강\n\n> review에서 자주 틀린 개념들의 핵심 정리\n\n### {개념}\n**핵심**: ...\n**왜 헷갈리나**: ...\n**기억법**: ...\n\n---\n\n## Q&A 기록\n\n### Q1 (L{N}). {질문}\n**A**: {사용자 답변}\n**Score**: {정답/오답}\n**보충**: {오답 시 보충 설명}\n\n---\n\n## 원페이저\n\n| 원칙 | 한 줄 | 상황 | 기억법 |\n|------|-------|------|--------|\n| ...  | ...   | ...  | ...    |\n```\n\n---\n\n## 사용자 신호 규칙\n\n- `>>다음` — Phase 1 → Phase 2 전환\n- `>>정리` 또는 `>>끝` — 세션 종료 + Phase 3 실행\n- 일반 대화 속 \"다음\", \"정리\", \"끝\"은 신호로 인식하지 않는다 (`>>` 접두사 필수).\n\n## 규칙\n\n- 기존 study/ 파일은 **읽기만** 한다. 수정하지 않는다.\n- 쓰기 동작은 `>>정리` 이후에만 수행한다.\n- Q&A 원문은 오타 수정만 하고 그대로 기록한다.\n- 통합 비유가 불가능하면 강제하지 않는다 (\"비유 한계:\" 처리).\n- 비유를 위해 사실을 왜곡하지 않는다.\n- 모든 원칙/프레임워크에 토픽 참조를 포함한다.\n- 기존 /learn 비유가 있으면 새로 만들지 않고 재활용/확장한다.\n- AI가 자체 판단으로 Phase를 건너뛰지 않는다.\n"},"lastSynced":"2026-02-26T08:41:54.024Z","agentAnalysis":{"suitability":{"en":"Ideal for Knowledge Management Agents needing advanced skill development and documentation capabilities.","zh":"适合需要高级技能开发和文档能力的知识管理代理。","ja":"高度なスキル開発とドキュメント機能が必要なナレッジマネジメントエージェントに最適。","ko":"고급 스킬 개발 및 문서화 기능이 필요한 지식 관리 에이전트에 적합합니다.","es":"Ideal para agentes de Gestión del Conocimiento que necesitan desarrollo de habilidades avanzadas y capacidades de documentación.","fr":"Idéal pour les agents de gestion des connaissances nécessitant un développement de compétences avancé et des capacités de documentation.","de":"Ideal für Wissensmanagement-Agenten, die eine weiterentwickelte Fähigkeitsentwicklung und Dokumentationsfunktionen benötigen.","pt":"Ideal para Agentes de Gerenciamento de Conhecimento que precisam de desenvolvimento de habilidades avançadas e capacidades de documentação.","ru":"Идеально подходит для агентов управления знаниями, требующих расширенного развития навыков и возможностей документирования.","ar":"مثالي لعميل إدارة المعرفة الذين يحتاجون إلى تطوير مهارات متقدمة وقدرات توثيقية."},"recommendation":{"en":"Empowers agents to parse and analyze Markdown files, utilizing Glob for file collection and Grep for keyword matching, while integrating with study plans and progress tracking through `mcp__study__context_resolve` and `mcp__study__progress_getPlan`.","zh":"赋予代理解析和分析Markdown文件的能力，利用Glob进行文件收集和Grep进行关键词匹配，同时通过`mcp__study__context_resolve`和`mcp__study__progress_getPlan`与学习计划和进度跟踪集成。","ja":"エージェントにMarkdownファイルを解析して分析する能力を付与し、Globを使用してファイルを収集し、Grepを使用してキーワードを一致させ、`mcp__study__context_resolve`および`mcp__study__progress_getPlan`を介して学習計画や進度の追跡と統合します。","ko":"에이전트가 Markdown 파일을 분석하고 해석할 수 있도록하며, Glob를 사용하여 파일을 수집하고 Grep를 사용하여 키워드를 일치시키고, `mcp__study__context_resolve`와 `mcp__study__progress_getPlan`을 통해 학습 계획 및 진행 상황 추적과 통합합니다.","es":"Permite a los agentes analizar y parsear archivos Markdown, utilizando Glob para la recopilación de archivos y Grep para la coincidencia de palabras clave, mientras se integra con planes de estudio y seguimiento del progreso a través de `mcp__study__context_resolve` y `mcp__study__progress_getPlan`.","fr":"Permet aux agents d''analyser et de parser des fichiers Markdown, en utilisant Glob pour la collecte de fichiers et Grep pour la correspondance de mots clés, tout en s''intégrant avec les plans d''étude et le suivi des progrès via `mcp__study__context_resolve` et `mcp__study__progress_getPlan`.","de":"Ermöglicht es den Agenten, Markdown-Dateien zu analysieren und zu parsen, indem Glob für die Dateisammlung und Grep für die Schlüsselwortübereinstimmung verwendet wird, während es sich mit Lernplänen und Fortschrittsverfolgung über `mcp__study__context_resolve` und `mcp__study__progress_getPlan` integriert.","pt":"Habilita agentes a analisar e parsear arquivos Markdown, utilizando Glob para coleta de arquivos e Grep para correspondência de palavras-chave, enquanto se integra com planos de estudo e acompanhamento de progresso por meio de `mcp__study__context_resolve` e `mcp__study__progress_getPlan`.","ru":"Наделяет агентов возможностью парсить и анализировать файлы Markdown, используя Glob для сбора файлов и Grep для соответствия ключевых слов, при этом интегрируясь с планами обучения и отслеживанием прогресса через `mcp__study__context_resolve` и `mcp__study__progress_getPlan`.","ar":"يمنح الوكلاء khảية تحليل وفرز ملفات Markdown، باستخدام Glob لجمع الملفات و Grep لمطابقة الكلمات الرئيسية، في حين يدمج مع خطط الدراسة وتتبع التقدم من خلال `mcp__study__context_resolve` و `mcp__study__progress_getPlan`."},"useCases":{"en":["Automating skill documentation by parsing `.md` files","Generating study plans based on topic completion status","Debugging knowledge gaps by analyzing meta files for weaknesses"],"zh":["通过解析`.md`文件来自动化技能文档","根据主题完成状态生成学习计划","通过分析元文件中的弱点来调试知识缺口"],"ja":["`.md`ファイルを解析してスキルドキュメントを自動化する","トピックの完了状態に基づいて学習計画を生成する","メタファイルを分析して知識のギャップをデバッグする"],"ko":[".md 파일을 분석하여 스킬 문서를 자동화하는 것","주제 완료 상태에 따라 학습 계획을 생성하는 것","메타 파일을 분석하여 지식의 약점을 디버깅하는 것"],"es":["Automatizar la documentación de habilidades al analizar archivos `.md`","Generar planes de estudio en función del estado de finalización de temas","Depurar las lagunas de conocimiento al analizar archivos meta en busca de debilidades"],"fr":["Automatiser la documentation des compétences en analysant des fichiers `.md`","Générer des plans d''étude en fonction de l''état d''achèvement des sujets","Déboguer les lacunes de connaissances en analysant des fichiers meta pour les faiblesses"],"de":["Automatisieren der Fähigkeitsdokumentation durch die Analyse von `.md`-Dateien","Erstellen von Lernplänen basierend auf dem Abschlussstatus von Themen","Fehlerbehebung von Wissenslücken durch die Analyse von Meta-Dateien auf Schwachstellen"],"pt":["Automatizar a documentação de habilidades parseando arquivos `.md`","Gerar planos de estudo com base no status de conclusão de tópicos","Depurar lacunas de conhecimento analisando arquivos meta para pontos fracos"],"ru":["Автоматизировать документацию навыков, парсируя файлы `.md`","Генерировать планы обучения на основе статуса завершения тем","Отлаживать пробелы в знаниях, анализируя файлы meta для слабых мест"],"ar":["توفير توثيق المهارات عن طريق فرز ملفات `.md`","جعل خطط الدراسة根据 حالة إكمال الموضوعات","تصحيح الثغرات في المعرفة من خلال تحليل الملفات الميتا للنقاط الضعف"]},"limitations":{"en":["Requires access to `study/` directory and its subdirectories","Dependent on `mcp__study__context_resolve` and `mcp__study__progress_getPlan` functions","Limited to Markdown file format (.md)"],"zh":["需要访问`study/`目录及其子目录","依赖于`mcp__study__context_resolve`和`mcp__study__progress_getPlan`函数","仅限于Markdown文件格式(.md)"],"ja":["`study/`ディレクトリおよびそのサブディレクトリへのアクセスが必要","`mcp__study__context_resolve`および`mcp__study__progress_getPlan`関数に依存","Markdownファイル形式(.md)のみに限定"],"ko":["`study/` 디렉토리及其 하위 디렉토리에 대한 접근 권한이 필요","`mcp__study__context_resolve` 및 `mcp__study__progress_getPlan` 함수에 의존","Markdown 파일 형식(.md)으로 제한"],"es":["Requiere acceso al directorio `study/` y sus subdirectorios","Dependiente de las funciones `mcp__study__context_resolve` y `mcp__study__progress_getPlan`","Limitado al formato de archivo Markdown (.md)"],"fr":["Nécessite un accès au répertoire `study/` et à ses sous-répertoires","Dépendant des fonctions `mcp__study__context_resolve` et `mcp__study__progress_getPlan`","Limité au format de fichier Markdown (.md)"],"de":["Benötigt Zugriff auf das Verzeichnis `study/` und seine Unterordner","Abhängig von den Funktionen `mcp__study__context_resolve` und `mcp__study__progress_getPlan`","Begrenzt auf das Markdown-Dateiformat (.md)"],"pt":["Exige acesso ao diretório `study/` e seus subdiretórios","Dependente das funções `mcp__study__context_resolve` e `mcp__study__progress_getPlan`","Limitado ao formato de arquivo Markdown (.md)"],"ru":["Требует доступа к каталогу `study/` и его подкаталогам","Зависит от функций `mcp__study__context_resolve` и `mcp__study__progress_getPlan`","Ограничен форматом файла Markdown (.md)"],"ar":["يتطلب الوصول إلى الدليل `study/` وفروعه","يعتمد على الدوال `mcp__study__context_resolve` و `mcp__study__progress_getPlan`","محدود بتنسيق ملف Markdown (.md)"]},"version":3},"contentHash":"fb879190b2cf802a45c182ea34270c15c56cbcab9d47ef470bdd847be053e8c9","qualityScore":25}');
