INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joseph0926/study-all/forge', 'forge', 'joseph0926', 'study-all', 'community', 'forge joseph0926 study-all community AI工具forge是一个开发者学习和记录开发技术的平台，帮助开发者提升开发效率 AIエージェントforgeは開発技術の学習と記録のためのプラットフォーム AI 에이전트 forge는 개발자가 개발 기술을 학습하고 기록을 축적하는 레포입니다 Forge es una herramienta de aprendizaje de desarrollo con AI que te permite mejorar tus habilidades y registrar tus logros. Forge est un outil d''apprentissage de développement avec l''IA qui vous permet d''améliorer vos compétences et d''enregistrer vos réalisations. Forge ist ein Entwicklungstool mit KI, das es Ihnen ermöglicht, Ihre Fähigkeiten zu verbessern und Ihre Erfolge aufzuzeichnen. O Forge é uma ferramenta de IA que ajuda os desenvolvedores a aprender e registrar técnicas de desenvolvimento Forge - это инструмент ИИ, который помогает разработчикам изучать и записывать методы разработки Forge هي أداة ذكاء اصطناعي تساعد المطورين على تعلم وتسجيل تقنيات التطوير AI와 함께 개발 기술를 학습하고, 기록을 축적하는 레포. AI工具 开发技术学习 开发效率提升 AI驱动的学习 开发者社区 如何使用AI工具 AI工具forge alternative AI工具forge vs competitive AI와 함께 개발 기술를 학습하고, 기록을 축적하는 레포.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OpenHands/skills/npm', 'community', 'OpenHands', 'skills', 'OpenHands/skills', 'npm', 0, 0, 25, '2026-02-20T04:13:19.574Z', '2026-02-20T04:32:00.568Z', 'f29251d112f6ba935eed0b36ccae2696f9080bdeb7fd852846f729161f7e30f2', '{"id":"OpenHands/skills/npm","name":"npm","description":{"zh":"npm 是一个包安装工具，使用 unix 的 yes 命令可以自动确认操作","ja":"npm はパッケージのインストールツールです。unix の yes コマンドを使用して操作を自動的に確認できます","ko":"npm은 패키지 설치 도구로 unix의 yes 명령을 사용하여 작업을 자동으로 확인할 수 있습니다","es":"npm es un registro público para paquetes de OpenHands que permite instalar dependencias de manera sencilla.","fr":"npm est un registre public pour les packages OpenHands qui permet d''installer des dépendances de manière simple.","de":"npm ist ein öffentliches Register für OpenHands-Pakete, das das Installieren von Abhängigkeiten auf einfache Weise ermöglicht.","pt":"O npm é um registro público para pacotes OpenHands, permitindo instalação sem shell interativo","ru":"npm — это публичный реестр пакетов OpenHands, позволяющий устанавливать пакеты без интерактивного shell","ar":"npm هو سجل عام للحزم OpenHands، يسمح بتثبيت الحزم بدون شل تفاعلي","en":"Public registry for OpenHands skills."},"seo":{"title":{"zh":"npm 包安装指南","ja":"npm パッケージのインストール","ko":"npm 패키지 설치 가이드","es":"npm: Registro público para paquetes de OpenHands","fr":"npm: Registre public pour les packages OpenHands","de":"npm: Öffentliches Register für OpenHands-Pakete","pt":"npm: Registro Público de Pacotes","ru":"npm: Публичный Реестр Пакетов","ar":"npm: سجل عام للحزم","en":"npm"},"description":{"zh":"npm 是一个包安装工具，使用 unix 的 yes 命令可以自动确认操作","ja":"npm はパッケージのインストールツールです。unix の yes コマンドを使用して操作を自動的に確認できます","ko":"npm은 패키지 설치 도구로 unix의 yes 명령을 사용하여 작업을 자동으로 확인할 수 있습니다","es":"npm es un registro público para paquetes de OpenHands que permite instalar dependencias de manera sencilla.","fr":"npm est un registre public pour les packages OpenHands qui permet d''installer des dépendances de manière simple.","de":"npm ist ein öffentliches Register für OpenHands-Pakete, das das Installieren von Abhängigkeiten auf einfache Weise ermöglicht.","pt":"O npm é um registro público para pacotes OpenHands, permitindo instalação sem shell interativo","ru":"npm — это публичный реестр пакетов OpenHands, позволяющий устанавливать пакеты без интерактивного shell","ar":"npm هو سجل عام للحزم OpenHands، يسمح بتثبيت الحزم بدون شل تفاعلي","en":"Public registry for OpenHands skills."},"definition":{"en":"Public registry for OpenHands skills."},"features":{"zh":["自动确认操作","提高开发效率","unix 集成","包安装管理","JavaScript 生态支持"],"ja":["操作の自動確認","開発効率の向上","unix 統合","パッケージのインストールと管理","JavaScript エコシステムのサポート"],"ko":["작업 자동 확인","개발 효율성 향상","unix 통합","패키지 설치 및 관리","자바스크립트 생태계 지원"],"es":["Instalación de paquetes de OpenHands","Uso de la orden unix ''yes'' para confirmar acciones","Instalación sin shell interactiva","Facilidad de uso para desarrolladores","Compatibilidad con múltiples plataformas"],"fr":["Installation de packages OpenHands","Utilisation de la commande unix ''yes'' pour confirmer les actions","Installation sans shell interactif","Facilité d''utilisation pour les développeurs","Compatibilité avec plusieurs plates-formes"],"de":["Installation von OpenHands-Paketen","Verwendung des Unix-Befehls ''yes'' zur Bestätigung von Aktionen","Installation ohne interaktive Shell","Einfachheit der Bedienung für Entwickler","Kompatibilität mit mehreren Plattformen"],"pt":["Instalação de pacotes sem shell interativo","Confirmação de ações com o comando unix ''yes''","Registro público de pacotes OpenHands","Facilidade de uso para desenvolvedores","Compatibilidade com unix"],"ru":["Установка пакетов без интерактивного shell","Подтверждение действий с помощью команды unix ''yes''","Публичный реестр пакетов OpenHands","Легкость использования для разработчиков","Совместимость с unix"],"ar":["تثبيت الحزم بدون شل تفاعلي","تأكيد الإجراءات باستخدام أمر unix ''yes''","سجل عام للحزم OpenHands","سهولة الاستخدام للمطورين","التوافق مع unix"]},"keywords":{"zh":["npm 安装","unix yes 命令","JavaScript 包管理","开发工具","自动确认操作","提高开发效率"],"ja":["npm インストール","unix yes コマンド","JavaScript パッケージ管理","開発ツール","操作の自動確認","開発効率の向上"],"ko":["npm 설치","unix yes 명령","자바스크립트 패키지 관리","개발 도구","작업 자동 확인","개발 효율성 향상"],"es":["npm","OpenHands","paquetes de código abierto","instalación de dependencias","desarrollo de software","registros de paquetes","shell interactiva","orden unix ''yes''"],"fr":["npm","OpenHands","packages de code ouvert","installation de dépendances","développement de logiciels","registres de packages","shell interactif","commande unix ''yes''"],"de":["npm","OpenHands","Open-Source-Pakete","Installation von Abhängigkeiten","Software-Entwicklung","Paket-Register","interaktive Shell","Unix-Befehl ''yes''"],"pt":["npm","registro de pacotes","openhands","desenvolvimento de software","unix","comando yes","instalação de pacotes","shell interativo"],"ru":["npm","реестр пакетов","openhands","разработка программного обеспечения","unix","команда yes","установка пакетов","интерактивный shell"],"ar":["npm","سجل الحزم","openhands","تطوير البرمجيات","unix","أمر yes","تثبيت الحزم","شل تفاعلي"]}},"owner":"OpenHands","repo":"skills","repoPath":"OpenHands/skills","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.574Z","topics":[],"category":"community","skillMd":{"name":"npm","description":"Handle npm package installation in non-interactive environments by piping confirmations. Use when installing Node.js packages that require user confirmation prompts.","bodyPreview":"When using npm to install packages, you will not be able to use an interactive shell, and it may be hard to confirm your actions.\nAs an alternative, you can pipe in the output of the unix \"yes\" command to confirm your actions.","body":"When using npm to install packages, you will not be able to use an interactive shell, and it may be hard to confirm your actions.\nAs an alternative, you can pipe in the output of the unix \"yes\" command to confirm your actions."},"lastSynced":"2026-02-20T04:32:00.568Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript-centric AI Agents seeking efficient package management and dependency installation via npm","zh":"适合于寻求通过npm实现高效包管理和依赖安装的JavaScript中心AI代理","ja":"JavaScriptを中心としたAIエージェントがnpmを介した効率的なパッケージ管理と依存関係のインストールを求める場合に最適","ko":"npm을 통해 효율적인 패키지 관리 및 의존성 설치를 구하는 자바스크립트 중심의 AI 에이전트에게 적합","es":"Ideal para agentes de inteligencia artificial centrados en JavaScript que buscan una gestión de paquetes eficiente y una instalación de dependencias a través de npm","fr":"Idéal pour les agents d''intelligence artificielle centrés sur JavaScript recherchant une gestion de packages efficace et une installation de dépendances via npm","de":"Ideal für JavaScript-zentrierte KI-Agents, die eine effiziente Paketverwaltung und eine Installation von Abhängigkeiten über npm suchen","pt":"Ideal para Agentes de IA centrados em JavaScript que buscam um gerenciamento de pacotes eficiente e instalação de dependências via npm","ru":"Идеально для агентов ИИ, ориентированных на JavaScript, ищущих эффективное управление пакетами и установку зависимостей через npm","ar":"مثالي لعميل الذكاء الاصطناعي المرتكز على جافا سكريبت الذي يسعى إلى إدارة حزمة فعالة وتثبيت التبعيات عبر npm"},"recommendation":{"en":"Empowers agents to install packages from the npm registry, leveraging unix commands like the ''yes'' command for automated confirmation, and streamlining dependency management for projects","zh":"赋予代理从npm注册表安装包的能力，利用诸如''yes''命令的unix命令进行自动确认，并简化项目的依赖管理","ja":"npmレジストリからパッケージをインストールするエージェントの機能を強化し、''yes''コマンドなどのUnixコマンドを利用して自動確認を行い、プロジェクトの依存関係管理を効率化する","ko":"npm 레지스트리에서 패키지를 설치할 수 있는 에이전트의 기능을 강화하고 ''yes'' 명령과 같은 유닉스 명령을 사용하여 자동 확인을 수행하며 프로젝트의 의존성 관리를 간소화","es":"Habilita a los agentes a instalar paquetes desde el registro de npm, aprovechando comandos de unix como el comando ''yes'' para confirmaciones automatizadas y simplificando la gestión de dependencias para proyectos","fr":"Permet aux agents d''installer des packages à partir du registre npm, en exploitant les commandes unix comme la commande ''yes'' pour des confirmations automatisées et en rationalisant la gestion des dépendances pour les projets","de":"Ermöglicht es den Agents, Pakete aus dem npm-Register zu installieren, indem es unix-Befehle wie den ''yes''-Befehl für automatisierte Bestätigungen nutzt und die Verwaltung von Abhängigkeiten für Projekte rationalisiert","pt":"Habilita os agentes a instalar pacotes do registro npm, aproveitando comandos unix como o comando ''yes'' para confirmação automatizada e simplificando o gerenciamento de dependências para projetos","ru":"Наделяет агентов возможностью устанавливать пакеты из реестра npm, используя команды unix, такие как команда ''yes'' для автоматического подтверждения, и оптимизируя управление зависимостями для проектов","ar":"يمنح الوكيل khảية تثبيت الحزم من سجل npm، مستفيداً من أوامر يونكس مثل أمر ''نعم'' للتأكيد التلقائي، وتبسيط إدارة التبعيات للمشاريع"},"useCases":{"en":["Automating package installations for project setup","Managing dependencies for Node.js applications","Piping ''yes'' command output for non-interactive shell confirmations"],"zh":["自动化项目设置的包安装","管理Node.js应用程序的依赖","管道''yes''命令输出以进行非交互式shell确认"],"ja":["プロジェクト設定のパッケージインストールの自動化","Node.jsアプリケーションの依存関係の管理","非対話型シェル確認のための''yes''コマンドの出力をパイプする"],"ko":["프로젝트 설정을 위한 패키지 설치 자동화","노드js 애플리케이션의 의존성 관리","비대화형 셸 확인을 위한 ''yes'' 명령의 출력을 파이프"],"es":["Automatizar la instalación de paquetes para la configuración del proyecto","Gestionar dependencias para aplicaciones Node.js","Conectar la salida del comando ''yes'' para confirmaciones de shell no interactivas"],"fr":["Automatiser l''installation de packages pour la configuration du projet","Gérer les dépendances pour les applications Node.js","Transférer la sortie de la commande ''yes'' pour des confirmations de shell non interactives"],"de":["Automatisieren der Installation von Paketen für die ProjektKonfiguration","Verwalten von Abhängigkeiten für Node.js-Anwendungen","Verbinden der Ausgabe des ''yes''-Befehls für nicht-interaktive Shell-Bestätigungen"],"pt":["Automatizar instalações de pacotes para configuração de projetos","Gerenciar dependências para aplicações Node.js","Encaminhar saída do comando ''yes'' para confirmações de shell não interativas"],"ru":["Автоматизировать установку пакетов для настройки проектов","Управлять зависимостями для приложений Node.js","Перенаправлять вывод команды ''yes'' для неинтерактивных подтверждений shell"],"ar":["تأتمتة تثبيت الحزم لتهيئة المشاريع","إدارة التبعيات لتطبيقات Node.js","نقل مخرج أمر ''نعم'' لتوكيدات.shell غير تفاعلية"]},"limitations":{"en":["No interactive shell available during package installation","Requires piping output from unix ''yes'' command for confirmations"],"zh":["包安装期间无交互式shell可用","需要从unix ''yes''命令管道输出以进行确认"],"ja":["パッケージインストール中に対話型シェルは利用できない","確認のためにUnix ''yes''コマンドの出力をパイプする必要がある"],"ko":["패키지 설치 중에 대화형 셸을 사용할 수 없음","확인을 위해 유닉스 ''yes'' 명령의 출력을 파이프해야 함"],"es":["No hay shell interactivo disponible durante la instalación del paquete","Requiere conectar la salida del comando unix ''yes'' para confirmaciones"],"fr":["Aucun shell interactif disponible pendant l''installation du package","Nécessite de connecter la sortie de la commande unix ''yes'' pour des confirmations"],"de":["Kein interaktives Shell verfügbar während der Paketinstallation","Benötigt die Verbindung der Ausgabe des unix-''yes''-Befehls für Bestätigungen"],"pt":["Nenhuma shell interativa disponível durante a instalação do pacote","Requer encaminhamento de saída do comando unix ''yes'' para confirmações"],"ru":["Нет доступной интерактивной оболочки во время установки пакета","Требуется перенаправление вывода команды unix ''yes'' для подтверждений"],"ar":["لا يوجد shell تفاعلي متاح أثناء تثبيت الحزمة","يتطلب تحويل مخرج أمر يونكس ''نعم'' للتوكيدات"]},"version":3},"contentHash":"f29251d112f6ba935eed0b36ccae2696f9080bdeb7fd852846f729161f7e30f2","qualityScore":25}');
