INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OpenHands/skills/npm', 'npm', 'OpenHands', 'skills', 'community', 'npm OpenHands skills community npm 是一个包安装工具，使用 unix 的 yes 命令可以自动确认操作 npm はパッケージのインストールツールです。unix の yes コマンドを使用して操作を自動的に確認できます npm은 패키지 설치 도구로 unix의 yes 명령을 사용하여 작업을 자동으로 확인할 수 있습니다 npm es un registro público para paquetes de OpenHands que permite instalar dependencias de manera sencilla. npm est un registre public pour les packages OpenHands qui permet d''installer des dépendances de manière simple. npm ist ein öffentliches Register für OpenHands-Pakete, das das Installieren von Abhängigkeiten auf einfache Weise ermöglicht. O npm é um registro público para pacotes OpenHands, permitindo instalação sem shell interativo npm — это публичный реестр пакетов OpenHands, позволяющий устанавливать пакеты без интерактивного shell npm هو سجل عام للحزم OpenHands، يسمح بتثبيت الحزم بدون شل تفاعلي Public registry for OpenHands skills. npm 安装 unix yes 命令 JavaScript 包管理 开发工具 自动确认操作 提高开发效率 Public registry for OpenHands skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('seflless/dot-agents/baseline-ui', 'community', 'seflless', 'dot-agents', 'seflless/dot-agents', 'baseline-ui', 0, 0, 25, '2026-02-20T04:13:19.581Z', '2026-02-20T05:08:48.749Z', '0957eead1bb79f848e623f88e7616171d7a42e67c6d090af50a0558fc892f9da', '{"id":"seflless/dot-agents/baseline-ui","name":"baseline-ui","description":{"zh":"Baseline UI技能是一种强制UI基线的技能，用于防止AI生成的界面混乱，确保一致的UI设计","ja":"Baseline UIスキルは、AI生成のインターフェイスの混乱を防ぐためのUI基準の適用スキルです","ko":"베이스라인 UI 스킬은 AI 생성 인터페이스의 혼란을 방지하기 위한 UI 기준선 적용 스킬입니다","es":"Baseline UI es una herramienta que establece un estándar de interfaz de usuario para prevenir la degradación de la misma. Ayuda a mantener la coherencia en el diseño de la interfaz de usuario.","fr":"Baseline UI est un outil qui définit une ligne de base pour l''interface utilisateur afin d''éviter sa dégradation. Il aide à maintenir la cohérence dans la conception de l''interface utilisateur.","de":"Baseline UI ist ein Tool, das einen Standard für die Benutzeroberfläche setzt, um deren Verschlechterung zu verhindern. Es hilft, die Konsistenz im Design der Benutzeroberfläche zu erhalten.","pt":"O Baseline UI é uma ferramenta que ajuda a manter a consistência da interface do usuário em projetos de desenvolvimento, aplicando um conjunto de regras e padrões","ru":"Baseline UI — это инструмент, который помогает поддерживать согласованность пользовательского интерфейса в проектах разработки, применяя набор правил и стандартов","ar":"Baseline UI هي أداة تساعد على الحفاظ على الاتساق في واجهة المستخدم في مشاريع التطوير، بتطبيق مجموعة من القواعد والمعايير","en":"Back up of my .agents folder (MIT)"},"seo":{"title":{"zh":"Baseline UI技能：强制UI基线以防止AI生成的界面混乱","ja":"Baseline UIスキル：AI生成のインターフェイスの混乱を防ぐためのUI基準の適用","ko":"베이스라인 UI 스킬: AI 생성 인터페이스의 혼란을 방지하기 위한 UI 기준선 적용","es":"Baseline UI: Establece un estándar de interfaz de usuario","fr":"Baseline UI : Définit une ligne de base pour l''interface ...","de":"Baseline UI: Setzt einen Standard für die Benutzeroberfläche","pt":"Baseline UI: Padrão de Interface para Desenvolvedores","ru":"Baseline UI: Стандартный Интерфейс для Разработчиков","ar":"Baseline UI: معيار واجهة للمطورين","en":"baseline-ui"},"description":{"zh":"Baseline UI技能是一种强制UI基线的技能，用于防止AI生成的界面混乱，确保一致的UI设计","ja":"Baseline UIスキルは、AI生成のインターフェイスの混乱を防ぐためのUI基準の適用スキルです","ko":"베이스라인 UI 스킬은 AI 생성 인터페이스의 혼란을 방지하기 위한 UI 기준선 적용 스킬입니다","es":"Baseline UI es una herramienta que establece un estándar de interfaz de usuario para prevenir la degradación de la misma. Ayuda a mantener la coherencia en e...","fr":"Baseline UI est un outil qui définit une ligne de base pour l''interface utilisateur afin d''éviter sa dégradation. Il aide à maintenir la cohérence dans la co...","de":"Baseline UI ist ein Tool, das einen Standard für die Benutzeroberfläche setzt, um deren Verschlechterung zu verhindern. Es hilft, die Konsistenz im Design de...","pt":"O Baseline UI é uma ferramenta que ajuda a manter a consistência da interface do usuário em projetos de desenvolvimento, aplicando um conjunto de regras e pa...","ru":"Baseline UI — это инструмент, который помогает поддерживать согласованность пользовательского интерфейса в проектах разработки, применяя набор правил и станд...","ar":"Baseline UI هي أداة تساعد على الحفاظ على الاتساق في واجهة المستخدم في مشاريع التطوير، بتطبيق مجموعة من القواعد والمعايير","en":"Back up of my .agents folder (MIT)"},"definition":{"en":"Back up of my .agents folder (MIT)"},"features":{"zh":["强制UI基线以防止AI生成的界面混乱","确保一致的UI设计","支持Tailwind CSS默认值","提供代码级别的修复建议","能够review文件并输出违反规范的内容","能够提供为什么重要和如何修复的建议"],"ja":["AI生成のインターフェイスの混乱を防ぐためのUI基準の適用","一貫したUIデザインを保証する","Tailwind CSSのデフォルト値をサポートする","コードレベルの修正を提案する","ファイルをreviewし、規約に違反する内容を出力する","重要性と修正方法についての提案を提供する"],"ko":["AI 생성 인터페이스의 혼란을 방지하기 위한 UI 기준선 적용","일관된 UI 설계를 보장한다","Tailwind CSS 기본값 지원","코드 수준의 수정 제안","파일을 검토하고 규약에 위반하는 내용을 출력한다","중요성과 수정 방법에 대한 제안을 제공한다"],"es":["Establece un estándar de interfaz de usuario","Previene la degradación de la interfaz de usuario","Mantiene la coherencia en el diseño de la interfaz de usuario","Utiliza Tailwind CSS por defecto","Permite revisiones de código y sugerencias de corrección"],"fr":["Définit une ligne de base pour l''interface utilisateur","Évite la dégradation de l''interface utilisateur","Maintient la cohérence dans la conception de l''interface utilisateur","Utilise Tailwind CSS par défaut","Permet les révisions de code et les suggestions de correction"],"de":["Setzt einen Standard für die Benutzeroberfläche","Verhindert die Verschlechterung der Benutzeroberfläche","Erhält die Konsistenz im Design der Benutzeroberfläche","Verwendet Tailwind CSS standardmäßig","Ermöglicht Code-Reviews und Korrekturvorschläge"],"pt":["Aplicação de regras de interface","Análise de arquivos contra padrões","Sugestões de correção de código","Integração com Tailwind CSS","Suporte a desenvolvedores"],"ru":["Применение правил интерфейса","Анализ файлов против стандартов","Предложения по исправлению кода","Интеграция с Tailwind CSS","Поддержка разработчиков"],"ar":["تطبيق قواعد الواجهة","تحليل الملفات ضد المعايير","اقتراحات لتصحيح الشفرة","التكامل مع Tailwind CSS","دعم المطورين"]},"keywords":{"zh":["Baseline UI","UI基线","AI生成界面","Tailwind CSS","代码修复","UI设计","一致性","界面混乱","AI生成"],"ja":["Baseline UI","UI基準","AI生成インターフェイス","Tailwind CSS","コード修正","UIデザイン","一貫性","インターフェイスの混乱","AI生成"],"ko":["베이스라인 UI","UI 기준선","AI 생성 인터페이스","Tailwind CSS","코드 수정","UI 설계","일관성","인터페이스의 혼란","AI 생성"],"es":["Baseline UI","estándar de interfaz de usuario","diseño de interfaz de usuario","coherencia en el diseño","Tailwind CSS","revisión de código","desarrollo de software"],"fr":["Baseline UI","ligne de base pour l''interface utilisateur","conception d''interface utilisateur","cohérence dans la conception","Tailwind CSS","révision de code","développement de logiciels"],"de":["Baseline UI","Standard für die Benutzeroberfläche","Gestaltung der Benutzeroberfläche","Konsistenz im Design","Tailwind CSS","Code-Review","Software-Entwicklung"],"pt":["Baseline UI","Desenvolvimento de interface","Tailwind CSS","Regras de interface","Análise de código","Desenvolvedores","Ferramentas de desenvolvimento"],"ru":["Baseline UI","Разработка интерфейса","Tailwind CSS","Правила интерфейса","Анализ кода","Разработчики","Инструменты разработки"],"ar":["Baseline UI","تطوير واجهة","Tailwind CSS","قواعد واجهة","تحليل الشفرة","مطورون","أدوات التطوير"]}},"owner":"seflless","repo":"dot-agents","repoPath":"seflless/dot-agents","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"baseline-ui","description":"Enforces an opinionated UI baseline to prevent AI-generated interface slop.","bodyPreview":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requ","body":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requested\n- MUST use `motion/react` (formerly `framer-motion`) when JavaScript animation is required\n- SHOULD use `tw-animate-css` for entrance and micro-animations in Tailwind CSS\n- MUST use `cn` utility (`clsx` + `tailwind-merge`) for class logic\n\n## Components\n\n- MUST use accessible component primitives for anything with keyboard or focus behavior (`Base UI`, `React Aria`, `Radix`)\n- MUST use the project’s existing component primitives first\n- NEVER mix primitive systems within the same interaction surface\n- SHOULD prefer [`Base UI`](https://base-ui.com/react/components) for new primitives if compatible with the stack\n- MUST add an `aria-label` to icon-only buttons\n- NEVER rebuild keyboard or focus behavior by hand unless explicitly requested\n\n## Interaction\n\n- MUST use an `AlertDialog` for destructive or irreversible actions\n- SHOULD use structural skeletons for loading states\n- NEVER use `h-screen`, use `h-dvh`\n- MUST respect `safe-area-inset` for fixed elements\n- MUST show errors next to where the action happens\n- NEVER block paste in `input` or `textarea` elements\n\n## Animation\n\n- NEVER add animation unless it is explicitly requested\n- MUST animate only compositor props (`transform`, `opacity`)\n- NEVER animate layout properties (`width`, `height`, `top`, `left`, `margin`, `padding`)\n- SHOULD avoid animating paint properties (`background`, `color`) except for small, local UI (text, icons)\n- SHOULD use `ease-out` on entrance\n- NEVER exceed `200ms` for interaction feedback\n- MUST pause looping animations when off-screen\n- SHOULD respect `prefers-reduced-motion`\n- NEVER introduce custom easing curves unless explicitly requested\n- SHOULD avoid animating large images or full-screen surfaces\n\n## Typography\n\n- MUST use `text-balance` for headings and `text-pretty` for body/paragraphs\n- MUST use `tabular-nums` for data\n- SHOULD use `truncate` or `line-clamp` for dense UI\n- NEVER modify `letter-spacing` (`tracking-*`) unless explicitly requested\n\n## Layout\n\n- MUST use a fixed `z-index` scale (no arbitrary `z-*`)\n- SHOULD use `size-*` for square elements instead of `w-*` + `h-*`\n\n## Performance\n\n- NEVER animate large `blur()` or `backdrop-filter` surfaces\n- NEVER apply `will-change` outside an active animation\n- NEVER use `useEffect` for anything that can be expressed as render logic\n\n## Design\n\n- NEVER use gradients unless explicitly requested\n- NEVER use purple or multicolor gradients\n- NEVER use glow effects as primary affordances\n- SHOULD use Tailwind CSS default shadow scale unless explicitly requested\n- MUST give empty states one clear next action\n- SHOULD limit accent color usage to one per view\n- SHOULD use existing theme or Tailwind CSS color tokens before introducing new ones\n"},"lastSynced":"2026-02-20T05:08:48.749Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring standardized UI development with Tailwind CSS defaults","zh":"适合需要标准化UI开发的前端代理，使用Tailwind CSS默认设置","ja":"Tailwind CSSのデフォルト設定を使用して標準化されたUI開発を必要とするフロントエンドエージェントに最適","ko":"Tailwind CSS 기본 설정을 사용하여 표준화된 UI 개발을 요구하는 프론트엔드 에이전트에 적합","es":"Ideal para agentes frontend que requieren un desarrollo de interfaz de usuario estandarizado con valores predeterminados de Tailwind CSS","fr":"Idéal pour les agents frontend nécessitant un développement d''interface utilisateur standardisé avec des valeurs par défaut de Tailwind CSS","de":"Ideal für Frontend-Agents, die ein standardisiertes UI-Entwicklung mit Tailwind-CSS-Standardwerten erfordern","pt":"Ideal para Agentes Frontend que exigem desenvolvimento de UI padronizado com padrões Tailwind CSS","ru":"Идеально подходит для фронтенд-агентов, требующих стандартизированного развития UI с настройками Tailwind CSS по умолчанию","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب تطوير واجهة مستخدم معيارية مع إعدادات Tailwind CSS افتراضية"},"recommendation":{"en":"Enforces a strict UI baseline, utilizing Tailwind CSS to prevent interface inconsistencies and provides code-level suggestions for fixes, ensuring adherence to established constraints and best practices","zh":"强制执行严格的UI基线，利用Tailwind CSS防止接口不一致，并提供代码级别的建议以确保遵守既定的约束和最佳实践","ja":"厳格なUIベースラインを適用し、Tailwind CSSを使用してインターフェイスの不一致を防止し、既定の制約とベストプラクティスに従うようにコードレベルの提案を提供する","ko":"严格한 UI 기준선을 적용하고 Tailwind CSS를 사용하여 인터페이스의 불일치를 방지하며 코드 수준의 제안을 제공하여 정해진 제약과 최고의 관행을 따르도록 함","es":"Establece una línea de base de interfaz de usuario estricta, utilizando Tailwind CSS para prevenir inconsistencias en la interfaz y proporciona sugerencias de código para solucionar problemas, garantizando el cumplimiento de las restricciones y las mejores prácticas establecidas","fr":"Met en place une ligne de base d''interface utilisateur stricte, en utilisant Tailwind CSS pour prévenir les incohérences d''interface et fournit des suggestions de code pour les corrections, garantissant le respect des contraintes et des meilleures pratiques établies","de":"Erzwingt eine strenge UI-Baselinie, indem Tailwind CSS verwendet wird, um Schnittstelleninkonsistenzen zu verhindern und bietet codebasierte Vorschläge für Korrekturen, um die Einhaltung etablierter Einschränkungen und Best Practices sicherzustellen","pt":"Impõe uma linha de base de UI estrita, utilizando Tailwind CSS para prevenir inconsistências de interface e fornece sugestões de nível de código para correções, garantindo a adesão a restrições e práticas recomendadas estabelecidas","ru":"Запрашивает строгую базовую линию UI, используя Tailwind CSS для предотвращения несоответствий интерфейса и предоставляет предложения на уровне кода для исправлений, обеспечивая соблюдение установленных ограничений и лучших практик","ar":"فرض خط قاعدي صارم لواجهة المستخدم، باستخدام Tailwind CSS لمنع عدم الاتساق في الواجهة وتقديم اقتراحات على مستوى الكود لتصحيحات، مما يضمن الامتثال للقيود وأفضل الممارسات المحددة"},"useCases":{"en":["Applying UI constraints to conversation outputs","Reviewing files against predefined UI standards","Generating concrete fixes for UI violations"],"zh":["将UI约束应用于会话输出","审查文件以满足预定义的UI标准","生成具体的修复方案以解决UI违规"],"ja":["会話出力にUI制約を適用する","事前定義されたUI標準に対するファイルのレビュー","UI違反に対する具体的な修正を生成する"],"ko":["대화 출력에 UI 제약을 적용","사전 정의된 UI 표준에 대한 파일 검토","UI 위반에 대한 구체적인 수정을 생성"],"es":["Aplicar restricciones de interfaz de usuario a salidas de conversación","Revisar archivos contra normas de interfaz de usuario predefinidas","Generar soluciones concretas para violaciones de interfaz de usuario"],"fr":["Appliquer des contraintes d''interface utilisateur aux sorties de conversation","Réviser les fichiers contre des normes d''interface utilisateur prédéfinies","Générer des solutions concrètes pour les violations d''interface utilisateur"],"de":["UI-Einschränkungen auf Konversationsausgaben anwenden","Dateien gegen vordefinierte UI-Standards überprüfen","Konkrete Korrekturen für UI-Verletzungen generieren"],"pt":["Aplicar restrições de UI às saídas de conversa","Revisar arquivos contra padrões de UI predefinidos","Gerar correções concretas para violações de UI"],"ru":["Применение ограничений UI к выводам разговора","Проверка файлов против предопределенных стандартов UI","Генерация конкретных исправлений для нарушений UI"],"ar":["تطبيق قيود واجهة المستخدم على مخرجات المحادثة","مراجعة الملفات ضد معايير واجهة المستخدم المحددة مسبقا","توليد تصحيحات ملموسة للانتهاكات لواجهة المستخدم"]},"limitations":{"en":["Requires Tailwind CSS defaults unless custom values exist","Limited to reviewing files against predefined constraints"],"zh":["需要Tailwind CSS默认设置，除非自定义值存在","仅限于审查文件以满足预定义的约束"],"ja":["カスタム値が存在しない限り、Tailwind CSSのデフォルト設定が必要","事前定義された制約に対するファイルのレビューのみ"],"ko":["사용자 정의 값이 있는 경우를 제외하고 Tailwind CSS 기본 설정이 필요","사전 정의된 제약 조건에 대한 파일 검토에만 제한"],"es":["Requiere valores predeterminados de Tailwind CSS a menos que existan valores personalizados","Limitado a la revisión de archivos contra restricciones predefinidas"],"fr":["Nécessite des valeurs par défaut de Tailwind CSS à moins que des valeurs personnalisées existent","Limité à la révision de fichiers contre des contraintes prédéfinies"],"de":["Benötigt Tailwind-CSS-Standardwerte, sofern nicht benutzerdefinierte Werte vorhanden sind","Begrenzt auf die Überprüfung von Dateien gegen vordefinierte Einschränkungen"],"pt":["Exige padrões Tailwind CSS a menos que existam valores personalizados","Limitado a revisar arquivos contra restrições predefinidas"],"ru":["Требует настроек Tailwind CSS по умолчанию, если не существуют пользовательские значения","Ограничен проверкой файлов против предопределенных ограничений"],"ar":["يتطلب إعدادات Tailwind CSS افتراضية ما لم تكن هناك قيم مخصصة","محدود بالمراجعة الملفات ضد القيود المحددة مسبقا"]},"version":3},"contentHash":"0957eead1bb79f848e623f88e7616171d7a42e67c6d090af50a0558fc892f9da","qualityScore":25}');
