INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('seflless/dot-agents/baseline-ui', 'baseline-ui', 'seflless', 'dot-agents', 'community', 'baseline-ui seflless dot-agents community Baseline UI技能是一种强制UI基线的技能，用于防止AI生成的界面混乱，确保一致的UI设计 Baseline UIスキルは、AI生成のインターフェイスの混乱を防ぐためのUI基準の適用スキルです 베이스라인 UI 스킬은 AI 생성 인터페이스의 혼란을 방지하기 위한 UI 기준선 적용 스킬입니다 Baseline UI es una herramienta que establece un estándar de interfaz de usuario para prevenir la degradación de la misma. Ayuda a mantener la coherencia en el diseño de la interfaz de usuario. Baseline UI est un outil qui définit une ligne de base pour l''interface utilisateur afin d''éviter sa dégradation. Il aide à maintenir la cohérence dans la conception de l''interface utilisateur. Baseline UI ist ein Tool, das einen Standard für die Benutzeroberfläche setzt, um deren Verschlechterung zu verhindern. Es hilft, die Konsistenz im Design der Benutzeroberfläche zu erhalten. O Baseline UI é uma ferramenta que ajuda a manter a consistência da interface do usuário em projetos de desenvolvimento, aplicando um conjunto de regras e padrões Baseline UI — это инструмент, который помогает поддерживать согласованность пользовательского интерфейса в проектах разработки, применяя набор правил и стандартов Baseline UI هي أداة تساعد على الحفاظ على الاتساق في واجهة المستخدم في مشاريع التطوير، بتطبيق مجموعة من القواعد والمعايير Back up of my .agents folder (MIT) Baseline UI UI基线 AI生成界面 Tailwind CSS 代码修复 UI设计 一致性 界面混乱 AI生成 Back up of my .agents folder (MIT)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ihj04982/my-cursor-settings/baseline-ui', 'community', 'ihj04982', 'my-cursor-settings', 'ihj04982/my-cursor-settings', 'baseline-ui', 0, 0, 25, '2026-02-20T04:13:19.581Z', '2026-02-20T05:09:05.056Z', '0957eead1bb79f848e623f88e7616171d7a42e67c6d090af50a0558fc892f9da', '{"id":"ihj04982/my-cursor-settings/baseline-ui","name":"baseline-ui","description":{"zh":"Baseline UI是一种用于前端开发的标准化UI工具，确保界面的一致性和美观","ja":"Baseline UIは、フロントエンド開発のための標準化UIツールで、UIの一貫性と美観を確保します","ko":"Baseline UI는 프론트엔드 개발을 위한 표준화된 UI 도구로 인터페이스의 일관성과 아름다움을 보장합니다","es":"Baseline UI es una herramienta que aplica un conjunto de reglas para mantener un estándar en la interfaz de usuario. Ayuda a prevenir la generación de interfaces inconsistentes.","fr":"Baseline UI est un outil qui applique un ensemble de règles pour maintenir une norme dans l''interface utilisateur. Il aide à prévenir la génération d''interfaces incohérentes.","de":"Baseline UI ist ein Tool, das einen Satz von Regeln anwendet, um einen Standard in der Benutzeroberfläche beizubehalten. Es hilft, die Generierung inkonsistenter Schnittstellen zu verhindern.","pt":"O Baseline UI é um conjunto de diretrizes para garantir a consistência da interface do usuário em projetos de desenvolvimento frontend, usando Tailwind CSS","ru":"Baseline UI - это набор руководств для обеспечения согласованности пользовательского интерфейса в проектах frontend-разработки, использующих Tailwind CSS","ar":"Baseline UI هو مجموعة من المبادئ التوجيهية لضمان συνέность واجهة المستخدم في مشاريع تطوير الواجهة الأمامية، باستخدام Tailwind CSS","en":"프론트엔드 개발을 위한 커서 세팅"},"seo":{"title":{"zh":"Baseline UI：前端开发的标准化界面","ja":"Baseline UI：フロントエンド開発のための標準化UI","ko":"Baseline UI: 프론트엔드 개발을 위한 표준화된 인터페이스","es":"Baseline UI: Establece un estándar de interfaz de usuario","fr":"Baseline UI : Définir une norme d''interface utilisateur","de":"Baseline UI: Ein UI-Standard festlegen","pt":"Baseline UI: Padrão de Interface para Desenvolvedores","ru":"Baseline UI: Стандартный Интерфейс для Разработчиков","ar":"Baseline UI: معيار واجهة المستخدم للمانحين","en":"baseline-ui"},"description":{"zh":"Baseline UI是一种用于前端开发的标准化UI工具，确保界面的一致性和美观","ja":"Baseline UIは、フロントエンド開発のための標準化UIツールで、UIの一貫性と美観を確保します","ko":"Baseline UI는 프론트엔드 개발을 위한 표준화된 UI 도구로 인터페이스의 일관성과 아름다움을 보장합니다","es":"Baseline UI es una herramienta que aplica un conjunto de reglas para mantener un estándar en la interfaz de usuario. Ayuda a prevenir la generación de interf...","fr":"Baseline UI est un outil qui applique un ensemble de règles pour maintenir une norme dans l''interface utilisateur. Il aide à prévenir la génération d''interfa...","de":"Baseline UI ist ein Tool, das einen Satz von Regeln anwendet, um einen Standard in der Benutzeroberfläche beizubehalten. Es hilft, die Generierung inkonsiste...","pt":"O Baseline UI é um conjunto de diretrizes para garantir a consistência da interface do usuário em projetos de desenvolvimento frontend, usando Tailwind CSS","ru":"Baseline UI - это набор руководств для обеспечения согласованности пользовательского интерфейса в проектах frontend-разработки, использующих Tailwind CSS","ar":"Baseline UI هو مجموعة من المبادئ التوجيهية لضمان συνέность واجهة المستخدم في مشاريع تطوير الواجهة الأمامية، باستخدام Tailwind CSS","en":"프론트엔드 개발을 위한 커서 세팅"},"definition":{"en":"프론트엔드 개발을 위한 커서 세팅"},"features":{"zh":["标准化UI","一致的界面设计","自动化代码审查","Tailwind CSS集成","代码级别的修复建议"],"ja":["標準化UI","一貫したUIデザイン","自動化コードレビュー","Tailwind CSS統合","コードレベルの修正提案"],"ko":["표준화된 UI","일관된 인터페이스 디자인","자동화된 코드 리뷰","Tailwind CSS 통합","코드 수준의 수정 제안"],"es":["Aplica un conjunto de reglas para mantener la coherencia en la interfaz de usuario","Previene la generación de interfaces inconsistentes","Utiliza Tailwind CSS por defecto","Permite revisar archivos contra las reglas establecidas","Proporciona sugerencias de código para solucionar violaciones"],"fr":["Applique un ensemble de règles pour maintenir la cohérence dans l''interface utilisateur","Prévenir la génération d''interfaces incohérentes","Utilise Tailwind CSS par défaut","Permet de réviser les fichiers contre les règles établies","Fournit des suggestions de code pour résoudre les violations"],"de":["Wendet einen Satz von Regeln an, um die Konsistenz in der Benutzeroberfläche beizubehalten","Verhindert die Generierung inkonsistenter Schnittstellen","Verwendet Tailwind CSS standardmäßig","Ermöglicht die Überprüfung von Dateien gegen die festgelegten Regeln","Bietet Code-Vorschläge, um Verstöße zu beheben"],"pt":["Fornece um conjunto de regras para garantir a consistência da interface do usuário","Usa Tailwind CSS como padrão","Permite a revisão de arquivos contra as regras definidas","Fornece sugestões concretas para corrigir violações","Melhora a experiência do usuário com uma interface consistente"],"ru":["Предоставляет набор правил для обеспечения согласованности пользовательского интерфейса","Использует Tailwind CSS в качестве стандарта","Позволяет просматривать файлы против определенных правил","Предоставляет конкретные предложения для исправления нарушений","Улучшает опыт пользователя с помощью согласованного интерфейса"],"ar":["يوفر مجموعة من القواعد لضمان συνέность واجهة المستخدم","يستخدم Tailwind CSS كمعيار","يسمح بمراجعة الملفات ضد القواعد المحددة","يوفر مقترحات ملموسة لتصحيح الانتهاكات","يحسن من تجربة المستخدم مع واجهة متسقة"]},"keywords":{"zh":["前端开发","标准化UI","一致的界面设计","Tailwind CSS","代码审查","自动化开发工具"],"ja":["フロントエンド開発","標準化UI","一貫したUIデザイン","Tailwind CSS","コードレビュー","自動化開発ツール"],"ko":["프론트엔드 개발","표준화된 UI","일관된 인터페이스 디자인","Tailwind CSS","코드 리뷰","자동화 개발 도구"],"es":["Baseline UI","interfaz de usuario","desarrollo frontend","coherencia en el diseño","Tailwind CSS","reglas de interfaz de usuario","diseño de interfaz de usuario","desarrollo de software"],"fr":["Baseline UI","interface utilisateur","développement frontend","cohérence dans la conception","Tailwind CSS","règles d''interface utilisateur","conception d''interface utilisateur","développement de logiciels"],"de":["Baseline UI","Benutzeroberfläche","Frontend-Entwicklung","Konsistenz im Design","Tailwind CSS","Benutzeroberflächen-Regeln","Benutzeroberflächen-Design","Software-Entwicklung"],"pt":["Baseline UI","Desenvolvimento frontend","Tailwind CSS","Interface do usuário","Consistência visual","Regras de interface","Desenvolvimento de software","Experiência do usuário"],"ru":["Baseline UI","Frontend-разработка","Tailwind CSS","Пользовательский интерфейс","Визуальная согласованность","Правила интерфейса","Разработка программного обеспечения","Опыт пользователя"],"ar":["Baseline UI","تطوير الواجهة الأمامية","Tailwind CSS","واجهة المستخدم","التناسق البصري","قواعد الواجهة","تطوير البرمجيات","تجربة المستخدم"]}},"owner":"ihj04982","repo":"my-cursor-settings","repoPath":"ihj04982/my-cursor-settings","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"baseline-ui","description":"Enforces an opinionated UI baseline to prevent AI-generated interface slop.","bodyPreview":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requ","body":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requested\n- MUST use `motion/react` (formerly `framer-motion`) when JavaScript animation is required\n- SHOULD use `tw-animate-css` for entrance and micro-animations in Tailwind CSS\n- MUST use `cn` utility (`clsx` + `tailwind-merge`) for class logic\n\n## Components\n\n- MUST use accessible component primitives for anything with keyboard or focus behavior (`Base UI`, `React Aria`, `Radix`)\n- MUST use the project’s existing component primitives first\n- NEVER mix primitive systems within the same interaction surface\n- SHOULD prefer [`Base UI`](https://base-ui.com/react/components) for new primitives if compatible with the stack\n- MUST add an `aria-label` to icon-only buttons\n- NEVER rebuild keyboard or focus behavior by hand unless explicitly requested\n\n## Interaction\n\n- MUST use an `AlertDialog` for destructive or irreversible actions\n- SHOULD use structural skeletons for loading states\n- NEVER use `h-screen`, use `h-dvh`\n- MUST respect `safe-area-inset` for fixed elements\n- MUST show errors next to where the action happens\n- NEVER block paste in `input` or `textarea` elements\n\n## Animation\n\n- NEVER add animation unless it is explicitly requested\n- MUST animate only compositor props (`transform`, `opacity`)\n- NEVER animate layout properties (`width`, `height`, `top`, `left`, `margin`, `padding`)\n- SHOULD avoid animating paint properties (`background`, `color`) except for small, local UI (text, icons)\n- SHOULD use `ease-out` on entrance\n- NEVER exceed `200ms` for interaction feedback\n- MUST pause looping animations when off-screen\n- SHOULD respect `prefers-reduced-motion`\n- NEVER introduce custom easing curves unless explicitly requested\n- SHOULD avoid animating large images or full-screen surfaces\n\n## Typography\n\n- MUST use `text-balance` for headings and `text-pretty` for body/paragraphs\n- MUST use `tabular-nums` for data\n- SHOULD use `truncate` or `line-clamp` for dense UI\n- NEVER modify `letter-spacing` (`tracking-*`) unless explicitly requested\n\n## Layout\n\n- MUST use a fixed `z-index` scale (no arbitrary `z-*`)\n- SHOULD use `size-*` for square elements instead of `w-*` + `h-*`\n\n## Performance\n\n- NEVER animate large `blur()` or `backdrop-filter` surfaces\n- NEVER apply `will-change` outside an active animation\n- NEVER use `useEffect` for anything that can be expressed as render logic\n\n## Design\n\n- NEVER use gradients unless explicitly requested\n- NEVER use purple or multicolor gradients\n- NEVER use glow effects as primary affordances\n- SHOULD use Tailwind CSS default shadow scale unless explicitly requested\n- MUST give empty states one clear next action\n- SHOULD limit accent color usage to one per view\n- SHOULD use existing theme or Tailwind CSS color tokens before introducing new ones\n"},"lastSynced":"2026-02-20T05:09:05.056Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring standardized UI development with Tailwind CSS defaults.","zh":"适合需要使用 Tailwind CSS 默认值进行标准化 UI 开发的前端代理。","ja":"Tailwind CSS デフォルトを使用した標準化された UI 開発が必要なフロントエンド エージェントに最適です。","ko":"Tailwind CSS 기본값을 사용하여 표준화된 UI 개발이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Ideal para agentes frontend que requieren desarrollo de UI estandarizado con valores predeterminados de Tailwind CSS.","fr":"Idéal pour les agents frontend nécessitant un développement d''UI standardisé avec des valeurs par défaut de Tailwind CSS.","de":"Ideal für Frontend-Agents, die ein standardisiertes UI-Entwicklung mit Tailwind-CSS-Standardwerten erfordern.","pt":"Ideal para Agentes Frontend que exigem desenvolvimento de UI padronizado com padrões Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, требующих стандартизированного разработки UI с использованием настроек Tailwind CSS по умолчанию.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب تطويرًا موحدًا لواجهة المستخدم مع إعدادات Tailwind CSS الافتراضية."},"recommendation":{"en":"Empowers agents to enforce an opinionated UI baseline, preventing interface slop and ensuring consistency, using Tailwind CSS and providing concrete code-level suggestions for fixes.","zh":"赋予代理人执行有见解的 UI 基线的能力，防止界面混乱，确保一致性，使用 Tailwind CSS 并提供具体的代码级别的修复建议。","ja":"エージェントに、意見のある UI ベースラインを施行する能力を与え、インターフェイスの混乱を防ぎ、整合性を確保し、Tailwind CSS を使用し、修正のための具体的なコードレベルの提案を提供します。","ko":"에이전트에 의견이 있는 UI 기준을施行하는 능력을 부여하여 인터페이스의 부스러기를 방지하고 일관성을 보장하며 Tailwind CSS를 사용하고 수정을 위한 구체적인 코드 수준의 제안을 제공합니다.","es":"Permite a los agentes aplicar una línea de base de UI con opiniones, evitando la inconsistencia en la interfaz y asegurando la coherencia, utilizando Tailwind CSS y proporcionando sugerencias concretas a nivel de código para correcciones.","fr":"Permet aux agents d''appliquer une ligne de base d''UI avec des opinions, empêchant la perte d''interface et assurant la cohérence, en utilisant Tailwind CSS et en fournissant des suggestions concrètes au niveau du code pour les corrections.","de":"Ermöglicht es Agents, eine Meinungsbasierte UI-Grundlinie durchzusetzen, eine schlechte Schnittstelle zu verhindern und Konsistenz sicherzustellen, unter Verwendung von Tailwind CSS und konkrete Code-Ebene Vorschläge für Korrekturen bereitzustellen.","pt":"Habilita os agentes a impor uma linha de base de UI opinativa, prevenindo a falta de padronização da interface e garantindo a consistência, usando Tailwind CSS e fornecendo sugestões concretas de nível de código para correções.","ru":"Наделяет агентов возможностью реализовывать opinative базовый уровень UI, предотвращая неряшливость интерфейса и гарантируя последовательность, используя Tailwind CSS и предоставляя конкретные предложения кодового уровня для исправлений.","ar":"يمنح الوكيل القدرة على فرض قاعدة موحدة لواجهة المستخدم، ومنع عدم انتظام الواجهة وضمان الاتساق، باستخدام Tailwind CSS وتوفير مقترحات ملموسة على مستوى الكود للاصلاحات."},"useCases":{"en":["Applying UI constraints to prevent sloppiness in AI-generated interfaces","Reviewing files against predefined UI standards and outputting violations and fixes","Enforcing Tailwind CSS defaults for consistent styling across UI components"],"zh":["将 UI 约束应用于防止 AI 生成的接口中的混乱","审查文件以符合预定义的 UI 标准并输出违规和修复","施行 Tailwind CSS 默认值以在 UI 组件中实现一致的样式"],"ja":["AI 生成のインターフェイスにおけるスロッピさを防ぐために UI 制約を適用する","事前に定義された UI 標準に従ってファイルをレビューし、違反と修正を出力する","UI コンポーネント全体で一貫したスタイリングを実現するために Tailwind CSS デフォルトを施行する"],"ko":["AI 생성 인터페이스의 부스러기를 방지하기 위해 UI 제약을 적용한다","사전에 정의된 UI 표준에 따라 파일을 검토하고 위반 및 수정을 출력한다","UI 컴포넌트 전반에 걸쳐 일관된 스타일링을 달성하기 위해 Tailwind CSS 기본값을 적용한다"],"es":["Aplicar restricciones de UI para prevenir la desorden en las interfaces generadas por IA","Revisar archivos contra estándares de UI predefinidos y salida de violaciones y correcciones","Aplicar valores predeterminados de Tailwind CSS para un estilo coherente en todos los componentes de UI"],"fr":["Appliquer des contraintes d''UI pour prévenir la perte dans les interfaces générées par l''IA","Réviser les fichiers contre des normes d''UI prédéfinies et sortir les violations et les corrections","Appliquer les valeurs par défaut de Tailwind CSS pour un style cohérent dans tous les composants d''UI"],"de":["UI-Einschränkungen anwenden, um Unordentlichkeit in von KI generierten Schnittstellen zu verhindern","Dateien gegen vorgegebene UI-Standards überprüfen und Verletzungen und Korrekturen ausgeben","Tailwind-CSS-Standardwerte anwenden, um ein konsistentes Styling über alle UI-Komponenten hinweg sicherzustellen"],"pt":["Aplicação de restrições de UI para prevenir a falta de padronização em interfaces geradas por IA","Revisão de arquivos contra padrões de UI pré-definidos e saída de violações e correções","Impor padrões Tailwind CSS para estilização consistente em componentes de UI"],"ru":["Применение ограничений UI для предотвращения неряшливости в интерфейсах, сгенерированных ИИ","Проверка файлов против заранее определенных стандартов UI и вывод нарушений и исправлений","Реализация настроек Tailwind CSS для последовательного стиля в компонентах UI"],"ar":["تطبيق قيود على واجهة المستخدم لمنع عدم انتظام واجهات المستخدم التي تم إنشاؤها بواسطة الذكاء الاصطناعي","مراجعة الملفات ضد معايير واجهة المستخدم المحددة مسبقًا وإخراج انتهاكات وتصحيحات","تطبيق إعدادات Tailwind CSS للحصول على تنسيق متسق عبر مكونات واجهة المستخدم"]},"limitations":{"en":["Requires use of Tailwind CSS defaults unless custom values exist","Limited to frontend development and UI-related tasks"],"zh":["需要使用 Tailwind CSS 默认值，除非自定义值存在","仅限于前端开发和 UI 相关任务"],"ja":["カスタム値が存在しない限り、Tailwind CSS デフォルトを使用する必要がある","フロントエンド開発と UI 関連タスクのみに限定される"],"ko":["사용자 정의 값이 존재하지 않는 한 Tailwind CSS 기본값을 사용해야 함","프론트엔드 개발 및 UI 관련 작업에만 제한됨"],"es":["Requiere el uso de valores predeterminados de Tailwind CSS a menos que existan valores personalizados","Limitado al desarrollo frontend y tareas relacionadas con la UI"],"fr":["Nécessite l''utilisation de valeurs par défaut de Tailwind CSS à moins que des valeurs personnalisées existent","Limité au développement frontend et aux tâches liées à l''UI"],"de":["Erfordert die Verwendung von Tailwind-CSS-Standardwerten, es sei denn, benutzerdefinierte Werte existieren","Begrenzt auf Frontend-Entwicklung und UI-bezogene Aufgaben"],"pt":["Exige o uso de padrões Tailwind CSS, a menos que existam valores personalizados","Limitado ao desenvolvimento frontend e tarefas relacionadas à UI"],"ru":["Требует использования настроек Tailwind CSS по умолчанию, если не существуют пользовательские значения","Ограничен разработкой frontend и задачами, связанными с UI"],"ar":["يتطلب استخدام إعدادات Tailwind CSS الافتراضية، إلا إذا كانت هناك قيم مخصصة","محدود بالتطوير الأمامي وتasks ذات الصلة بواجهة المستخدم"]},"version":3},"contentHash":"0957eead1bb79f848e623f88e7616171d7a42e67c6d090af50a0558fc892f9da","qualityScore":25}');
