INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ihj04982/my-cursor-settings/baseline-ui', 'baseline-ui', 'ihj04982', 'my-cursor-settings', 'community', 'baseline-ui ihj04982 my-cursor-settings community Baseline UI是一种用于前端开发的标准化UI工具，确保界面的一致性和美观 Baseline UIは、フロントエンド開発のための標準化UIツールで、UIの一貫性と美観を確保します Baseline UI는 프론트엔드 개발을 위한 표준화된 UI 도구로 인터페이스의 일관성과 아름다움을 보장합니다 Baseline UI es una herramienta que aplica un conjunto de reglas para mantener un estándar en la interfaz de usuario. Ayuda a prevenir la generación de interfaces inconsistentes. Baseline UI est un outil qui applique un ensemble de règles pour maintenir une norme dans l''interface utilisateur. Il aide à prévenir la génération d''interfaces incohérentes. Baseline UI ist ein Tool, das einen Satz von Regeln anwendet, um einen Standard in der Benutzeroberfläche beizubehalten. Es hilft, die Generierung inkonsistenter Schnittstellen zu verhindern. O Baseline UI é um conjunto de diretrizes para garantir a consistência da interface do usuário em projetos de desenvolvimento frontend, usando Tailwind CSS Baseline UI - это набор руководств для обеспечения согласованности пользовательского интерфейса в проектах frontend-разработки, использующих Tailwind CSS Baseline UI هو مجموعة من المبادئ التوجيهية لضمان συνέность واجهة المستخدم في مشاريع تطوير الواجهة الأمامية، باستخدام Tailwind CSS 프론트엔드 개발을 위한 커서 세팅 前端开发 标准化UI 一致的界面设计 Tailwind CSS 代码审查 自动化开发工具 프론트엔드 개발을 위한 커서 세팅');
