INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wowsignal-io/pedro/setup [dev]', 'setup [dev]', 'wowsignal-io', 'pedro', 'community', 'setup [dev] wowsignal-io pedro community The setup [dev] skill helps developers set up the Pedro repository, ensuring a smooth build and test process for the open-source EDR on Linux. setup [dev] 是一个用于设置Pedro仓库的技能，包括切换到正确的分支和更新git子模块等步骤 setup [dev]はPedroリポジトリを設定するスキルで、ブランチの切り替えとgitサブモジュールの更新などが含まれています setup [dev]는 Pedro 리포지토리를 설정하는 데 사용되는 스킬로, 브랜치 전환 및 Git 서브모듈 업데이트 등을 포함합니다 Configura Pedro EDR, una herramienta de detección y respuesta de puntos finales de código abierto para Linux, con nuestra guía de setup para desarrolladores. Aprende a configurar el repositorio y a ejecutar tests Configurez Pedro EDR, un outil de détection et de réponse de points de terminaison open source pour Linux, avec notre guide de setup pour les développeurs. Découvrez comment configurer le référentiel et exécuter des tests Richten Sie Pedro EDR, ein Open-Source-Endgeräte-Erkennungs- und -Reaktions-Tool für Linux, mit unserer Setup-Anleitung für Entwickler ein. Erfahren Sie, wie Sie das Repository konfigurieren und Tests ausführen O setup [dev] é uma ferramenta para configurar o Pet EDR Operation, uma solução de código aberto para Linux. Настройка setup [dev] предназначена для конфигурации Pet EDR Operation, легковесного ИИ Агента для Linux. إعداد setup [dev] هو أداة لتشغيل Pet EDR Operation، حل مفتوح المصدر لINUX. how to use setup [dev] setup [dev] install guide Pedro repository setup git submodule update git pull --rebase setup [dev] vs other EDRs Linux EDR setup setup [dev] alternative setup [dev] Pedro仓库 git子模块 git pull --rebase vendor/abseil-cp 快速入门 AI工具 设置指南 Switches to the right branch and performs a git pull --rebase Ensures git submodules are checked out with git submodule update --init --recursive Verifies vendor/abseil-cpp checkout Supports development on the dev branch Runs tests to validate the repository setup Uses git commands for repository management setup [dev] is a technical skill for initializing the Pedro repository, covering branch switching, git submodule updates, and test execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kaihendry/dabase.com/blog', 'community', 'kaihendry', 'dabase.com', 'kaihendry/dabase.com', 'blog', 7, 8, 23, '2026-02-26T14:17:09Z', '2026-03-06T06:50:29.566Z', '3b1f13f0f676037a24c9b792711e4b0eadcc7e0e9164bcb22e91c519aec9a17d', '{"id":"kaihendry/dabase.com/blog","name":"blog","description":{"en":"This skill helps developers create new blog posts for their Hugo-based blog, generating SEO-friendly titles and descriptions. It benefits developers looking to streamline their blogging workflow.","zh":"Kai Hendry的技术博客使用Hugo和ikiwiki，提供快速创建SEO友好的博客文章的方法","ja":"Kai HendryのテクノロジーブログはHugoとikiwikiを使用しており、SEO対応のブログ記事を作成するための迅速な方法を提供します","ko":"Kai Hendry의 기술 블로그는 Hugo 및 ikiwiki를 사용하여 SEO 최적화된 블로그 게시물 생성을 위한 빠른 방법을 제공합니다","es":"Nuestra herramienta de blog te ayuda a crear publicaciones con títulos y descripciones SEO-friendly para tu blog basado en Hugo. Aprovecha tecnologías como ikiwiki para mejorar tu experiencia de blogueo","fr":"Notre outil de blog vous aide à créer des publications avec des titres et des descriptions SEO-friendly pour votre blog basé sur Hugo. Profitez des technologies comme ikiwiki pour améliorer votre expérience de blogue","de":"Unser Blog-Tool hilft Ihnen, Beiträge mit SEO-freundlichen Titeln und Beschreibungen für Ihren Hugo-basierten Blog zu erstellen. Nutzen Sie Technologien wie ikiwiki, um Ihre Blog-Erfahrung zu verbessern","pt":"Criar um blog com Hugo e IKIWiki é fácil com nossa guia. Aprenda a criar títulos amigáveis e descrições para SEO","ru":"ИИ Агенты помогают создать блог с Hugo и IKIWiki. Узнайте, как создать привлекательные заголовки и описания для поисковых систем","ar":"إنشاء مدونة مع Hugo و IKIWiki أصبح أكثر سهولة مع أدوات الذكاء الاصطناعي. تعرف على كيفية إنشاء عناوين ووصف للمدونة"},"seo":{"title":{"en":"Blog: Hugo-Based Post Creation Setup Guide | AI Agent Skill","zh":"Hugo博客搭建