INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kaihendry/dabase.com/blog', 'blog', 'kaihendry', 'dabase.com', 'community', 'blog kaihendry dabase.com community blog hendry hugo ikiwiki tech tips wiki This skill helps developers create new blog posts for their Hugo-based blog, generating SEO-friendly titles and descriptions. It benefits developers looking to streamline their blogging workflow. Kai Hendry的技术博客使用Hugo和ikiwiki，提供快速创建SEO友好的博客文章的方法 Kai HendryのテクノロジーブログはHugoとikiwikiを使用しており、SEO対応のブログ記事を作成するための迅速な方法を提供します Kai Hendry의 기술 블로그는 Hugo 및 ikiwiki를 사용하여 SEO 최적화된 블로그 게시물 생성을 위한 빠른 방법을 제공합니다 Nuestra herramienta de blog te ayuda a crear publicaciones con títulos y descripciones SEO-friendly para tu blog basado en Hugo. Aprovecha tecnologías como ikiwiki para mejorar tu experiencia de blogueo Notre outil de blog vous aide à créer des publications avec des titres et des descriptions SEO-friendly pour votre blog basé sur Hugo. Profitez des technologies comme ikiwiki pour améliorer votre expérience de blogue Unser Blog-Tool hilft Ihnen, Beiträge mit SEO-freundlichen Titeln und Beschreibungen für Ihren Hugo-basierten Blog zu erstellen. Nutzen Sie Technologien wie ikiwiki, um Ihre Blog-Erfahrung zu verbessern Criar um blog com Hugo e IKIWiki é fácil com nossa guia. Aprenda a criar títulos amigáveis e descrições para SEO ИИ Агенты помогают создать блог с Hugo и IKIWiki. Узнайте, как создать привлекательные заголовки и описания для поисковых систем إنشاء مدونة مع Hugo و IKIWiki أصبح أكثر سهولة مع أدوات الذكاء الاصطناعي. تعرف على كيفية إنشاء عناوين ووصف للمدونة how to use blog what is blog blog alternative hugo blog setup guide blog post creation ikiwiki tutorial seo friendly title generation dynamic blog post creation Hugo博客 AIエージェント博客工具 SEO友好的博客 技术博客 动态年份获取 标题生成 ikiwiki集成 Determines the current year using the date +%Y command Asks users for blog post topic and title, offering generation based on topic Generates SEO-friendly titles and descriptions for blog posts Integrates with Hugo for seamless blog post creation Supports ikiwiki for flexible wiki-based content management Blog is a skill that assists in creating new blog posts for Hugo-based blogs, utilizing commands like date +%Y for dynamic year determination.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('forcedotcom/apex-language-support/packageJson', 'community', 'forcedotcom', 'apex-language-support', 'forcedotcom/apex-language-support', 'packageJson', 7, 2, 23, '2026-03-03T21:15:35Z', '2026-03-06T06:51:23.877Z', 'd93ceb60a999573a178efdaa05905dddd885a6c5b7d2dae94e7e25cbd3de8eb6', '{"id":"forcedotcom/apex-language-support/packageJson","name":"packageJson","description":{"en":"The packageJson skill provides guidance on configuring package.json files for extensions, including naming conventions and type definitions. It benefits developers working with npm packages and extensions.","zh":"packageJson 是一种实验性的 AI 工具配置方法，需要遵循特定的命名规则和类型定义","ja":"packageJson は実験的な AI エージェント設定方法であり、特定の命名規則と型定義を必要とする","ko":"packageJson은 실험적인 AI 에이전트 설정 방법으로 특정한 명명 규칙과 유형 정의를 필요로 함","es":"El packageJson es un archivo de configuración para agentes de IA que permite definir tipos y dependencias de extensiones","fr":"Le packageJson est un fichier de configuration pour les outils d''IA qui permet de définir les types et les dépendances des extensions","de":"Das packageJson ist eine Konfigurationsdatei für KI-Agents, die die Definition von Typen und Abhängigkeiten von Erweiterungen ermöglicht","pt":"O packageJson é um arquivo de configuração crucial para desenvolvedores de extensões e pacotes npm.","ru":"Файл packageJson является важным файлом конфигурации для разработчиков расширений и npm-пакетов.","ar":"ملف packageJson هو ملف تعريف أساسي للمطورين لإضافات وحزم npm."},"seo":{"title":{"en":"packageJson: Configuration Setup Guide | AI Agent Skill","zh":"packageJson 设置指南 - AI工具配置最佳实践","ja":"packageJson の設定方法 - AIエージェント開発のベストプラクティス","ko":"packageJson 설정 가이드 - AI 에이전트 개발 모범 사례","es":"Guía de configuración de packageJson para agentes de IA","fr":"Guide de configuration de packageJson pour les outils d''IA","de":"Konfigurationsleitfaden für packageJson in KI-Agenten","pt":"Configuração de packageJson: Melhores Práticas para Desen...","ru":"ИИ Агенты: Настройка packageJson для Расширений","ar":"إعداد packageJson: دليل تطوير البرامج"},"description":{"en":"Discover how to properly configure your package.json file for seamless extension development, including type definitions and browser support","zh":"了解 packageJson 的技术细节和设置方法，优化您的 AI 工具配置","ja":"packageJson の設定方法と技術的詳細を学び、AIエージェント開発を最適化する","ko":"packageJson 설정 방법과 기술적 세부 사항을 알아보고 AI 에이전트 개발을 최적화하십시오","es":"Descubre cómo configurar packageJson para agentes de IA y aprovecha sus capacidades para desarrollar extensiones","fr":"Découvrez comment configurer packageJson pour les outils d''IA et exploitez leurs capacités pour développer des extensions","de":"Erfahren Sie, wie Sie packageJson für KI-Agents konfigurieren und ihre Fähigkeiten für die Entwicklung von Erweiterungen nutzen","pt":"Aprenda a configurar corretamente o packageJson para desenvolver extensões e pacotes npm","ru":"Узнайте, как настроить packageJson для разработки расширений и npm-пакетов","ar":"تعرف على كيفية إعداد packageJson بشكل صحيح لتطوير الإضافات وحزم npm"},"definition":{"en":"packageJson is a configuration file format used to manage dependencies and scripts for JavaScript projects, particularly those using npm packages","zh":"packageJson 是一种 AI 工具配置文件，定义了包的命名、类型和浏览器兼容性","ja":"packageJson は AI エージェント設定ファイルであり、パッケージの命名、型とブラウザーの互換性を定義する","ko":"packageJson은 AI 에이전트 설정 파일로 패키지의 명명, 유형 및 브라우저 호환성을 정의","es":"El packageJson es un archivo de configuración que define metadatos para agentes de IA y extensiones","fr":"Le packageJson est un fichier de configuration qui définit des métadonnées pour les outils d''IA et les extensions","de":"Das packageJson ist eine Konfigurationsdatei, die Metadaten für KI-Agents und Erweiterungen definiert","pt":"O packageJson é um arquivo que contém metadados para pacotes npm e extensões","ru":"ИИ Агенты: packageJson - файл, содержащий метаданные для npm-пакетов и расширений","ar":"packageJson هو ملف يحتوي على بيانات وصفية لـ npm وملحقات"},"features":{"en":["Enforces naming conventions for non-npm packages using the @salesforce/foo format","Supports type definitions for extensions using the `types` prop","Requires a bundled dist file for web-enabled extensions","Provides guidance on extension dependencies and npm package management","Alerts users to naming discrepancies and configuration issues"],"zh":["支持 @salesforce/foo 命名规则","需要 types 属性来定义扩展依赖","支持浏览器兼容性的配置","需要指向打包后的 dist 文件"],"ja":["@salesforce/foo 命名規則をサポート","types 属性を使用して拡張依存関係を定義","ブラウザーの互換性をサポート","バンドルされた dist ファイルを指す必要がある"],"ko":["@salesforce/foo 명명 규칙 지원","types 속성을 사용하여 확장 의존성을 정의","브라우저 호환성 지원","번들된 dist 파일을 가리킬 필요가 있음"],"es":["Definición de tipos para extensiones","Gestión de dependencias de extensiones","Compatibilidad con npm packages","Soporte para extensiones web","Configuración de archivos de distribución"],"fr":["Définition de types pour les extensions","Gestion des dépendances d''extensions","Compatibilité avec les packages npm","Prise en charge des extensions web","Configuration des fichiers de distribution"],"de":["Definition von Typen für Erweiterungen","Verwaltung von Abhängigkeiten von Erweiterungen","Kompatibilität mit npm-Paketen","Unterstützung für Web-Erweiterungen","Konfiguration von Verteilungsdateien"],"pt":["Suporte a tipos para extensões","Configuração de browser para extensões web","Compatibilidade com pacotes npm","Convenções de nomenclatura para pacotes não npm","Verificação de consistência de nomes de pacotes"],"ru":["Поддержка типов для расширений","Настройка браузера для веб-расширений","Совместимость с npm-пакетами","Конвенции именования для пакетов, не являющихся npm","Проверка согласованности имен пакетов"],"ar":["دعم أنواع للامتدادات","إعداد المتصفح للامتدادات على الويب","التطابق مع حزم npm","اتفاقيات تسمية الحزم غير npm","تحقق من الاتساق في أسماء الحزم"]},"keywords":{"en":["how to use packageJson","packageJson configuration guide","npm package management","extension development best practices","packageJson setup tutorial","packageJson vs npm","packageJson install instructions","what is packageJson","packageJson alternative solutions"],"zh":["packageJson 设置","AI 工具配置","AIエージェント开发","npm 包管理","浏览器兼容性","扩展依赖","dist 文件配置"],"ja":["packageJson の設定","AI エージェント開発","AIエージェント設定","npm パッケージ管理","ブラウザーの互換性","拡張依存関係","dist ファイルの設定"],"ko":["packageJson 설정","AI 에이전트 개발","AI 에이전트 설정","npm 패키지 관리","브라우저 호환성","확장 의존성","dist 파일 설정"],"es":["agentes de IA","packageJson","configuración de extensiones","desarrollo de extensiones","npm packages","extensiones web","configuración de archivos de distribución"],"fr":["outils d''IA","packageJson","configuration d''extensions","développement d''extensions","packages npm","extensions web","configuration de fichiers de distribution"],"de":["KI-Agents","packageJson","Konfiguration von Erweiterungen","Entwicklung von Erweiterungen","npm-Pakete","Web-Erweiterungen","Konfiguration von Verteilungsdateien"],"pt":["packageJson","desenvolvimento de extensões","pacotes npm","configuração de browser","tipos para extensões","convenções de nomenclatura","verificação de consistência"],"ru":["ИИ Агенты","packageJson","разработка расширений","npm-пакеты","настройка браузера","типы для расширений","конвенции именования","проверка согласованности"],"ar":["إعداد packageJson","تطوير الإضافات","حزم npm","إعداد المتصفح","أنواع للامتدادات","اتفاقيات تسمية","تحقق من الاتساق","أدوات ذكاء اصطناعي"]}},"owner":"forcedotcom","repo":"apex-language-support","repoPath":"forcedotcom/apex-language-support","stars":7,"forks":2,"updatedAt":"2026-03-03T21:15:35Z","topics":[],"category":"community","skillMd":{"name":"packageJson","description":"Guidelines for package.json files in packages","bodyPreview":"## Name\n\nany package that''s not an npm package should be named @salesforce/foo (whether it actually published to npm or not)\ndon''t rename packages, but do tell the user when stuff doesn''t match the rules\n\n## types\n\non an extension, you only need a `types` prop if your extension will be an extensionDependency of some other extension.\n\nprobably not necessary for non-extension packages.\n\n## browser\n\nonly for web-enabled extensions. Must point to a bundled dist file\n\n## npm packages\n\npackages that p","body":"## Name\n\nany package that''s not an npm package should be named @salesforce/foo (whether it actually published to npm or not)\ndon''t rename packages, but do tell the user when stuff doesn''t match the rules\n\n## types\n\non an extension, you only need a `types` prop if your extension will be an extensionDependency of some other extension.\n\nprobably not necessary for non-extension packages.\n\n## browser\n\nonly for web-enabled extensions. Must point to a bundled dist file\n\n## npm packages\n\npackages that publish to npm should have a `files` property in the package.json\n\n## scripts\n\nSee [wireit skill](../wireit/SKILL.md)\n\n## dependencies\n\nuse `*` as the version for anything that''s another package in this repo\n\n## devDependencies\n\npackages should not duplicate devDependencies that exist at the top level of the repo.\n\n## vscode \"contributes\"\n\n### Tips\n\n- anything in `commands` will appear in command palette. If you don''t want that, you have to `never` or use some `when` under commandPalette\n- commands need a unique ID, 2 extensions contributing the same config will produce a UI warning\n- never create a \"default:true\" boolean configuration (it''s hard to override user/workspace)\n"},"lastSynced":"2026-03-06T06:51:23.877Z","agentAnalysis":{"suitability":{"en":"Perfect for JavaScript Agents needing advanced package.json configuration and npm package management.","zh":"适合需要高级package.json配置和npm包管理的JavaScript代理。","ja":"JavaScriptエージェントが高度なpackage.json設定とnpmパッケージ管理を必要とする場合に適しています。","ko":"고급 package.json 구성 및 npm 패키지 관리가 필요한 JavaScript 에이전트에 적합합니다.","es":"Perfecto para agentes de JavaScript que necesitan una configuración avanzada de package.json y gestión de paquetes npm.","fr":"Parfait pour les agents JavaScript ayant besoin d''une configuration avancée de package.json et de gestion de paquet npm.","de":"Perfekt für JavaScript-Agents, die eine erweiterte package.json-Konfiguration und npm-Paketverwaltung benötigen.","pt":"Perfeito para Agentes JavaScript que necessitam de configuração avançada do package.json e gerenciamento de pacotes npm.","ru":"Идеально для агентов JavaScript, требующих расширенной настройки package.json и управления пакетами npm.","ar":"مثالي للوكلاء JavaScript الذين يحتاجون إلى تكوين متقدم لملف package.json وإدارة حزم npm."},"recommendation":{"en":"Empowers agents to configure package.json files with standardized naming conventions, type definitions, and browser-specific settings, leveraging npm packages and extension dependencies.","zh":"赋予代理配置package.json文件的能力，使用标准化的命名约定、类型定义和浏览器特定设置，利用npm包和扩展依赖。","ja":"エージェントが標準化された命名規則、型定義、およびブラウザ固有の設定を使用してpackage.jsonファイルを構成する機能を提供し、npmパッケージおよび拡張依存関係を利用します。","ko":"에이전트가 표준화된 명명 규칙, 유형 정의 및 브라우저별 설정을 사용하여 package.json 파일을 구성할 수 있도록 하며, npm 패키지 및 확장 종속성을 활용합니다.","es":"Habilita a los agentes a configurar archivos package.json con convenciones de nomenclatura estandarizadas, definiciones de tipo y configuraciones específicas del navegador, aprovechando paquetes npm y dependencias de extensiones.","fr":"Permet aux agents de configurer des fichiers package.json avec des conventions de nommage standardisées, des définitions de type et des paramètres spécifiques au navigateur, en exploitant les paquets npm et les dépendances d''extension.","de":"Ermächtigt Agents, package.json-Dateien mit standardisierten Namenskonventionen, Typdefinitionen und browser-spezifischen Einstellungen zu konfigurieren, indem npm-Pakete und Erweiterungs-Abhängigkeiten genutzt werden.","pt":"Habilita os agentes a configurar arquivos package.json com convenções de nomenclatura padronizadas, definições de tipo e configurações específicas do navegador, aproveitando pacotes npm e dependências de extensão.","ru":"Наделяет агентов возможностью настраивать файлы package.json с标准ными соглашениями об именах, определениями типов и настройками, специфичными для браузера, используя пакеты npm и зависимости расширений.","ar":"تمكين الوكلاء من تكوين ملفات package.json باستخدام اتفاقيات命名 معيارية وdefinitions من النوع والإعدادات المحددة للمتصفح، مستفيدة من حزم npm واعتماديات الامتداد."},"useCases":{"en":["Configuring package.json files for extensions","Validating naming conventions for npm packages","Defining type definitions for extension dependencies"],"zh":["为扩展配置package.json文件","验证npm包的命名约定","为扩展依赖定义类型定义"],"ja":["拡張機能のpackage.jsonファイルを構成する","npmパッケージの命名規則を検証する","拡張依存関係の型定義を定義する"],"ko":["확장 기능을 위한 package.json 파일 구성","npm 패키지의 명명 규칙 검증","확장 종속성의 유형 정의"],"es":["Configuración de archivos package.json para extensiones","Validación de convenciones de nomenclatura para paquetes npm","Definición de definiciones de tipo para dependencias de extensiones"],"fr":["Configuration de fichiers package.json pour les extensions","Validation des conventions de nommage pour les paquets npm","Définition des définitions de type pour les dépendances d''extension"],"de":["Konfiguration von package.json-Dateien für Erweiterungen","Validierung von Namenskonventionen für npm-Pakete","Definition von Typdefinitionen für Erweiterungs-Abhängigkeiten"],"pt":["Configurando arquivos package.json para extensões","Validando convenções de nomenclatura para pacotes npm","Definindo definições de tipo para dependências de extensão"],"ru":["Настройка файлов package.json для расширений","Проверка соглашений об именах для пакетов npm","Определение определений типов для зависимостей расширений"],"ar":["تكوين ملفات package.json للامتدادات","التحقق من اتفاقيات命امگ ل حزم npm","تحديد تعريفات النوع لاعتماديات الامتداد"]},"limitations":{"en":["Requires npm package knowledge","Limited to JavaScript-based projects","Only necessary for projects with extension dependencies"],"zh":["需要npm包知识","仅限于基于JavaScript的项目","仅对于具有扩展依赖的项目才有必要"],"ja":["npmパッケージの知識が必要","JavaScriptベースのプロジェクトのみ","拡張依存関係があるプロジェクトでのみ必要"],"ko":["npm 패키지 지식이 필요","JavaScript 기반 프로젝트만 해당","확장 종속성이 있는 프로젝트에서만 필요"],"es":["Requiere conocimiento de paquetes npm","Limitado a proyectos basados en JavaScript","Solo necesario para proyectos con dependencias de extensiones"],"fr":["Nécessite des connaissances en paquets npm","Limité aux projets basés sur JavaScript","Nécessaire uniquement pour les projets avec des dépendances d''extension"],"de":["Benötigt npm-Paket-Kenntnisse","Begrenzt auf JavaScript-basierte Projekte","Nur notwendig für Projekte mit Erweiterungs-Abhängigkeiten"],"pt":["Exige conhecimento de pacotes npm","Limitado a projetos baseados em JavaScript","Apenas necessário para projetos com dependências de extensão"],"ru":["Требует знания пакетов npm","Ограничен проектами на основе JavaScript","Необходим только для проектов с зависимостями расширений"],"ar":["يتطلب معرفة حزم npm","محدود لمشاريع مبنية على JavaScript","مطلوب فقط لمشاريع ذات اعتماديات امتداد"]},"version":4},"contentHash":"d93ceb60a999573a178efdaa05905dddd885a6c5b7d2dae94e7e25cbd3de8eb6","qualityScore":23}');
