INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('forcedotcom/apex-language-support/packageJson', 'packageJson', 'forcedotcom', 'apex-language-support', 'community', 'packageJson forcedotcom apex-language-support community The packageJson skill provides guidance on configuring package.json files for extensions, including naming conventions and type definitions. It benefits developers working with npm packages and extensions. packageJson 是一种实验性的 AI 工具配置方法，需要遵循特定的命名规则和类型定义 packageJson は実験的な AI エージェント設定方法であり、特定の命名規則と型定義を必要とする packageJson은 실험적인 AI 에이전트 설정 방법으로 특정한 명명 규칙과 유형 정의를 필요로 함 El packageJson es un archivo de configuración para agentes de IA que permite definir tipos y dependencias de extensiones Le packageJson est un fichier de configuration pour les outils d''IA qui permet de définir les types et les dépendances des extensions Das packageJson ist eine Konfigurationsdatei für KI-Agents, die die Definition von Typen und Abhängigkeiten von Erweiterungen ermöglicht O packageJson é um arquivo de configuração crucial para desenvolvedores de extensões e pacotes npm. Файл packageJson является важным файлом конфигурации для разработчиков расширений и npm-пакетов. ملف packageJson هو ملف تعريف أساسي للمطورين لإضافات وحزم npm. how to use packageJson packageJson configuration guide npm package management extension development best practices packageJson setup tutorial packageJson vs npm packageJson install instructions what is packageJson packageJson alternative solutions packageJson 设置 AI 工具配置 AIエージェント开发 npm 包管理 浏览器兼容性 扩展依赖 dist 文件配置 Enforces naming conventions for non-npm packages using the @salesforce/foo format Supports type definitions for extensions using the `types` prop Requires a bundled dist file for web-enabled extensions Provides guidance on extension dependencies and npm package management Alerts users to naming discrepancies and configuration issues packageJson is a configuration file format used to manage dependencies and scripts for JavaScript projects, particularly those using npm packages');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('u9401066/med-paper-assistant/memory-updater', 'community', 'u9401066', 'med-paper-assistant', 'u9401066/med-paper-assistant', 'memory-updater', 4, 0, 23, '2026-02-24T00:13:47Z', '2026-03-06T06:57:19.001Z', '7bd1d14ccc1a60095ed589b99c104b679658878e3ba094794516234339dfb7ed', '{"id":"u9401066/med-paper-assistant/memory-updater","name":"memory-updater","description":{"en":"The memory-updater skill is an AI-powered medical paper writing toolkit that streamlines the writing process from PubMed search to Word export within VS Code, benefiting clinical researchers and academic writers.","zh":"memory-updater是AI-powered的医学论文写作工具，支持PubMed搜索、Word导出等功能","ja":"memory-updaterはAIエージェントによる医学論文作成ツールで、PubMed検索、Wordエクスポートなどをサポート","ko":"memory-updater는 AI 에이전트를 활용한 의학 논문 작성 도구로, PubMed 검색, Word导出 등을 지원합니다","es":"memory-updater es una herramienta de investigación médica que actualiza la memoria y proporciona herramientas de escritura para mejorar la productividad","fr":"memory-updater est un outil de recherche médicale qui met à jour la mémoire et fournit des outils d''écriture pour améliorer la productivité","de":"memory-updater ist ein medizinisches Forschungstool, das die Speicheraktualisierungen durchführt und Schreibtools zur Verfügung stellt, um die Produktivität zu verbessern","pt":"O memory-updater é uma ferramenta de escrita médica AI que facilita a pesquisa e a escrita de artigos médicos, integrando PubMed e VS Code.","ru":"Memory-updater - это инструмент для написания медицинских статей с ИИ, который упрощает поиск и написание медицинских статей, интегрируя PubMed и VS Code.","ar":"memory-updater هو أداة الكتابة الطبية بالذكاء الاصطناعي التي تسهل البحث والكتابة في المقالات الطبية، و تدمج PubMed و VS Code."},"seo":{"title":{"en":"memory-updater: AI-Powered Medical Writing Toolkit Setup ...","zh":"memory-updater_SETUP指南：AI医学论文写作工具","ja":"memory-updater セットアップガイド: AIエージェントによる医学論文作成ツール","ko":"memory-updater 설정 가이드: AI 에이전트를 활용한 의학 논문 작성 도구","es":"Guía de configuración de memory-updater para herramientas...","fr":"Guide de mise en place de memory-updater pour les outils ...","de":"Einrichtungsleitfaden für memory-updater in medizinischen...","pt":"Guia de Configuração do memory-updater: Ferramenta de Esc...","ru":"Настройка memory-updater: Инструмент для написания медици...","ar":"دليل إعداد memory-updater: أداة الكتابة الطبية بالذكاء ال..."},"description":{"en":"Unlock efficient medical paper writing with memory-updater. Discover how to integrate PubMed search and Word export in VS Code, and get started today!","zh":"了解memory-updater的功能和特点，掌握AI医学论文写作工具的使用方法","ja":"memory-updaterの機能と特徴を学び、AIエージェントによる医学論文作成ツールの使用方法をマスターする","ko":"memory-updater의 기능과 특징을 알아보고, AI 에이전트를 활용한 의학 논문 작성 도구의 사용 방법을 익히세요","es":"Descubre cómo memory-updater mejora la investigación médica con actualizaciones de memoria automatizadas y herramientas de escritura","fr":"Découvrez comment memory-updater améliore la recherche médicale avec des mises à jour de mémoire automatisées et des outils d''écriture","de":"Erfahren Sie, wie memory-updater die medizinische Forschung mit automatisierten Speicheraktualisierungen und Schreibtools verbessert","pt":"Aprenda a configurar o memory-updater, uma ferramenta de escrita médica AI que integra PubMed e VS Code para melhorar sua produtividade","ru":"Узнайте, как настроить memory-updater, инструмент для написания медицинских статей с ИИ, интегрирующий PubMed и VS Code","ar":"تعرف على كيفية إعداد memory-updater، أداة الكتابة الطبية بالذكاء الاصطناعي التي تدمج PubMed و VS Code لتحسين إنتاجيتك"},"definition":{"en":"memory-updater is a VS Code extension that utilizes AI to facilitate medical paper writing, including literature review, citation management, and evidence-based medicine support.","zh":"memory-updater是一种AI工具，用于更新记忆并记录进度","ja":"memory-updaterは、記憶を更新し進度を記録するAIエージェント","ko":"memory-updater는 기억을 업데이트하고 진행 상황을 기록하는 AI 에이전트","es":"memory-updater es una herramienta de investigación médica que actualiza la memoria para mejorar la productividad","fr":"memory-updater est un outil de recherche médicale qui met à jour la mémoire pour améliorer la productivité","de":"memory-updater ist ein medizinisches Forschungstool, das die Speicheraktualisierungen durchführt, um die Produktivität zu verbessern","pt":"O memory-updater é uma ferramenta de escrita médica AI que atualiza a memória e registra o progresso","ru":"Memory-updater - это инструмент для написания медицинских статей с ИИ, который обновляет память и регистрирует прогресс","ar":"memory-updater هو أداة الكتابة الطبية بالذكاء الاصطناعي التي تحديث الذاكرة وتسجل التقدم"},"features":{"en":["Triggers updates to memory, records progress, and syncs data upon work session completion","Utilizes MCP Tools, including `memory_bank_update_progress` and `memory_bank_update_context` commands","Supports logging decisions in decisionLog.md and displaying memory content","Integrates with PubMed for efficient literature searches","Exports written content to Word format"],"zh":["支持PubMed搜索和Word导出","自动更新记忆和记录进度","提供进度跟踪和决策记录功能","集成memory_bank_update_progress和memory_bank_update_context工具","支持多种文件格式，包括progress.md和decisionLog.md"],"ja":["PubMed検索とWordエクスポートをサポート","記憶を自動更新し進度を記録","進度追跡と決策記録機能を提供","memory_bank_update_progressとmemory_bank_update_contextツールを統合","複数のファイル形式をサポート、progress.mdとdecisionLog.mdなど"],"ko":["PubMed 검색과 Word导出을 지원","기억을 자동 업데이트하고 진행 상황을 기록","진행 상황 추적과 의사 결정 기록 기능을 제공","memory_bank_update_progress와 memory_bank_update_context 도구를 통합","여러 파일 형식을 지원, progress.md와 decisionLog.md 등"],"es":["Actualizaciones de memoria automatizadas","Herramientas de escritura para investigación médica","Integración con PubMed y exportación a Word","Compatibilidad con VS Code","Soporte para MCP (Model-Context-Protocol)","Funcionalidades de registro y seguimiento de progreso"],"fr":["Mises à jour de mémoire automatisées","Outils d''écriture pour la recherche médicale","Intégration avec PubMed et exportation vers Word","Compatibilité avec VS Code","Prise en charge de MCP (Model-Context-Protocol)","Fonctionnalités de journalisation et de suivi de progression"],"de":["Automatisierte Speicheraktualisierungen","Schreibtools für medizinische Forschung","Integration mit PubMed und Export in Word","Kompatibilität mit VS Code","Unterstützung für MCP (Model-Context-Protocol)","Funktionen zur Protokollierung und Fortschrittsverfolgung"],"pt":["Integração com PubMed para pesquisa de artigos médicos","Atualização da memória e registro do progresso","Suporte a VS Code para edição de artigos","Ferramentas de gestão de contexto e decisão","Suporte a Python para desenvolvimento personalizado"],"ru":["Интеграция с PubMed для поиска медицинских статей","Обновление памяти и регистрация прогресса","Поддержка VS Code для редактирования статей","Инструменты управления контекстом и решением","Поддержка Python для индивидуального развития"],"ar":["التكامل مع PubMed للبحث في المقالات الطبية","تحديث الذاكرة وتسجيل التقدم","دعم VS Code لتحرير المقالات","أدوات إدارة السياق والقرار","دعم Python للتطوير المخصص"]},"keywords":{"en":["how to use memory-updater","memory-updater alternative","memory-updater setup guide","what is memory-updater","memory-updater vs copilot","memory-updater install","AI-powered medical writing tools","VS Code extensions for academic writing","PubMed search integration"],"zh":["AI医学论文写作工具","memory-updater","PubMed搜索","Word导出","AI工具","记忆更新","进度记录","决策记录","memory_bank_update_progress","memory_bank_update_context"],"ja":["AIエージェント","memory-updater","PubMed検索","Wordエクスポート","AIツール","記憶更新","進度記録","決策記録","memory_bank_update_progress","memory_bank_update_context"],"ko":["AI 에이전트","memory-updater","PubMed 검색","Word导出","AI 도구","기억 업데이트","진행 상황 기록","의사 결정 기록","memory_bank_update_progress","memory_bank_update_context"],"es":["herramientas de investigación médica","actualizaciones de memoria","escritura médica","PubMed","VS Code","MCP","model-context-protocol","investigación clínica","literatura médica","herramientas de escritura médica"],"fr":["outils de recherche médicale","mises à jour de mémoire","écriture médicale","PubMed","VS Code","MCP","model-context-protocol","recherche clinique","littérature médicale","outils d''écriture médicale"],"de":["medizinische Forschungstools","Speicheraktualisierungen","medizinisches Schreiben","PubMed","VS Code","MCP","model-context-protocol","klinische Forschung","medizinische Literatur","medizinische Schreibtools"],"pt":["memory-updater","ferramenta de escrita médica AI","PubMed","VS Code","Python","desenvolvimento de artigos médicos","gestão de contexto","decisão médica"],"ru":["memory-updater","инструмент для написания медицинских статей с ИИ","PubMed","VS Code","Python","развитие медицинских статей","управление контекстом","медицинское решение"],"ar":["memory-updater","أداة الكتابة الطبية بالذكاء الاصطناعي","PubMed","VS Code","Python","تطوير المقالات الطبية","إدارة السياق","القرار الطبي"]}},"owner":"u9401066","repo":"med-paper-assistant","repoPath":"u9401066/med-paper-assistant","stars":4,"forks":0,"updatedAt":"2026-02-24T00:13:47Z","topics":["academic-writing","ai-assistant","ai-tools","citation-manager","clinical-research","copilot","evidence-based-medicine","literature-review","mcp","medical-writing","model-context-protocol","pubmed","python","scientific-writing","vscode-extension"],"category":"community","skillMd":{"name":"memory-updater","description":"更新 Memory Bank 檔案。觸發：memory、記憶、進度、存檔、sync、做到哪。","bodyPreview":"# Memory Bank 更新技能\n\n觸發：更新 memory、記錄進度、存檔、sync、工作階段結束時自動觸發\n\n---\n\n## MCP Tools\n\n| 工具                          | 用途                                |\n| ----------------------------- | ----------------------------------- |\n| `memory_bank_update_progress` | progress.md (done/doing/next)       |\n| `memory_bank_update_context`  | activeContext.md                    |\n| `memory_bank_log_decision`    | decisionLog.md（重大決策）          |\n| `memory_bank_show_memory`     | 顯示記憶內容                        |\n| `mem","body":"# Memory Bank 更新技能\n\n觸發：更新 memory、記錄進度、存檔、sync、工作階段結束時自動觸發\n\n---\n\n## MCP Tools\n\n| 工具                          | 用途                                |\n| ----------------------------- | ----------------------------------- |\n| `memory_bank_update_progress` | progress.md (done/doing/next)       |\n| `memory_bank_update_context`  | activeContext.md                    |\n| `memory_bank_log_decision`    | decisionLog.md（重大決策）          |\n| `memory_bank_show_memory`     | 顯示記憶內容                        |\n| `memory_bank_switch_mode`     | 切換模式 (architect/code/ask/debug) |\n\n## 檔案與時機\n\n| 檔案              | 更新時機        |\n| ----------------- | --------------- |\n| activeContext.md  | 每次切換任務    |\n| progress.md       | 完成任務時      |\n| decisionLog.md    | 架構/技術決策時 |\n| productContext.md | 專案設定變更時  |\n| systemPatterns.md | 發現新模式時    |\n\n## 原則\n\n增量更新、保持簡潔、重要項目加日期、標記相關檔案和決策\n"},"lastSynced":"2026-03-06T06:57:19.001Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents requiring streamlined medical paper writing and PubMed search integration within VS Code.","zh":"适用于需要在 VS Code 中简化医疗论文写作和 PubMed 搜索集成的研究代理。","ja":"VS Code 内で医療論文の執筆と PubMed 検索の統合をストリームライン化する必要がある研究エージェントに最適。","ko":"VS Code 내에서 의학 논문 작성 및 PubMed 검색 통합을 간소화해야 하는 연구 에이전트에 적합합니다.","es":"Ideal para agentes de investigación que requieren una escritura de artículos médicos optimizada y la integración de búsqueda en PubMed dentro de VS Code.","fr":"Idéal pour les agents de recherche nécessitant une rédaction d''articles médicaux simplifiée et l''intégration de la recherche PubMed au sein de VS Code.","de":"Ideal für Forschungsagenten, die eine optimierte medizinische Artikelveröffentlichung und eine PubMed-Suche-Integration innerhalb von VS Code benötigen.","pt":"Ideal para Agentes de Pesquisa que requerem escrita de artigos médicos e integração de busca no PubMed dentro do VS Code.","ru":"Идеально подходит для агентов-исследователей, требующих упрощенной медицинской научной статьи и интеграции поиска PubMed внутри VS Code.","ar":"مثالي لعميل البحث الذي يتطلب كتابة ورقة طبية متدفقة وتكامل بحث PubMed داخل VS Code."},"recommendation":{"en":"Empowers agents to automate progress tracking, decision logging, and memory updates using tools like `memory_bank_update_progress` and `memory_bank_log_decision`, seamlessly integrating with Word export and sync capabilities.","zh":"赋予代理人使用诸如 `memory_bank_update_progress` 和 `memory_bank_log_decision` 之类的工具自动跟踪进度、记录决策和更新内存，并与 Word 导出和同步功能无缝集成。","ja":"エージェントに `memory_bank_update_progress` や `memory_bank_log_decision` などのツールを使用して進度の追跡、意思決定の記録、メモリの更新を自動化し、Word のエクスポートや同期機能とシームレスに統合することを可能にします。","ko":"에이전트가 `memory_bank_update_progress` 및 `memory_bank_log_decision`와 같은 도구를 사용하여 진행 상황을 자동으로 추적하고 결정 사항을 기록하고 메모리를 업데이트하며 Word 내보내기 및 동기화 기능과 원활하게 통합할 수 있도록 합니다.","es":"Permite a los agentes automatizar el seguimiento del progreso, la registración de decisiones y las actualizaciones de memoria utilizando herramientas como `memory_bank_update_progress` y `memory_bank_log_decision`, integrándose de forma transparente con las capacidades de exportación y sincronización de Word.","fr":"Permet aux agents d''automatiser le suivi des progrès, l''enregistrement des décisions et les mises à jour de mémoire en utilisant des outils tels que `memory_bank_update_progress` et `memory_bank_log_decision`, s''intégrant sans heurt avec les capacités d''exportation et de synchronisation de Word.","de":"Ermöglicht es den Agenten, den Fortschrittsverlauf, die Entscheidungsprotokollierung und die Speicheraktualisierungen mithilfe von Tools wie `memory_bank_update_progress` und `memory_bank_log_decision` zu automatisieren, und integriert sich nahtlos mit den Word-Export- und Synchronisierungsfunktionen.","pt":"Permite que os agentes automatizem o rastreamento de progresso, registro de decisões e atualizações de memória usando ferramentas como `memory_bank_update_progress` e `memory_bank_log_decision`, integrando-se perfeitamente com as capacidades de exportação e sincronização do Word.","ru":"Позволяет агентам автоматизировать отслеживание прогресса, ведение журнала решений и обновления памяти с помощью инструментов như `memory_bank_update_progress` и `memory_bank_log_decision`, обеспечивая бесшовную интеграцию с возможностями экспорта и синхронизации Word.","ar":"يمكن للعميل تمكين الوكلاء من توفير تلقائي لتتبع التقدم وتسجيل القرارات وتحديث الذاكرة باستخدام أدوات مثل `memory_bank_update_progress` و `memory_bank_log_decision` ، وتكاملها بلا مشاكل مع إمكانيات تصدير وتنظيم كلمة."},"useCases":{"en":["Automating medical paper writing workflows from PubMed search to Word export","Updating memory banks and tracking progress with `memory_bank_update_progress`","Logging significant decisions using `memory_bank_log_decision` for transparency and accountability"],"zh":["自动执行从 PubMed 搜索到 Word 导出的医疗论文写作工作流程","使用 `memory_bank_update_progress` 更新内存库并跟踪进度","使用 `memory_bank_log_decision` 记录重要决策以实现透明度和责任感"],"ja":["PubMed 検索から Word エクスポートまでの医療論文の執筆ワークフローを自動化する","`memory_bank_update_progress` を使用してメモリーバンクを更新し、進度を追跡する","`memory_bank_log_decision` を使用して重要な意思決定を記録し、透明性と説明責任を確保する"],"ko":["PubMed 검색에서 Word 내보내기까지 의학 논문 작성 워크플로우를 자동화하는 것","`memory_bank_update_progress`를 사용하여 메모리 뱅크를 업데이트하고 진행 상황을 추적하는 것","`memory_bank_log_decision`를 사용하여 중요한 결정 사항을 기록하여 투명성과 책임성을確保하는 것"],"es":["Automatizar flujos de trabajo de escritura de artículos médicos desde la búsqueda en PubMed hasta la exportación a Word","Actualizar bancos de memoria y realizar un seguimiento del progreso con `memory_bank_update_progress`","Registrar decisiones importantes utilizando `memory_bank_log_decision` para la transparencia y la responsabilidad"],"fr":["Automatiser les flux de travail de rédaction d''articles médicaux depuis la recherche PubMed jusqu''à l''exportation vers Word","Mettre à jour les banques de mémoire et suivre les progrès avec `memory_bank_update_progress`","Enregistrer les décisions importantes en utilisant `memory_bank_log_decision` pour la transparence et la responsabilité"],"de":["Automatisierung von Arbeitsabläufen für die Veröffentlichung medizinischer Artikel von der PubMed-Suche bis zur Word-Export","Aktualisierung von Speicherbänken und Verfolgung des Fortschritts mit `memory_bank_update_progress`","Protokollierung wichtiger Entscheidungen unter Verwendung von `memory_bank_log_decision` für Transparenz und Rechenschaftspflicht"],"pt":["Automatizar fluxos de trabalho de escrita de artigos médicos da busca no PubMed à exportação do Word","Atualizar bancos de memória e rastrear progresso com `memory_bank_update_progress`","Registrar decisões significativas usando `memory_bank_log_decision` para transparência e responsabilidade"],"ru":["Автоматизировать рабочие процессы написания медицинских статей от поиска в PubMed до экспорта в Word","Обновлять банки памяти и отслеживать прогресс с помощью `memory_bank_update_progress`","Вести журнал значимых решений с помощью `memory_bank_log_decision` для прозрачности и подотчетности"],"ar":["توفير تلقائي لتدفقات عمل كتابة الأوراق الطبية من بحث PubMed إلى تصدير كلمة","تحديث بنوك الذاكرة وتتبع التقدم باستخدام `memory_bank_update_progress`","تسجيل القرارات المهمة باستخدام `memory_bank_log_decision` من أجل الشفافية والمساءلة"]},"limitations":{"en":["Requires VS Code integration","Limited to medical paper writing and research contexts","Dependent on PubMed search functionality"],"zh":["需要 VS Code 集成","仅限医疗论文写作和研究背景","依赖于 PubMed 搜索功能"],"ja":["VS Code 統合が必要","医療論文の執筆と研究のコンテキストのみ","PubMed 検索機能に依存している"],"ko":["VS Code 통합이 필요합니다","의학 논문 작성 및 연구 컨텍스트에서만 제한됩니다","PubMed 검색 기능에 의존합니다"],"es":["Requiere integración con VS Code","Limitado a contextos de escritura y investigación de artículos médicos","Dependiente de la funcionalidad de búsqueda de PubMed"],"fr":["Nécessite une intégration avec VS Code","Limité aux contextes de rédaction et de recherche d''articles médicaux","Dépendant de la fonctionnalité de recherche PubMed"],"de":["Benötigt eine Integration mit VS Code","Begrenzt auf Kontexte der medizinischen Artikelveröffentlichung und Forschung","Abhängig von der PubMed-Suchfunktion"],"pt":["Requer integração com o VS Code","Limitado a contextos de escrita e pesquisa de artigos médicos","Dependente da funcionalidade de busca do PubMed"],"ru":["Требует интеграции с VS Code","Ограничен контекстами написания и исследования медицинских статей","Зависит от функциональности поиска PubMed"],"ar":["يتطلب تكامل مع VS Code","محدود السياقات البحثية والكتابة للأوراق الطبية","يعتمد على وظيفة بحث PubMed"]},"version":4},"contentHash":"7bd1d14ccc1a60095ed589b99c104b679658878e3ba094794516234339dfb7ed","qualityScore":23}');
