INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('u9401066/med-paper-assistant/memory-updater', 'memory-updater', 'u9401066', 'med-paper-assistant', 'community', 'memory-updater u9401066 med-paper-assistant community academic-writing ai-assistant ai-tools citation-manager clinical-research copilot evidence-based-medicine literature-review mcp medical-writing model-context-protocol pubmed python scientific-writing vscode-extension The memory-updater skill is an AI-powered medical paper writing toolkit that streamlines the writing process from PubMed search to Word export within VS Code, benefiting clinical researchers and academic writers. memory-updater是AI-powered的医学论文写作工具，支持PubMed搜索、Word导出等功能 memory-updaterはAIエージェントによる医学論文作成ツールで、PubMed検索、Wordエクスポートなどをサポート memory-updater는 AI 에이전트를 활용한 의학 논문 작성 도구로, PubMed 검색, Word导出 등을 지원합니다 memory-updater es una herramienta de investigación médica que actualiza la memoria y proporciona herramientas de escritura para mejorar la productividad memory-updater est un outil de recherche médicale qui met à jour la mémoire et fournit des outils d''écriture pour améliorer la productivité memory-updater ist ein medizinisches Forschungstool, das die Speicheraktualisierungen durchführt und Schreibtools zur Verfügung stellt, um die Produktivität zu verbessern O memory-updater é uma ferramenta de escrita médica AI que facilita a pesquisa e a escrita de artigos médicos, integrando PubMed e VS Code. Memory-updater - это инструмент для написания медицинских статей с ИИ, который упрощает поиск и написание медицинских статей, интегрируя PubMed и VS Code. memory-updater هو أداة الكتابة الطبية بالذكاء الاصطناعي التي تسهل البحث والكتابة في المقالات الطبية، و تدمج PubMed و VS Code. how to use memory-updater memory-updater alternative memory-updater setup guide what is memory-updater memory-updater vs copilot memory-updater install AI-powered medical writing tools VS Code extensions for academic writing PubMed search integration AI医学论文写作工具 memory-updater PubMed搜索 Word导出 AI工具 记忆更新 进度记录 决策记录 memory_bank_update_progress memory_bank_update_context Triggers updates to memory, records progress, and syncs data upon work session completion Utilizes MCP Tools, including `memory_bank_update_progress` and `memory_bank_update_context` commands Supports logging decisions in decisionLog.md and displaying memory content Integrates with PubMed for efficient literature searches Exports written content to Word format memory-updater is a VS Code extension that utilizes AI to facilitate medical paper writing, including literature review, citation management, and evidence-based medicine support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frankxai/agentic-creator-os/brand-voice', 'community', 'frankxai', 'agentic-creator-os', 'frankxai/agentic-creator-os', 'brand-voice', 2, 0, 23, '2026-02-25T20:31:39Z', '2026-03-06T07:06:12.480Z', 'cf08bbcd3544bc3968220b0a64b688a13f7196265d5a09de9d142eaa015b7874', '{"id":"frankxai/agentic-creator-os/brand-voice","name":"brand-voice","description":{"en":"The brand-voice skill enables creators to write in a consistent voice, leveraging context engineering and autonomous coding. It benefits AI-powered creators using Agentic Creator OS v11.","zh":"Agentic Creator OS 的品牌声音技能，帮助开发者实现一致性声音和语气","ja":"AIエージェントを使用したブランドボイスの実現、開発者向け","ko":"Agentic Creator OS의 브랜드 목소리 기능, 개발자를 위한 일관된 목소리와 어조 구현","es":"La voz de marca es el sello único de comunicación de un creador, que se mantiene consistente en todos los canales","fr":"La voix de marque est l''empreinte unique de communication d''un créateur, qui reste cohérente sur tous les canaux","de":"Die Markenstimme ist der einzigartige Kommunikationsstempel eines Erstellers, der auf allen Kanälen konsistent bleibt","pt":"A voz de marca é fundamental para a criação de conteúdo consistente. Com Agentic Creator OS, você pode configurar uma voz de marca personalizada para melhorar a experiência do usuário.","ru":"Голос бренда имеет решающее значение для создания последовательного контента. С помощью Agentic Creator OS вы можете настроить индивидуальный голос бренда для улучшения опыта пользователя.","ar":"صوت العلامة التجارية هو أساسي لإنشاء محتوى متسق. مع منصة Agentic Creator OS، يمكنك إعداد صوت العلامة التجارية المخصص لتحسين تجربة المستخدم."},"seo":{"title":{"en":"brand-voice: Consistent Voice Setup Guide | AI Agent Skill","zh":"品牌声音 Setup Guide - 使用 Agentic Creator OS","ja":"ブランドボイス Setup Guide - AIエージェントを使用","ko":"브랜드 목소리 설정 가이드 - Agentic Creator OS 사용","es":"Guía de configuración de voz de marca para Agentes de IA","fr":"Guide de mise en place de la voix de marque pour les Agen...","de":"Einrichtungsleitfaden für Markenstimme bei KI-Agents","pt":"Guia de Configuração de Voz de Marca para Agentic Creator OS","ru":"Настройка голоса бренда для Agentic Creator OS с помощью ...","ar":"دليل إعداد صوت العلامة التجارية لمنصة Agentic Creator OS"},"description":{"en":"Unlock consistent brand communication with brand-voice. Learn how to configure voice settings and adapt tone across channels like LinkedIn and X.","zh":"了解品牌声音的重要性和使用 Agentic Creator OS 实现一致性声音的方法","ja":"ブランドボイスの重要性と AIエージェントを使用した一貫性あるボイスの実現方法","ko":"브랜드 목소리의 중요성과 Agentic Creator OS를 사용한 일관된 목소리 구현 방법","es":"Aprende a implementar la voz de marca en tus proyectos de Agentes de IA con Agentic Creator OS v11 y Claude Code","fr":"Découvrez comment mettre en place la voix de marque dans vos projets d''Agents IA avec Agentic Creator OS v11 et Claude Code","de":"Erfahren Sie, wie Sie die Markenstimme in Ihren KI-Agents-Projekten mit Agentic Creator OS v11 und Claude Code umsetzen","pt":"Aprenda a configurar a voz de marca consistente com Agentic Creator OS e descubra como melhorar a experiência do usuário com habilidades de IA","ru":"Узнайте, как настроить последовательный голос бренда с помощью Agentic Creator OS и улучшить опыт пользователя с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد صوت العلامة التجارية المتسق مع منصة Agentic Creator OS واكتشف كيفية تحسين تجربة المستخدم باستخدام مهارات الذكاء الاصطناعي"},"definition":{"en":"brand-voice is a skill that maintains a consistent voice and tone for creators, using technologies like Claude Code and multi-agent orchestration.","zh":"品牌声音是指品牌的个性和沟通风格","ja":"ブランドボイスは、ブランドの個性とコミュニケーションスタイル","ko":"브랜드 목소리는 브랜드의 개성과 커뮤니케이션 스타일","es":"La voz de marca es la personalidad fija de un creador, que se distingue del tono variable","fr":"La voix de marque est la personnalité fixe d''un créateur, qui se distingue du ton variable","de":"Die Markenstimme ist die feste Persönlichkeit eines Erstellers, die sich vom variablen Ton unterscheidet","pt":"Voz de marca é a personalidade única de uma marca, que se mantém consistente em todos os canais de comunicação.","ru":"Голос бренда - это уникальная личность бренда, которая остается последовательной во всех каналах коммуникации.","ar":"صوت العلامة التجارية هو الشخصية الفريدة للعلامة التجارية، والتي تظل متسقة في جميع قنوات التواصل."},"features":{"en":["Loads voice configuration for consistent communication","Distinguishes between fixed voice and variable tone","Adapts tone across channels like LinkedIn, X, and email","Works with Agentic Creator OS v11 and Claude Code","Supports multi-agent orchestration and context engineering","Integrates with plugins like Windsurf and Gemini"],"zh":["支持 Claude Code 和其他插件","实现一致性声音和语气","多agent 和子agent 支持","语境工程和钩子支持"],"ja":["Claude Code と他のプラグインをサポート","一貫性あるボイスとトーンを実現","マルチエージェントとサブエージェントをサポート","コンテキストエンジニアリングとフックをサポート"],"ko":["Claude Code 및 기타 플러그인을 지원","일관된 목소리와 어조 구현","다중 에이전트와 서브 에이전트 지원","문脈 엔지니어링과 훅 지원"],"es":["Compatibilidad con Agentic Creator OS v11","Integración con Claude Code para una codificación autónoma","Soporte para múltiples agentes y subagentes","Gestión de la voz y el tono en diferentes canales","Uso de hooks y plugins para personalizar la voz de marca"],"fr":["Compatibilité avec Agentic Creator OS v11","Intégration avec Claude Code pour une codification autonome","Prise en charge de plusieurs agents et sous-agents","Gestion de la voix et du ton sur différents canaux","Utilisation de hooks et de plugins pour personnaliser la voix de marque"],"de":["Kompatibilität mit Agentic Creator OS v11","Integration mit Claude Code für eine autonome Codierung","Unterstützung für mehrere Agenten und Subagenten","Verwaltung von Stimme und Ton auf verschiedenen Kanälen","Verwendung von Hooks und Plugins zur Anpassung der Markenstimme"],"pt":["Configuração de voz de marca personalizada","Integração com Claude Code e outros plugins","Compatibilidade com Agentic Creator OS v11","Suporte a múltiplos agentes e subagentes","Capacidade de adaptação de tom e contexto"],"ru":["Настройка индивидуального голоса бренда","Интеграция с Claude Code и другими плагинами","Совместимость с Agentic Creator OS v11","Поддержка нескольких агентов и субагентов","Возможность адаптации тона и контекста"],"ar":["إعداد صوت العلامة التجارية المخصص","التكامل مع Claude Code وبرامج附属 أخرى","التوافق مع منصة Agentic Creator OS v11","دعم متعدّد الوكلاء والوكلاء الفرعيين","القدرة على التكيف مع النبرة والسياق"]},"keywords":{"en":["how to use brand-voice","brand-voice alternative","brand-voice setup guide","what is brand-voice","brand-voice vs tone","install brand-voice","Claude Code plugins","Agentic Creator OS v11 skills","context engineering for AI agents"],"zh":["品牌声音","Agentic Creator OS","AIエージェント","一致性声音","语境工程","Claude Code","开发者工具"],"ja":["ブランドボイス","AIエージェント","一貫性あるボイス","コンテキストエンジニアリング","Claude Code","開発者ツール"],"ko":["브랜드 목소리","AI 에이전트","일관된 목소리","문脈 엔지니어링","Claude Code","개발자 도구"],"es":["Agentes de IA","Voz de marca","Agentic Creator OS v11","Claude Code","Desarrollo de software","Codificación autónoma","Markenstimme","Tono variable","Gestión de la voz"],"fr":["Agents IA","Voix de marque","Agentic Creator OS v11","Claude Code","Développement de logiciels","Codification autonome","Personnalisation de la voix","Tonalité variable","Gestion de la voix"],"de":["KI-Agents","Markenstimme","Agentic Creator OS v11","Claude Code","Software-Entwicklung","Autonome Codierung","Anpassung der Markenstimme","Variabler Ton","Stimmverwaltung"],"pt":["voz de marca","Agentic Creator OS","IA","configuração de voz de marca","Claude Code","plugins de IA","desenvolvimento de software","experiência do usuário"],"ru":["голос бренда","Agentic Creator OS","ИИ","настройка голоса бренда","Claude Code","плагины ИИ","разработка программного обеспечения","опыт пользователя"],"ar":["صوت العلامة التجارية","منصة Agentic Creator OS","الذكاء الاصطناعي","إعداد صوت العلامة التجارية","Claude Code","برامج附属 الذكاء الاصطناعي","تطوير البرمجيات","تجربة المستخدم"]}},"owner":"frankxai","repo":"agentic-creator-os","repoPath":"frankxai/agentic-creator-os","stars":2,"forks":0,"updatedAt":"2026-02-25T20:31:39Z","topics":["agentic-skills","ai-agents","autonomous-coding","claude-code","claude-code-plugins","context-engineering","developer-tools","hooks","llm","multi-agent","orchestration","skills","subagents"],"category":"community","skillMd":{"name":"brand-voice","description":"Apply and enforce brand voice across all content creation. Manages voice attributes, tone adaptation by channel, style rules, and terminology. Use when writing content, reviewing drafts, or defining brand voice for a new project. Loads voice config from CREATOR.md or creator-memory/voice.md.","bodyPreview":"# Brand Voice\n\nWrite in a consistent voice — not just tone, but the specific fingerprint of how a creator communicates.\n\n## Voice vs. Tone\n\n**Voice** is fixed. It''s the personality — what the brand always sounds like.\n**Tone** is variable. It''s the emotional inflection applied to the voice based on context.\n\nA creator''s voice stays consistent across channels. Tone adapts: more formal on LinkedIn, punchier on X, warmer in email.\n\n## Voice Loading\n\nBefore writing, check for voice config in this or","body":"# Brand Voice\n\nWrite in a consistent voice — not just tone, but the specific fingerprint of how a creator communicates.\n\n## Voice vs. Tone\n\n**Voice** is fixed. It''s the personality — what the brand always sounds like.\n**Tone** is variable. It''s the emotional inflection applied to the voice based on context.\n\nA creator''s voice stays consistent across channels. Tone adapts: more formal on LinkedIn, punchier on X, warmer in email.\n\n## Voice Loading\n\nBefore writing, check for voice config in this order:\n1. `CREATOR.md` — voice section (quick ref, covers 90% of cases)\n2. `creator-memory/voice.md` — full documentation with examples\n3. If neither exists: ask user to describe their voice, or offer to initialize\n\n## The 5 Voice Components\n\nA complete voice profile covers:\n\n### 1. Voice Attributes (3-5 maximum)\nEach attribute defined as:\n- **We are**: what it means in practice\n- **We are not**: the misinterpretation to avoid\n- **Sounds like**: example sentence\n- **Never sounds like**: anti-example\n\nExample for \"Cool Authority\":\n- **We are**: confident, precise, lets the work speak\n- **We are not**: arrogant, dismissive, or name-dropping\n- **Sounds like**: \"[Specific result]. Here''s what that teaches you about [topic].\"\n- **Never sounds like**: \"As a top AI architect, I know better than most that...\"\n\n### 2. Audience Definition\n- Who the primary audience is\n- What they already know (don''t over-explain)\n- What they want from this creator\n- How they expect to be addressed (peer, student, collaborator)\n\n### 3. Content Pillars\n3-5 core themes the creator consistently covers. Every piece of content should belong to one. Defined with topic focus, audience, and core argument.\n\n### 4. Tone Adaptation Rules\nHow the voice shifts by context while staying recognizably consistent.\n\n| Channel | Tone shift | Example |\n|---------|-----------|---------|\n| Long-form blog | Educational, complete, evidence-based | Full arguments, examples, conclusions |\n| LinkedIn | Professional, thought-provoking, personal | First-person insight, business framing |\n| X/Twitter | Direct, punchy, opinionated | Short sentences, bold claims |\n| Email | Personal, warm, action-oriented | \"You\" framing, clear next step |\n| Video | Conversational, energetic | Shorter sentences, visual language |\n\n### 5. Terminology Rules\nPreferred and avoided terms. Examples:\n- \"creators\" not \"influencers\"\n- \"ships\" not \"launches\" (for product releases)\n- \"AI music\" not \"generated music\"\n- Never: spiritual language, guru tone, lazy CTAs (\"drop a comment below\")\n\n## Applying Voice to Content\n\nWhen writing, run this checklist:\n1. Read the voice attributes from CREATOR.md\n2. Draft the opener — rewrite until it sounds like the creator\n3. Check for anti-patterns (things this creator never says)\n4. Verify tone matches the channel rules\n5. Check terminology — any flagged words used?\n\n**Red flags requiring revision:**\n- Opener starts with \"I\" (usually weak, unless intentional personal story)\n- More than one \"!\" in a piece\n- \"Amazing\", \"awesome\", \"incredible\" (generic, not precise)\n- \"In today''s fast-paced world...\" (stock opener, never use)\n- Passive voice where active works better\n- Hedging: \"I think\", \"maybe\", \"possibly\" (unless intentional)\n\n## Loading Voice Config\n\nCheck for voice documentation in this priority order:\n1. `CREATOR.md` in the current project (hot cache — covers 90% of requests)\n2. `creator-memory/voice.md` in the current project (full documentation)\n3. Project `CLAUDE.md` — look for a \"Brand Positioning\" or \"Voice\" section\n4. If none found: ask the user to describe their voice, or run `/creator-sprint`\n\nSee `references/voice-frameworks.md` for the full voice documentation template and attribute definition system.\n"},"lastSynced":"2026-03-06T07:06:12.480Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing consistent tone and voice generation across multiple channels.","zh":"适用于需要在多个渠道上保持一致的语气和声音生成的内容创建代理。","ja":"複数のチャネルで一貫したトーンとボイス生成が必要なコンテンツ作成エージェントに適しています。","ko":"여러 채널에서 일관된 음색과 음성을 생성해야 하는 콘텐츠 생성 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Creación de Contenido que necesitan una generación de tono y voz coherente en múltiples canales.","fr":"Parfait pour les agents de création de contenu ayant besoin d''une génération de ton et de voix cohérente sur plusieurs canaux.","de":"Perfekt für Content-Erstellung-Agenten, die eine konsistente Tonalität und Stimmgenerierung über mehrere Kanäle hinweg benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo que necessitam de geração de tom e voz consistentes em vários canais.","ru":"Идеально подходит для агентов по созданию контента, которым требуется последовательная генерация тона и голоса на нескольких каналах.","ar":"مثالي لعميل إنشاء المحتوى الذي يحتاج إلى إنشاء صوت وطابع مستمر عبر عدة قنوات."},"recommendation":{"en":"Empowers agents to maintain a consistent brand voice through context engineering and autonomous coding, ensuring a unique personality shines through in every piece of content, whether it''s a formal LinkedIn post or a punchier X post, all while adapting tone based on context using protocols like voice config loading.","zh":"通过上下文工程和自主编码，赋予代理保持一致的品牌声音的能力，确保每个内容都展现出独特的个性，无论是正式的LinkedIn帖子还是更活泼的X帖子，同时使用诸如语音配置加载之类的协议根据上下文调整语气。","ja":"コンテキストエンジニアリングとオートノマスコーディングを通じて、エージェントが一貫したブランドボイスを維持できるようにし、LinkedInのフォーマルポストやXのパンチーのポストなど、どのようなコンテンツでも独自の個性が光ることを保証し、ボイスコンフィグロードなどのプロトコルを使用してコンテキストに基づいてトーンを適応させる。","ko":"문맥 엔지니어링과 자율 코딩을 통해 에이전트가 일관된 브랜드 음성을 유지할 수 있도록 하여, LinkedIn의 공식 게시물이나 X의 더活泼한 게시물 등 모든 콘텐츠에서 고유한 개성이 빛나는 것을 보장하며, 음성 구성 로드와 같은 프로토콜을 사용하여 문맥에 따라 음调을 조정합니다.","es":"Habilita a los agentes a mantener una voz de marca coherente a través de la ingeniería de contexto y la codificación autónoma, asegurando que una personalidad única brille en cada pieza de contenido, ya sea un post formal de LinkedIn o un post más impactante de X, todo mientras se adapta el tono según el contexto utilizando protocolos como la carga de configuración de voz.","fr":"Permet aux agents de maintenir une voix de marque cohérente grâce à l''ingénierie de contexte et à la codification autonome, en veillant à ce qu''une personnalité unique se démarque dans chaque pièce de contenu, qu''il s''agisse d''un post LinkedIn formel ou d''un post X plus percutant, le tout en adaptant le ton en fonction du contexte en utilisant des protocoles tels que le chargement de la configuration vocale.","de":"Ermächtigt Agenten, eine konsistente Markenstimme durch Kontextengineering und autonomes Codieren zu wahren, um sicherzustellen, dass eine einzigartige Persönlichkeit in jedem Inhaltstück leuchtet, sei es ein formeller LinkedIn-Post oder ein prägnanterer X-Post, und zwar unter Anpassung des Tons basierend auf dem Kontext mithilfe von Protokollen wie der Sprachkonfigurationsladung.","pt":"Habilita os agentes a manter uma voz de marca consistente por meio da engenharia de contexto e codificação autônoma, garantindo que uma personalidade única brilhe em cada peça de conteúdo, seja um post formal do LinkedIn ou um post mais impactante do X, adaptando o tom com base no contexto usando protocolos como carregamento de configuração de voz.","ru":"Наделяет агентов возможностью поддерживать последовательный бренд-голос посредством контекстной инженерии и автономального кодирования, гарантируя, что уникальная личность сияет в каждом контенте, будь то формальный пост в LinkedIn или более живой пост в X, адаптируя тон на основе контекста с использованием протоколов, таких как загрузка конфигурации голоса.","ar":"تمكّن الوكلاء من الحفاظ على صوت العلامة التجارية الثابت من خلال هندسة السياق والبرمجة المستقلة، مما يضمن ظهور شخصية فريدة في كل قطعة من المحتوى، سواء كان منشورًا رسميًا على LinkedIn أو منشورًا أكثر حدة على X، مع تعديل النبرة بناءً على السياق باستخدام بروتوكولات مثل تحميل تكوين الصوت."},"useCases":{"en":["Automating content generation with consistent voice","Generating tone-adapted responses for social media","Debugging inconsistencies in brand communication"],"zh":["使用一致的语音自动化内容生成","为社交媒体生成语气适应的响应","调试品牌沟通中的不一致性"],"ja":["一貫したボイスで自動コンテンツ生成を行う","ソーシャルメディア用にトーン適応のレスポンスを生成する","ブランドコミュニケーションの不一致をデバッグする"],"ko":["일관된 음성을 사용하여 자동 콘텐츠 생성하기","소셜 미디어용으로 음调 조정된 응답 생성하기","브랜드 커뮤니케이션의 불일치 디버깅"],"es":["Automatización de la generación de contenido con voz coherente","Generación de respuestas adaptadas al tono para las redes sociales","Depuración de inconsistencias en la comunicación de la marca"],"fr":["Automatisation de la génération de contenu avec voix cohérente","Génération de réponses adaptées au ton pour les réseaux sociaux","Débogage des incohérences dans la communication de la marque"],"de":["Automatisierung der Inhaltsgenerierung mit konsistenter Stimme","Generierung von tonangepassten Antworten für soziale Medien","Fehlerbehebung bei Inkonsistenzen in der Markenkommunikation"],"pt":["Automatizar a geração de conteúdo com voz consistente","Gerar respostas adaptadas ao tom para mídias sociais","Depurar inconsistências na comunicação da marca"],"ru":["Автоматизировать генерацию контента с последовательным голосом","Генерировать ответы, адаптированные к тону, для социальных сетей","Отлаживать несоответствия в коммуникации бренда"],"ar":["توفير آلي لإنشاء المحتوى مع صوت مستمر","إنشاء استجابات متكيفة مع النبرة للمواقع الاجتماعية","تصحيح عدم الاتساق في اتصالات العلامة التجارية"]},"limitations":{"en":["Requires Agentic Creator OS v11","Dependent on accurate voice configuration"],"zh":["需要Agentic Creator OS v11","依赖于准确的语音配置"],"ja":["Agentic Creator OS v11が必要","正確なボイス構成に依存"],"ko":["Agentic Creator OS v11 필요","정확한 음성 구성에 의존"],"es":["Requiere Agentic Creator OS v11","Dependiente de una configuración de voz precisa"],"fr":["Nécessite Agentic Creator OS v11","Dépendante d''une configuration vocale précise"],"de":["Benötigt Agentic Creator OS v11","Abhängig von einer genauen Sprachkonfiguration"],"pt":["Requer Agentic Creator OS v11","Dependente de configuração de voz precisa"],"ru":["Требуется Agentic Creator OS v11","Зависит от точной конфигурации голоса"],"ar":["يتطلب نظام تشغيل Agentic Creator OS v11","يعتمد على تكوين صوت دقيق"]},"version":4},"contentHash":"cf08bbcd3544bc3968220b0a64b688a13f7196265d5a09de9d142eaa015b7874","qualityScore":23}');
