INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frankxai/agentic-creator-os/brand-voice', 'brand-voice', 'frankxai', 'agentic-creator-os', 'community', 'brand-voice frankxai agentic-creator-os community agentic-skills ai-agents autonomous-coding claude-code claude-code-plugins context-engineering developer-tools hooks llm multi-agent orchestration skills subagents The brand-voice skill enables creators to write in a consistent voice, leveraging context engineering and autonomous coding. It benefits AI-powered creators using Agentic Creator OS v11. Agentic Creator OS 的品牌声音技能，帮助开发者实现一致性声音和语气 AIエージェントを使用したブランドボイスの実現、開発者向け Agentic Creator OS의 브랜드 목소리 기능, 개발자를 위한 일관된 목소리와 어조 구현 La voz de marca es el sello único de comunicación de un creador, que se mantiene consistente en todos los canales La voix de marque est l''empreinte unique de communication d''un créateur, qui reste cohérente sur tous les canaux Die Markenstimme ist der einzigartige Kommunikationsstempel eines Erstellers, der auf allen Kanälen konsistent bleibt A voz de marca é fundamental para a criação de conteúdo consistente. Com Agentic Creator OS, você pode configurar uma voz de marca personalizada para melhorar a experiência do usuário. Голос бренда имеет решающее значение для создания последовательного контента. С помощью Agentic Creator OS вы можете настроить индивидуальный голос бренда для улучшения опыта пользователя. صوت العلامة التجارية هو أساسي لإنشاء محتوى متسق. مع منصة Agentic Creator OS، يمكنك إعداد صوت العلامة التجارية المخصص لتحسين تجربة المستخدم. how to use brand-voice brand-voice alternative brand-voice setup guide what is brand-voice brand-voice vs tone install brand-voice Claude Code plugins Agentic Creator OS v11 skills context engineering for AI agents 品牌声音 Agentic Creator OS AIエージェント 一致性声音 语境工程 Claude Code 开发者工具 Loads voice configuration for consistent communication Distinguishes between fixed voice and variable tone Adapts tone across channels like LinkedIn, X, and email Works with Agentic Creator OS v11 and Claude Code Supports multi-agent orchestration and context engineering Integrates with plugins like Windsurf and Gemini brand-voice is a skill that maintains a consistent voice and tone for creators, using technologies like Claude Code and multi-agent orchestration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bauerlucks-tech/escalasbmi/skill', 'community', 'bauerlucks-tech', 'escalasbmi', 'bauerlucks-tech/escalasbmi', 'skill', 2, 0, 23, '2026-03-01T20:08:15Z', '2026-03-06T07:08:38.488Z', '77e72fa2943a203224d7bcd3b050b9a4d0ccaec82a3d81b6200e3c26047199d0', '{"id":"bauerlucks-tech/escalasbmi/skill","name":"skill","description":{"en":"The Skill provides instructions for AI agents, offering relative paths to other resources in the skill directory. It benefits developers working with AI agents.","zh":"AIエージェント Skill 提供了相对路径的资源访问和技术指南","ja":"AIエージェント Skill は相対パスのリソースアクセスと技術ガイドを提供する","ko":"AI 에이전트 Skill은 상대 경로의 리소스 접근과 기술 가이드를 제공한다","es":"El skill proporciona instrucciones para su configuración y uso. Los desarrolladores pueden acceder a recursos adicionales en el directorio del skill.","fr":"La compétence skill fournit des instructions pour sa configuration et son utilisation. Les développeurs peuvent accéder à des ressources supplémentaires dans le répertoire de la compétence.","de":"Das skill bietet Anweisungen für seine Einrichtung und Verwendung. Entwickler können auf zusätzliche Ressourcen im Skill-Verzeichnis zugreifen.","pt":"O skill fornece instruções para configuração e uso de recursos relativos no diretório do skill.","ru":"Навык предоставляет инструкции для настройки и использования относительных путей к другим ресурсам в директории навыка.","ar":"المهارة توفر إرشادات لتهيئة واستخدام مسارات 相対 في دليل المهارات."},"seo":{"title":{"en":"Skill: Setup Guide for AI Agents | AI Agent Skill","zh":"AIエージェント Skill 设置指南","ja":"AIエージェント Skill ベストプラクティス","ko":"AI 에이전트 Skill 구축 가이드","es":"Guía de configuración de skill para desarrolladores","fr":"Guide d''installation de la compétence skill pour les déve...","de":"Einrichtungsleitfaden für Entwickler von skill","pt":"Guia de Configuração do Skill de Agente de IA","ru":"