INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bauerlucks-tech/escalasbmi/skill', 'skill', 'bauerlucks-tech', 'escalasbmi', 'community', 'skill bauerlucks-tech escalasbmi community The Skill provides instructions for AI agents, offering relative paths to other resources in the skill directory. It benefits developers working with AI agents. AIエージェント Skill 提供了相对路径的资源访问和技术指南 AIエージェント Skill は相対パスのリソースアクセスと技術ガイドを提供する AI 에이전트 Skill은 상대 경로의 리소스 접근과 기술 가이드를 제공한다 El skill proporciona instrucciones para su configuración y uso. Los desarrolladores pueden acceder a recursos adicionales en el directorio del skill. La compétence skill fournit des instructions pour sa configuration et son utilisation. Les développeurs peuvent accéder à des ressources supplémentaires dans le répertoire de la compétence. Das skill bietet Anweisungen für seine Einrichtung und Verwendung. Entwickler können auf zusätzliche Ressourcen im Skill-Verzeichnis zugreifen. O skill fornece instruções para configuração e uso de recursos relativos no diretório do skill. Навык предоставляет инструкции для настройки и использования относительных путей к другим ресурсам в директории навыка. المهارة توفر إرشادات لتهيئة واستخدام مسارات 相対 في دليل المهارات. how to use Skill what is Skill Skill alternative Skill vs other AI agents Skill install Skill setup guide Skill for AI agents Skill technical capabilities AIエージェント Skill AI 工具设置 开发效率提高 相对路径资源访问 技术指南 CLI 接口 React 支持 Python 支持 AIエージェント开发 Provides instructions for AI agents Offers relative paths to other resources in the skill directory Supports access to SKILL.md content Enables implementation of specific commands and protocols Skill is a technical capability that provides instructions for AI agents, enabling access to relative paths and other resources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hivellm/tml/artifacts', 'community', 'hivellm', 'tml', 'hivellm/tml', 'artifacts', 1, 1, 23, '2026-02-26T06:21:16Z', '2026-03-06T07:12:49.247Z', 'e460d1cdb64d0a2ded04f9bfe3fcea6a6af03c8fcdabf56f56c07d0751047aaf', '{"id":"hivellm/tml/artifacts","name":"artifacts","description":{"en":"The artifacts skill enables developers to manage TML project artifacts using the mcp__tml__project_artifacts tool, providing a deterministic approach to code generation and analysis. This skill benefits AI agent developers working with Large Language Models.","zh":"TML语言和mcp__tml__project_artifacts工具帮助您高效管理Artifact","ja":"TML言語とmcp__tml__project_artifactsツールを使用して、Artifactを効率的に管理します","ko":"TML 언어와 mcp__tml__project_artifacts 툴을 사용하여 Artifact를 효율적으로 관리합니다","es":"El comando mcp__tml__project_artifacts permite listar artefactos de proyecto TML con opciones de filtrado por tipo y configuración. Esta herramienta es útil para el análisis y la generación de código determinista en TML.","fr":"La commande mcp__tml__project_artifacts permet de lister les artefacts de projet TML avec des options de filtrage par type et configuration. Cet outil est utile pour l''analyse et la génération de code déterministe dans TML.","de":"Der Befehl mcp__tml__project_artifacts ermöglicht die Auflistung von TML-Projektartefakten mit Filteroptionen nach Typ und Konfiguration. Dieses Tool ist nützlich für die Analyse und die deterministische Codegenerierung in TML.","pt":"O skill artifacts permite que desenvolvedores usem o MCP tool para listar artefatos de projetos TML de forma eficiente","ru":"Навык артефактов позволяет разработчикам использовать инструмент MCP для вывода списка артефактов проектов TML","ar":"يسمح سكيل الملفات المكونة لمطوري التطبيقات باستخدام أداة MCP لاستعراض ملفات مكونة لمشاريع TML"},"seo":{"title":{"en":"Artifacts: TML Project Artifact Management Setup Guide | ...","zh":"AIエージェントArtifact设置指南","ja":"AIエージェントArtifactのベストプラクティス","ko":"AI 에이전트 Artifact 설정 가이드","es":"Guía de configuración de artefactos de TML","fr":"Guide de mise en place des artefacts TML","de":"Einrichtungsleitfaden für TML-Artefakte","pt":"Guia de Configuração de Artifacts para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Артефактов","ar":"دليل إعداد الملفات المكونة لملحقي التطبيق"},"description":{"en":"Discover how to list and manage TML project artifacts with the mcp__tml__project_artifacts tool. Learn more and get started today!","zh":"了解如何使用TML语言和mcp__tml__project_artifacts工具来管理和优化Artifact","ja":"TML言語とmcp__tml__project_artifactsツールを使用してArtifactを管理および最適化する方法について学びます","ko":"TML 언어와 mcp__tml__project_artifacts 툴을 사용하여 Artifact를 관리하고 최적화하는 방법에 대해 알아보세요","es":"Aprende a utilizar el comando mcp__tml__project_artifacts para listar artefactos de proyecto TML con filtrado por tipo y configuración","fr":"Découvrez comment utiliser la commande mcp__tml__project_artifacts pour lister les artefacts de projet TML avec filtrage par type et configuration","de":"Erfahren Sie, wie Sie den Befehl mcp__tml__project_artifacts verwenden, um TML-Projektartefakte mit Filterung nach Typ und Konfiguration zu listen","pt":"Aprenda a usar o MCP tool para listar artefatos de projetos TML, incluindo executáveis, bibliotecas e cache","ru":"Используйте инструмент MCP для вывода списка артефактов проектов TML, включая исполняемые файлы, библиотеки и кэш","ar":"تعلم كيفية استخدام أداة MCP لاستعراض ملفات مكونة لمشاريع TML، بما في ذلك الملفات التنفيذية والمكتبات والแคش"},"definition":{"en":"Artifacts is a TML programming language feature that provides stable IDs for refactoring and uses formal contracts for deterministic code generation and analysis.","zh":"Artifact是TML语言中用于管理和优化代码的产物","ja":"Artifactは、TML言語でコードを管理および最適化するために使用される成果物です","ko":"Artifact는 TML 언어에서 코드를 관리하고 최적화하기 위해 사용되는 산물입니다","es":"Un artefacto de TML es un elemento generado por el comando mcp__tml__project_artifacts, que puede ser un ejecutable, una biblioteca, una caché o un informe de cobertura","fr":"Un artefact TML est un élément généré par la commande mcp__tml__project_artifacts, qui peut être un exécutable, une bibliothèque, une cache ou un rapport de couverture","de":"Ein TML-Artefakt ist ein durch den Befehl mcp__tml__project_artifacts generiertes Element, das ein ausführbares Programm, eine Bibliothek, eine Zwischenspeicherung oder ein Abdeckungsbericht sein kann","pt":"Artifacts são resultados de compilação de projetos TML, como executáveis e bibliotecas","ru":"Артефакты - это результаты компиляции проектов TML, такие как исполняемые файлы и библиотеки","ar":"الملفات المكونة هي نتائج مترجمات مشاريع TML، مثل الملفات التنفيذية والمكتبات"},"features":{"en":["Uses the mcp__tml__project_artifacts MCP tool for artifact management","Filters artifacts by type, including executables, libraries, cache, and coverage","Supports release and debug configurations with the --release and --all flags","Displays artifact listings with sizes and modification times","Utilizes formal contracts for deterministic code generation and analysis"],"zh":["使用mcp__tml__project_artifacts工具列出构建Artifact","支持根据类型过滤Artifact：执行文件、库、缓存、覆盖率或所有","支持根据配置过滤Artifact：发布、调试或所有","显示Artifact列表，包括大小和修改时间"],"ja":["mcp__tml__project_artifactsツールを使用してビルドArtifactをリストする","タイプによるArtifactのフィルタリングをサポート：実行可能ファイル、ライブラリ、キャッシュ、カバレッジ、またはすべて","構成によるArtifactのフィルタリングをサポート：リリース、デバッグ、またはすべて","Artifactリストを表示する、サイズと変更時刻を含む"],"ko":["mcp__tml__project_artifacts 툴을 사용하여 빌드 Artifact를 나열합니다","유형에 따라 Artifact를 필터링합니다: 실행 파일, 라이브러리, 캐시, 커버리지 또는 모든","구성에 따라 Artifact를 필터링합니다: 릴리스, 디버깅 또는 모든","Artifact 목록을 표시합니다, 크기와 수정 시간을 포함하여"],"es":["Soporte para filtrado por tipo de artefacto (ejecutable, biblioteca, caché, cobertura)","Opción de configuración para especificar el tipo de compilación (debug, release, all)","Capacidad para listar artefactos con información de tamaño y fecha de modificación","Integración con 