INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hivellm/tml/artifacts', 'artifacts', 'hivellm', 'tml', 'community', 'artifacts hivellm tml community The artifacts skill enables developers to manage TML project artifacts using the mcp__tml__project_artifacts tool, providing a deterministic approach to code generation and analysis. This skill benefits AI agent developers working with Large Language Models. TML语言和mcp__tml__project_artifacts工具帮助您高效管理Artifact TML言語とmcp__tml__project_artifactsツールを使用して、Artifactを効率的に管理します TML 언어와 mcp__tml__project_artifacts 툴을 사용하여 Artifact를 효율적으로 관리합니다 El comando mcp__tml__project_artifacts permite listar artefactos de proyecto TML con opciones de filtrado por tipo y configuración. Esta herramienta es útil para el análisis y la generación de código determinista en TML. La commande mcp__tml__project_artifacts permet de lister les artefacts de projet TML avec des options de filtrage par type et configuration. Cet outil est utile pour l''analyse et la génération de code déterministe dans TML. Der Befehl mcp__tml__project_artifacts ermöglicht die Auflistung von TML-Projektartefakten mit Filteroptionen nach Typ und Konfiguration. Dieses Tool ist nützlich für die Analyse und die deterministische Codegenerierung in TML. O skill artifacts permite que desenvolvedores usem o MCP tool para listar artefatos de projetos TML de forma eficiente Навык артефактов позволяет разработчикам использовать инструмент MCP для вывода списка артефактов проектов TML يسمح سكيل الملفات المكونة لمطوري التطبيقات باستخدام أداة MCP لاستعراض ملفات مكونة لمشاريع TML how to use artifacts what is artifacts artifacts setup guide TML project artifact management mcp__tml__project_artifacts tool artifacts vs other LLM tools install artifacts artifacts for AI agents deterministic code generation with artifacts TML语言 Artifact管理 mcp__tml__project_artifacts工具 代码优化 AIエージェント Artifact设置 TML开发 Uses the mcp__tml__project_artifacts MCP tool for artifact management Filters artifacts by type, including executables, libraries, cache, and coverage Supports release and debug configurations with the --release and --all flags Displays artifact listings with sizes and modification times Utilizes formal contracts for deterministic code generation and analysis Artifacts is a TML programming language feature that provides stable IDs for refactoring and uses formal contracts for deterministic code generation and analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vangberg/pdit/www', 'community', 'vangberg', 'pdit', 'vangberg/pdit', 'www', 1, 0, 23, '2026-02-26T08:00:42Z', '2026-03-06T07:13:55.636Z', 'f8140c8841faede77fe4e860b89ec9d011409c70163874c98bbfef20224d88ca', '{"id":"vangberg/pdit/www","name":"www","description":{"en":"The www skill, also known as The Python Un-Notebook, enables developers to update content, add pages, and adjust styling on the Astro site. It benefits developers working with Astro websites.","zh":"www 技术允许您在 Astro 网站上更新内容、添加页面或新闻帖子，并调整样式","ja":"www 技術を使って Astro サイトでコンテンツを更新したり、ページやニュース投稿を追加したり、スタイルを調整したりできます","ko":"www 기술을 사용하여 Astro 웹사이트에서 콘텐츠를 업데이트하고 페이지나 뉴스 게시물을 추가하고 스타일을 조정할 수 있습니다","es":"www es una herramienta de AI para crear sitios web con Astro, que permite actualizar contenido, agregar páginas y ajustar estilos","fr":"www est un outil d''IA pour créer des sites web avec Astro, qui permet de mettre à jour le contenu, d''ajouter des pages et d''ajuster les styles","de":"www ist ein KI-Tool zum Erstellen von Websites mit Astro, mit dem Sie Inhalte aktualisieren, Seiten hinzufügen und Stile anpassen können","pt":"O www é um projeto de site Astro que permite atualizar conteúdo, adicionar páginas e notícias, e ajustar estilos de acordo com o sistema de design local.","ru":"www - это проект сайта Astro, который позволяет обновлять контент, добавлять страницы и новости, и настраивать стили в соответствии с локальной системой дизайна.","ar":"www هو مشروع موقع Astro يسمح بتحديث المحتوى، وإضافة صفحات واخبار، وتعديل الأنماط وفقًا لنظام التصميم المحلي."},"seo":{"title":{"en":"www: Astro Website Development Setup Guide | AI Agent Skill","zh":"www 快速入门指南 - Astro 网站开发最佳实践","ja":"www セットアップガイド - Astro サイトの開発方法","ko":"www 설정 가이드 - Astro 웹사이트 개발 팁","es":"Herramientas de AI: Configuración de www con Astro","fr":"Outils d''IA: Guide de démarrage rapide pour www avec Astro","de":"KI-Tools: Einrichtung von www mit Astro","pt":"Guia de Configuração do www: Desenvolvimento de Sites Astro","ru":"ИИ Агенты: Настройка www для Разработки Сайтов Astro","ar":"دليل إعداد www: تطوير مواقع Astro باستخدام الإيمان الإلكت..."},"description":{"en":"Discover how to work with the Astro site in www/, update content, and adjust styling with this comprehensive guide - get started now!","zh":"了解 www 技术，快速开发 Astro 网站，掌握 npm 安装、运行开发服务器、构建和预览的方法","ja":"www 技術をマスターし、Astro サイトの開発をスピードアップするためのヒントをご紹介","ko":"www 기술을 익히고 Astro 웹사이트 개발을 가속화하는 방법을 알아보세요","es":"Aprende a configurar y personalizar tu sitio web con www y Astro, incluyendo la instalación de dependencias y la creación de rutas","fr":"Découvrez comment configurer et personnaliser votre site web avec www et Astro, y compris l''installation des dépendances et la création de routes","de":"Erfahren Sie, wie Sie Ihre Website mit www und Astro konfigurieren und anpassen, einschließlich der Installation von Abhängigkeiten und der Erstellung von Ro...","pt":"Aprenda a configurar o www para desenvolver sites Astro com eficiência. Instale dependências, execute o servidor de desenvolvimento e construa seu site.","ru":"Узнайте, как настроить www для разработки сайтов Astro. Установите зависимости, запустите сервер разработки и соберите сайт.","ar":"تعلم كيفية إعداد www لتطوير مواقع Astro بفعالية. قم بتثبيت الإعتماديات، تشغيل خادم التطوير، وبناء موقعك."},"definition":{"en":"www is a Python-based Astro website development environment for updating content, adding pages, and adjusting styling","zh":"www 是一个 Astro 网站开发工具，允许您更新内容、添加页面和新闻帖子","ja":"www は Astro サイトの開発ツールで、コンテンツの更新、ページやニュース投稿の追加が可能","ko":"www는 Astro 웹사이트 개발 도구로 콘텐츠 업데이트와 페이지 및 뉴스 게시물을 추가할 수 있습니다","es":"www es una herramienta de AI que permite crear y personalizar sitios web con Astro","fr":"www est un outil d''IA qui permet de créer et de personnaliser des sites web avec Astro","de":"www ist ein KI-Tool, mit dem Sie Websites mit Astro erstellen und anpassen können","pt":"O www é um projeto de site Astro que utiliza tecnologias como Astro.glob e npm para desenvolver e construir sites.","ru":"www - это проект сайта Astro, который использует технологии как Astro.glob и npm для разработки и сборки сайтов.","ar":"www هو مشروع موقع Astro يعتمد على تقنيات مثل Astro.glob وnpm لتطوير وبناء المواقع."},"features":{"en":["Updates content and adds pages using Astro.glob","Adjusts styling following the local design system","Installs dependencies via npm install in the www directory","Runs a development server with npm run dev","Previews builds using npm run preview","Organizes route files in www/src/pages/"],"zh":["支持 Astro.glob 功能","使用 npm 安装依赖项","运行开发服务器以预览更改","构建和预览 Astro 网站","使用 www/src/pages/ 目录组织路由文件","支持导入和导出功能"],"ja":["Astro.glob 機能をサポート","npm を使用して依存関係をインストール","開発サーバーを実行して変更をプレビュー","Astro サイトをビルドしてプレビュー","www/src/pages/ ディレクトリを使用してルートファイルを整理","インポートとエクスポート機能をサポート"],"ko":["Astro.glob 기능 지원","npm을 사용하여 의존성 설치","개발 서버 실행하여 변경 사항预览","Astro 웹사이트 빌드 및预览","www/src/pages/ 디렉토리를 사용하여 라우트 파일 구성","导入 및导出 기능 지원"],"es":["Instalación de dependencias con npm","Creación de rutas con Astro","Actualización de contenido y estilos","Uso de Astro.glob para listar noticias","Creación de sitios web personalizados con Astro"],"fr":["Installation des dépendances avec npm","Création de routes avec Astro","Mise à jour du contenu et des styles","Utilisation d''Astro.glob pour lister les actualités","Création de sites web personnalisés avec Astro"],"de":["Installation von Abhängigkeiten mit npm","Erstellung von Routen mit Astro","Aktualisierung von Inhalten und Stilen","Verwendung von Astro.glob zur Auflistung von Nachrichten","Erstellung von benutzerdefinierten Websites mit Astro"],"pt":["Utilize Astro.glob para listar notícias","Atualize conteúdo e adicione páginas","Ajuste estilos de acordo com o sistema de design local","Execute o servidor de desenvolvimento com npm run dev","Construa o site com npm run build","Visualize a pré-visualização do site com npm run preview"],"ru":["Используйте Astro.glob для списка новостей","Обновите контент и добавьте страницы","Настройте стили в соответствии с локальной системой дизайна","Запустите сервер разработки с npm run dev","Соберите сайт с npm run build","Просмотрите предварительный просмотр сайта с npm run preview"],"ar":["استخدم Astro.glob لاستعراض الأخبار","قم بتحديث المحتوى وإضافة صفحات","عدل الأنماط وفقًا لنظام التصميم المحلي","تشغيل خادم التطوير باستخدام npm run dev","بناء الموقع باستخدام npm run build","استعرض معاينة الموقع باستخدام npm run preview"]},"keywords":{"en":["how to use www","what is www","www alternative","www vs Astro","www install","www setup guide","Astro website development","Python Un-Notebook","npm run dev"],"zh":["www 技术","Astro 网站开发","npm 安装","Astro.glob","开发服务器","构建和预览","路由文件组织","AIエージェント","前端开发"],"ja":["www 技術","Astro サイトの開発","npm インストール","Astro.glob","開発サーバー","ビルドとプレビュー","ルートファイルの整理","AIエージェント","フロントエンド開発"],"ko":["www 기술","Astro 웹사이트 개발","npm 설치","Astro.glob","개발 서버","빌드 및预览","라우트 파일 구성","AI 에이전트","프론트엔드 개발"],"es":["herramientas de AI","desarrollo web con Astro","configuración de sitios web","creación de rutas con Astro","personalización de sitios web"," Astro.glob","npm","desarrollo de sitios web personalizados"],"fr":["outils d''IA","développement web avec Astro","configuration de sites web","création de routes avec Astro","personnalisation de sites web","Astro.glob","npm","développement de sites web personnalisés"],"de":["KI-Tools","Webentwicklung mit Astro","Konfiguration von Websites","Erstellung von Routen mit Astro","Anpassung von Websites","Astro.glob","npm","Entwicklung von benutzerdefinierten Websites"],"pt":["desenvolvimento de sites Astro","configuração do www","Astro.glob","npm","servidor de desenvolvimento","construção de sites","pré-visualização de sites","desenvolvimento web"],"ru":["разработка сайтов Astro","настройка www","Astro.glob","npm","сервер разработки","сборка сайтов","предварительный просмотр сайтов","веб-разработка"],"ar":["تطوير مواقع Astro","إعداد www","Astro.glob","npm","خادم التطوير","بناء المواقع","معاينة المواقع","تطوير الويب"]}},"owner":"vangberg","repo":"pdit","repoPath":"vangberg/pdit","stars":1,"forks":0,"updatedAt":"2026-02-26T08:00:42Z","topics":["agentic-coding","notebooks","python"],"category":"community","skillMd":{"name":"www","description":"Work on the Astro website in `www/` for pdit.dev. Use when editing site content, styles, layouts, or components; adding pages or news posts; or running Astro dev/build commands for the website.","bodyPreview":"# www Astro website\n\n## Overview\n\nWork on the Astro site in `www/`: update content, add pages or news posts, and adjust styling while following the local design system.\n\n## Quick Start\n\n- Install deps: `cd www && npm install`\n- Run dev server: `npm run dev`\n- Build: `npm run build`\n- Preview build: `npm run preview`\n\n## Project Map\n\n- Use `www/src/pages/` for route files (e.g., `index.astro`, `manual.astro`, `news/`).\n- List news posts in `www/src/pages/news/index.astro` via `Astro.glob`; export","body":"# www Astro website\n\n## Overview\n\nWork on the Astro site in `www/`: update content, add pages or news posts, and adjust styling while following the local design system.\n\n## Quick Start\n\n- Install deps: `cd www && npm install`\n- Run dev server: `npm run dev`\n- Build: `npm run build`\n- Preview build: `npm run preview`\n\n## Project Map\n\n- Use `www/src/pages/` for route files (e.g., `index.astro`, `manual.astro`, `news/`).\n- List news posts in `www/src/pages/news/index.astro` via `Astro.glob`; export `title` and `date` from each post.\n- Wrap pages with `www/src/layouts/Layout.astro`; keep `Nav`, global CSS, fonts, and analytics wired in.\n- Edit the main nav in `www/src/components/Nav.astro`.\n- Treat `www/src/styles/global.css` as the home for global typography, colors, and layout defaults.\n- Place static assets in `www/public/` (images, icons).\n- Follow the design system in `www/DESIGN.md`.\n- Avoid editing `www/dist/` directly (build output, ignored by git).\n\n## Conventions\n\n- Wrap pages with `Layout` and set `title` plus `description` when available.\n- Put shared styling in `www/src/styles/global.css`; keep page-specific styles in each `.astro` file''s `<style>` block.\n- Follow `www/DESIGN.md`: bold, high contrast, thick borders, sharp corners, palette-driven accents.\n- Preserve existing typography: Fira Mono for headings, system-ui for body.\n- Keep assets in `www/public/` and reference by absolute path (e.g., `/screenshot.png`).\n\n## Common Tasks\n\n### Update content\n\n- Edit the target `.astro` file in `www/src/pages/` or `www/src/pages/news/`.\n- Adjust local styles in the same file if layout changes are needed.\n\n### Add a new page\n\n1. Create `www/src/pages/<route>.astro`.\n2. Use `Layout` and provide `title`/`description`.\n3. Add a nav link in `www/src/components/Nav.astro` if the page should appear in the top nav.\n\n### Add a news post\n\n1. Create `www/src/pages/news/<slug>.astro`.\n2. Export `title` and `date` as strings.\n3. Use `Layout` and include a back-link to `/news/`.\n4. Rely on `Astro.glob` in `/news/` to surface the post automatically.\n"},"lastSynced":"2026-03-06T07:13:55.636Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents working with Astro websites needing advanced content management capabilities.","zh":"非常适合使用 Astro 网站的前端代理，需要高级内容管理功能。","ja":"Astro サイトで高度なコンテンツ管理機能を必要とするフロントエンド エージェントに最適です。","ko":"Astro 웹사이트에서 고급 콘텐츠 관리 기능이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes de Frontend que trabajan con sitios web de Astro y necesitan capacidades de administración de contenido avanzadas.","fr":"Parfait pour les agents Frontend qui travaillent avec des sites web Astro nécessitant des capacités de gestion de contenu avancées.","de":"Perfekt für Frontend-Agenten, die mit Astro-Websites arbeiten und erweiterte Inhaltsverwaltungsfunktionen benötigen.","pt":"Perfeito para Agentes Frontend que trabalham com sites Astro que necessitam de capacidades avançadas de gerenciamento de conteúdo.","ru":"Идеально подходит для агентов Frontend, работающих с сайтами Astro, требующими продвинутых возможностей управления контентом.","ar":"مثالي لعملاء واجهة المستخدم الذين يعملون مع مواقع Astro التي تحتاج إلى возможات متقدمة لإدارة المحتوى."},"recommendation":{"en":"Empowers agents to update content, add pages, and adjust styling on Astro sites using npm and Astro.glob, while following the local design system and leveraging route files in `www/src/pages/`.","zh":"赋予代理更新 Astro 网站内容、添加页面和调整样式的能力，使用 npm 和 Astro.glob，同时遵循本地设计系统，并利用 `www/src/pages/` 路由文件。","ja":"エージェントが Astro サイトのコンテンツを更新したり、ページやニュース ポストを追加したり（`Astro.glob` を使用）、ローカル デザイン システムに合わせてスタイリングを調整したりする機能を提供します。また、`www/src/pages/` のルート ファイルを利用します。","ko":"에이전트가 npm 및 Astro.glob를 사용하여 Astro 사이트의 콘텐츠를 업데이트하거나 페이지 또는 뉴스 게시물을 추가하거나 로컬 디자인 시스템에 맞게 스타일을 조정하는 기능을 제공합니다. 또한 `www/src/pages/`의 라우트 파일을 활용합니다.","es":"Habilita a los agentes para actualizar el contenido, agregar páginas y ajustar el estilo en los sitios de Astro utilizando npm y Astro.glob, siguiendo el sistema de diseño local y aprovechando los archivos de ruta en `www/src/pages/`.","fr":"Permet aux agents de mettre à jour le contenu, d''ajouter des pages et d''ajuster le style sur les sites Astro en utilisant npm et Astro.glob, en suivant le système de conception local et en exploitant les fichiers de route dans `www/src/pages/`.","de":"Ermächtigt die Agenten, den Inhalt zu aktualisieren, Seiten hinzuzufügen und das Layout auf Astro-Seiten mithilfe von npm und Astro.glob anzupassen, während sie das lokale Designsystem befolgen und die Routendateien in `www/src/pages/` nutzen.","pt":"Habilita os agentes a atualizar o conteúdo, adicionar páginas e ajustar a formatação em sites Astro usando npm e Astro.glob, seguindo o sistema de design local e aproveitando arquivos de rota em `www/src/pages/`.","ru":"Наделяет агентов возможностью обновлять контент, добавлять новые страницы и настраивать оформление на сайтах Astro с помощью npm и Astro.glob, следуя локальной системе дизайна и используя файлы маршрутов в `www/src/pages/`.","ar":"يمنح العملاء القدرة على تحديث المحتوى وإضافة صفحات وضبط التخطيط على مواقع Astro باستخدام npm و Astro.glob ، متبعين نظام التصميم المحلي واستخدام ملفات المسار في `www/src/pages/`."},"useCases":{"en":["Updating content on Astro websites","Adding new pages or news posts using `Astro.glob`","Adjusting styling to match the local design system"],"zh":["在 Astro 网站上更新内容","使用 `Astro.glob` 添加新页面或新闻帖子","调整样式以匹配本地设计系统"],"ja":["Astro サイトのコンテンツを更新する","`Astro.glob` を使用して新しいページまたはニュース ポストを追加する","ローカル デザイン システムに合わせてスタイリングを調整する"],"ko":["Astro 웹사이트의 콘텐츠를 업데이트하는 것","`Astro.glob`를 사용하여 새로운 페이지 또는 뉴스 게시물을 추가하는 것","로컬 디자인 시스템에 맞게 스타일을 조정하는 것"],"es":["Actualización de contenido en sitios web de Astro","Agregar nuevas páginas o publicaciones de noticias utilizando `Astro.glob`","Ajuste del estilo para que coincida con el sistema de diseño local"],"fr":["Mise à jour du contenu sur les sites web Astro","Ajout de nouvelles pages ou de publications de nouvelles à l''aide de `Astro.glob`","Ajustement du style pour qu''il corresponde au système de conception local"],"de":["Aktualisieren von Inhalten auf Astro-Websites","Hinzufügen neuer Seiten oder Nachrichtenposts mithilfe von `Astro.glob`","Anpassen des Layouts, um es mit dem lokalen Designsystem zu vereinbaren"],"pt":["Atualizar conteúdo em sites Astro","Adicionar novas páginas ou posts de notícias usando `Astro.glob`","Ajustar a formatação para corresponder ao sistema de design local"],"ru":["Обновление контента на сайтах Astro","Добавление новых страниц или сообщений в блоге с помощью `Astro.glob`","Настройка оформления для соответствия локальной системе дизайна"],"ar":["تحديث المحتوى على مواقع Astro","إضافة صفحات أو منشورات إخبارية جديدة باستخدام `Astro.glob`","ضبط التخطيط لتطابق نظام التصميم المحلي"]},"limitations":{"en":["Requires npm installation","Limited to Astro websites","Dependent on local design system"],"zh":["需要 npm 安装","仅限 Astro 网站","依赖于本地设计系统"],"ja":["npm のインストールが必要","Astro サイトのみに対応","ローカル デザイン システムに依存する"],"ko":["npm 설치가 필요함","Astro 웹사이트만 해당함","로컬 디자인 시스템에 의존함"],"es":["Requiere instalación de npm","Limitado a sitios web de Astro","Dependiente del sistema de diseño local"],"fr":["Nécessite l''installation de npm","Limité aux sites web Astro","Dépendant du système de conception local"],"de":["Erfordert npm-Installation","Begrenzt auf Astro-Websites","Abhängig vom lokalen Designsystem"],"pt":["Requer instalação do npm","Limitado a sites Astro","Dependente do sistema de design local"],"ru":["Требует установки npm","Ограничен для сайтов Astro","Зависит от локальной системы дизайна"],"ar":["يتطلب تثبيت npm","محدود لمواقع Astro","يعتمد على نظام التصميم المحلي"]},"version":4},"contentHash":"f8140c8841faede77fe4e860b89ec9d011409c70163874c98bbfef20224d88ca","qualityScore":23}');
