INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pierrickmartino/blockbuilders.tech.bmad/bmad-editorial-review-prose', 'bmad-editorial-review-prose', 'pierrickmartino', 'blockbuilders.tech.bmad', 'community', 'bmad-editorial-review-prose pierrickmartino blockbuilders.tech.bmad community The bmad-editorial-review-prose skill enables AI agents to read and follow instructions from the editorial-review-prose.xml task file, ensuring precise execution of tasks. This skill benefits developers working with XML-based task files. bmad-editorial-review-prose是一种AIエージェント技能，用于编辑审查，通过阅读项目根目录下的任务文件来完成任务 bmad-editorial-review-proseはAIエージェントのスキルで，編集のレビューに使用され，プロジェクトルートディレクトリのタスクファイルを読み取ることで機能します bmad-editorial-review-prose는 AI 에이전트의 기능으로 편집 검토에 사용되며 프로젝트 루트 디렉토리의 작업 파일을 읽어들이는 방식으로 작동합니다 El skill bmad-editorial-review-prose permite la revisión editorial avanzada en proyectos de IA. Sigue las instrucciones en el archivo de tarea para una configuración exitosa. Le skill bmad-editorial-review-prose permet une révision éditoriale avancée dans les projets d''IA. Suivez les instructions du fichier de tâche pour une configuration réussie. Das Skill bmad-editorial-review-prose ermöglicht eine erweiterte redaktionelle Überprüfung in KI-Projekten. Befolgen Sie die Anweisungen in der Aufgabendatei für eine erfolgreiche Einrichtung. O bmad-editorial-review-prose é uma ferramenta de edição que ajuda a melhorar a eficiência do fluxo de trabalho de edição ИИ Агент bmad-editorial-review-prose - это инструмент редактирования, который помогает оптимизировать редакционный процесс بمد-مراجعة-نثر هو أداة تحرير تساعد على تحسين كفاءة تدفق عمل التحرير how to use bmad-editorial-review-prose bmad-editorial-review-prose setup guide bmad-editorial-review-prose alternative bmad-editorial-review-prose vs xml task managers what is bmad-editorial-review-prose bmad-editorial-review-prose install bmad-editorial-review-prose AIエージェント 编辑审查 内容优化 AI开发 项目管理 任务自动化 开发效率 Reads the entire task file at {project-root}/_bmad/core/tasks/editorial-review-prose.xml Follows all instructions in the task file exactly as written Executes tasks based on XML file format Supports task execution via the _bmad core tasks directory bmad-editorial-review-prose is a skill that allows AI agents to read and execute tasks defined in the editorial-review-prose.xml file located at {project-root}/_bmad/core/tasks/');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aryasoni98/mcpatlas/product-manager', 'community', 'aryasoni98', 'mcpatlas', 'aryasoni98/mcpatlas', 'product-manager', 1, 0, 23, '2026-03-03T12:33:44Z', '2026-03-06T07:18:15.345Z', 'cc798d9a80f0a9186806fe0b3322b5a7c4932eeb20eccfb064679fdbd1327dce', '{"id":"aryasoni98/mcpatlas/product-manager","name":"product-manager","description":{"en":"The product-manager skill applies product thinking to 2,400+ CNCF projects, enabling developers and AI to access structured, real-time data. It benefits developers and AI agents by providing ecosystem intelligence and contributor onboarding paths.","zh":"产品经理AI技能实现10x加速发现、AI增强贡献和全CNCF上下文，解决2400+ CNCF项目的结构化实时访问问题","ja":"Product Manager AIスキルは、10倍速の発見、AI強化貢献、全面的なCNCFコンテキストを実現し、2400以上のCNCFプロジェクトの構造化リアルタイムアクセス問題を解決","ko":"제품 관리자 AI 스킬은 10배 빠른 발견, AI 강화 기여 및 전체 CNCF 컨텍스트를 실현하여 2400개 이상의 CNCF 프로젝트의 구조화된 실시간 액세스 문제를 해결","es":"El product-manager permite un acceso estructurado a más de 2.400 proyectos CNCF, mejorando la descubierta y la colaboración","fr":"Le product-manager permet un accès structuré à plus de 2.400 projets CNCF, améliorant la découverte et la collaboration","de":"Der product-manager ermöglicht einen strukturierten Zugriff auf über 2.400 CNCF-Projekte, verbessert die Entdeckung und die Zusammenarbeit","pt":"O Gerente de Produto é uma habilidade que aplica pensamento de produto para melhorar a descoberta de projetos CNCF","ru":"ИИ Агент «Product Manager» — это навык, который применяет продукт-думание для ускорения обнаружения проектов CNCF","ar":"مدير المنتج هو مهارة تطبق التفكير المنتج لتحسين اكتشاف المشاريع CNCF"},"seo":{"title":{"en":"Product-Manager: AI-Augmented Project Insights | AI Agent...","zh":"产品经理设置指南 - 10x 加速发现和AI增强贡献","ja":"Product Manager セットアップガイド - 10倍速の発見とAI強化貢献","ko":"제품 관리자 설정 가이드 - 10배 빠른 발견 및 AI 강화 기여","es":"Guía de configuración del product-manager para acceso est...","fr":"Guide de mise en place du product-manager pour un accès s...","de":"Einrichtungsleitfaden für product-manager zur strukturier...","pt":"Guia de Configuração do Gerente de Produto para Aumentar ...","ru":"Настройка ИИ Агента «Product Manager» для Ускорения Обнар...","ar":"دليل إعداد مدير المنتج لزيادة اكتشاف 10x مع أدوات الذكاء ..."},"description":{"en":"Unlock 10x faster discovery and AI-driven contributions with the product-manager skill. Explore CNCF project intelligence and more - get started now!","zh":"了解产品经理AI技能，实现10x加速发现、AI增强贡献和全CNCF上下文","ja":"Product Manager AIスキルを使用して、10倍速の発見、AI強化貢献、全面的なCNCFコンテキストを実現","ko":"제품 관리자 AI 스킬을 사용하여 10배 빠른 발견, AI 강화 기여 및 전체 CNCF 컨텍스트를 실현","es":"Mejora la descubierta de proyectos CNCF con el product-manager y accede a inteligencia de ecosistemas y rutas de incorporación de contribuyentes","fr":"Améliorez la découverte de projets CNCF avec le product-manager et accédez à l''intelligence d''écosystème et aux parcours d''intégration des contributeurs","de":"Verbessern Sie die Entdeckung von CNCF-Projekten mit dem product-manager und greifen Sie auf die Ecosystem-Intelligenz und die Einbindungspfade von Mitwirken...","pt":"Aprenda a configurar o Gerente de Produto para melhorar a descoberta de projetos CNCF com acesso estruturado e inteligência de ecossistema","ru":"Узнайте, как настроить ИИ Агента «Product Manager» для ускорения обнаружения проектов CNCF с помощью структурированного доступа и экосистемной разведки","ar":"تعلم كيفية إعداد مدير المنتج لتطوير اكتشاف المشاريع CNCF مع الوصول المنظم والاستخبارات البيئية"},"definition":{"en":"product-manager is a skill that applies product thinking to provide user impact, roadmap alignment, scope, and success metrics for CNCF projects.","zh":"产品经理AI技能是一种实现结构化实时访问、AI增强贡献和全CNCF上下文的技术","ja":"Product Manager AIスキルは、構造化リアルタイムアクセス、AI強化貢献、全面的なCNCFコンテキストを実現する技術","ko":"제품 관리자 AI 스킬은 구조화된 실시간 액세스, AI 강화 기여 및 전체 CNCF 컨텍스트를 실현하는 기술","es":"El product-manager es una habilidad que aplica la forma de pensar del producto para mejorar el acceso a proyectos CNCF","fr":"Le product-manager est une compétence qui applique la pensée produit pour améliorer l''accès aux projets CNCF","de":"Der product-manager ist eine Fähigkeit, die die Produkt-Denke anwendet, um den Zugriff auf CNCF-Projekte zu verbessern","pt":"O que é um Gerente de Produto? É uma habilidade que aplica pensamento de produto para melhorar a descoberta de projetos","ru":"Что такое ИИ Агент «Product Manager»? Это навык, который применяет продукт-думание для ускорения обнаружения проектов","ar":"ما هو مدير المنتج؟ هو مهارة تطبق التفكير المنتج لتحسين اكتشاف المشاريع"},"features":{"en":["Provides 10x faster discovery of CNCF projects","Enables AI-augmented contributions with full CNCF context","Delivers ecosystem intelligence, including trends and health metrics","Offers contributor onboarding paths for streamlined collaboration","Applies product thinking to user impact, roadmap alignment, scope, and success metrics"],"zh":["实现10x加速发现","AI增强贡献","全CNCF上下文","解决2400+ CNCF项目的结构化实时访问问题","提供生态系统智能（趋势、健康）","提供贡献者入门路径"],"ja":["10倍速の発見を実現","AI強化貢献","全面的なCNCFコンテキスト","2400以上のCNCFプロジェクトの構造化リアルタイムアクセス問題を解決","エコシステムインテリジェンス（トレンド、ヘルス）を提供","貢献者入門パスを提供"],"ko":["10배 빠른 발견을 실현","AI 강화 기여","전체 CNCF 컨텍스트","2400개 이상의 CNCF 프로젝트의 구조화된 실시간 액세스 문제를 해결","생태계 인텔리전스（트렌드、헬스）를 제공","기여자 입문 경로를 제공"],"es":["Acceso estructurado a más de 2.400 proyectos CNCF","Descubierta 10 veces más rápida de proyectos","Colaboración mejorada con inteligencia de ecosistemas","Rutas de incorporación de contribuyentes personalizadas","Análisis de tendencias y salud del ecosistema"],"fr":["Accès structuré à plus de 2.400 projets CNCF","Découverte 10 fois plus rapide de projets","Collaboration améliorée avec l''intelligence d''écosystème","Parcours d''intégration des contributeurs personnalisés","Analyse des tendances et de la santé de l''écosystème"],"de":["Strukturierten Zugriff auf über 2.400 CNCF-Projekte","10-mal schnellere Entdeckung von Projekten","Verbesserte Zusammenarbeit mit Ecosystem-Intelligenz","Personalisierte Einbindungspfade von Mitwirkenden","Analyse von Trends und Gesundheit des Ökosystems"],"pt":["Acesso estruturado a 2.400+ projetos CNCF","Descoberta 10x mais rápida com inteligência de ecossistema","Contribuições aumentadas por IA com contexto CNCF completo","Caminhos de onboard de contribuidores","Análise de tendências e saúde do ecossistema"],"ru":["Структурированный доступ к 2.400+ проектам CNCF","Ускорение обнаружения в 10 раз с помощью экосистемной разведки","Улучшение вклада с помощью ИИ и полного контекста CNCF","Пути на борту для участников","Анализ тенденций и здоровья экосистемы"],"ar":["وصول منظم إلى 2.400+ مشروع CNCF","اكتشاف أسرع 10 مرات مع استخبارات البيئية","مساهمات محسنة بواسطة الذكاء الاصطناعي مع سياق CNCF كامل","مسارات على متن للمساهمين","تحليل الاتجاهات وصحّة البيئة"]},"keywords":{"en":["how to use product-manager","what is product-manager","product-manager alternative","product-manager vs roadmap alignment tools","product-manager install guide","product-manager setup for CNCF projects","AI-augmented project management","CNCF project intelligence","product-manager for AI agents"],"zh":["产品经理AI技能","AIエージェント","CNCF项目","结构化实时访问","AI增强贡献","全CNCF上下文","生态系统智能","贡献者入门路径"],"ja":["Product Manager AIスキル","AIエージェント","CNCFプロジェクト","構造化リアルタイムアクセス","AI強化貢献","全面的なCNCFコンテキスト","エコシステムインテリジェンス","貢献者入門パス"],"ko":["제품 관리자 AI 스킬","AI 에이전트","CNCF 프로젝트","구조화된 실시간 액세스","AI 강화 기여","전체 CNCF 컨텍스트","생태계 인텔리전스","기여자 입문 경로"],"es":["product-manager","proyectos CNCF","acceso estructurado","descubierta de proyectos","inteligencia de ecosistemas","colaboración en proyectos","rutas de incorporación de contribuyentes","análisis de tendencias","salud del ecosistema"],"fr":["product-manager","projets CNCF","accès structuré","découverte de projets","intelligence d''écosystème","collaboration sur les projets","parcours d''intégration des contributeurs","analyse des tendances","santé de l''écosystème"],"de":["product-manager","CNCF-Projekte","strukturierter Zugriff","Entdeckung von Projekten","Ecosystem-Intelligenz","Zusammenarbeit an Projekten","Einbindungspfade von Mitwirkenden","Trendanalyse","Gesundheit des Ökosystems"],"pt":["gerente de produto","descoberta de projetos CNCF","inteligência de ecossistema","contribuições aumentadas por IA","onboard de contribuidores","análise de tendências","saúde do ecossistema"],"ru":["ИИ Агент «Product Manager»","обнаружение проектов CNCF","экосистемная разведка","улучшение вклада с помощью ИИ","пути на борту для участников","анализ тенденций","здоровье экосистемы"],"ar":["مدير المنتج","اكتشاف المشاريع CNCF","استخبارات البيئية","مساهمات محسنة بواسطة الذكاء الاصطناعي","مسارات على متن للمساهمين","تحليل الاتجاهات","صحّة البيئة"]}},"owner":"aryasoni98","repo":"mcpatlas","repoPath":"aryasoni98/mcpatlas","stars":1,"forks":0,"updatedAt":"2026-03-03T12:33:44Z","topics":[],"category":"community","skillMd":{"name":"product-manager","description":"Align MCPAtlas work with roadmap, impact, and success metrics. Use when prioritizing features, defining scope, writing roadmap/ROADMAP.md, or discussing user value and CNCF Sandbox positioning.","bodyPreview":"# Product Manager — MCPAtlas\n\nApply product thinking: user impact, roadmap alignment, scope, and success metrics (BluePrint §11, DEEP_PLAN §1, §12–13).\n\n## Problem and impact (keep front of mind)\n\n- **Problem**: 2,400+ CNCF projects; developers and AI lack structured, real-time access. Discovery and cross-project knowledge are fragmented.\n- **Impact**: 10x faster discovery, AI-augmented contributions with full CNCF context, ecosystem intelligence (trends, health), contributor onboarding paths, m","body":"# Product Manager — MCPAtlas\n\nApply product thinking: user impact, roadmap alignment, scope, and success metrics (BluePrint §11, DEEP_PLAN §1, §12–13).\n\n## Problem and impact (keep front of mind)\n\n- **Problem**: 2,400+ CNCF projects; developers and AI lack structured, real-time access. Discovery and cross-project knowledge are fragmented.\n- **Impact**: 10x faster discovery, AI-augmented contributions with full CNCF context, ecosystem intelligence (trends, health), contributor onboarding paths, maturity/health for CNCF governance.\n- **Value prop**: Living, queryable knowledge graph over the landscape via MCP (Anthropic, OpenAI, Google, Microsoft — 97M+ SDK downloads).\n\n## Prioritization\n\n- **Phase 1 (Foundation)**: Core MCP server, search, get_project, compare, resources, STDIO/SSE, Docker, Homebrew, docs. Goal: installable, usable.\n- **Phase 2 (Intelligence)**: Semantic search, health scoring, suggest_stack, find_alternatives, analyze_trends, LLM summaries, Streamable HTTP. Goal: CNCF Sandbox application.\n- **Phase 3 (Extensibility)**: WASM plugins, get_good_first_issues, get_migration_path, K8s operator, contributor automation. Goal: ecosystem and community.\n- **Phase 4 (Scale & maturity)**: Horizontal scaling, Helm, RBAC, audit, SLSA, performance, enterprise features. Goal: production and Incubating prep.\n\nWhen choosing work: close gaps in current phase before jumping; fix tech debt that blocks scaling or security; prefer items that unblock multiple streams (e.g. storage traits unblock SurrealDB and Redis).\n\n## Scope and “out of scope”\n\n- **In scope**: MCP server for CNCF Landscape (tools, resources, prompts), plugin system, data pipeline, deployment (local, Docker, K8s), docs and governance.\n- **Out of scope (for now)**: Writing back to CNCF repos via MCP, real-time event stream, cross-landscape federation (LF AI, OpenSSF), marketplace for premium plugins — treat as later roadmap.\n\n## Success metrics (DEEP_PLAN §13)\n\n| Metric        | 3 mo   | 6 mo    | 12 mo   |\n|---------------|--------|---------|---------|\n| GitHub stars  | 500    | 2,000   | 10,000  |\n| Monthly downloads | 1K | 10K     | 100K    |\n| Contributors  | 5      | 20      | 50+     |\n| MCP tools     | 6      | 10      | 20+     |\n| Plugins       | 0      | 3       | 15+     |\n| CNCF status   | —      | Sandbox | Incubating prep |\n\nUse these when justifying effort or writing ROADMAP.md / ADOPTERS.md.\n\n## Stakeholder and community\n\n- **Users**: Developers and AI agents (Claude, Cursor, VS Code, custom agents). Optimize for “ask and get an answer” latency and correctness.\n- **CNCF**: Sandbox → Incubating path. Governance, CoC, SECURITY.md, CONTRIBUTING.md, maintainers from multiple orgs.\n- **Partners**: IDE/tool integrations (Anthropic, Cursor, VS Code), CNCF TOC. Document integration guides and adoption.\n\nWhen drafting docs or features, state who benefits and how it moves a phase or metric.\n"},"lastSynced":"2026-03-06T07:18:15.345Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor and AutoGPT needing ecosystem intelligence and contributor onboarding paths for 2,400+ CNCF projects.","zh":"适用于像Cursor和AutoGPT这样需要生态系统智能和贡献者入职路径的AI代理，尤其是对于2,400+个CNCF项目。","ja":"CursorやAutoGPTのようなエコシステムの知識とコントリビューターオンボーディングパスを必要とするAIエージェントに適しています。特に2,400以上のCNCFプロジェクトの場合です。","ko":"Cursor와 AutoGPT 같은 생태계 지능과 기여자 온보딩 경로가 필요한 AI 에이전트에게 적합합니다. 특히 2,400개 이상의 CNCF 프로젝트의 경우에요.","es":"Ideal para agentes de IA como Cursor y AutoGPT que necesitan inteligencia de ecosistema y rutas de incorporación de contribuyentes para 2,400+ proyectos de CNCF.","fr":"Idéal pour les agents IA comme Cursor et AutoGPT ayant besoin d''intelligence d''écosystème et de parcours d''intégration des contributeurs pour 2,400+ projets CNCF.","de":"Ideal für KI-Agents wie Cursor und AutoGPT, die Ökosystem-Intelligenz und Beitrittswege für Mitwirkende für 2,400+ CNCF-Projekte benötigen.","pt":"Ideal para Agentes de IA como Cursor e AutoGPT que necessitam de inteligência de ecossistema e caminhos de integração de contribuintes para 2.400+ projetos CNCF.","ru":"Идеально подходит для агентов ИИ, таких как Cursor и AutoGPT, которым необходимы экосистемная интеллект и пути интеграции участников для 2 400+ проектов CNCF.","ar":"مثالي لعمال الإي الأي مثل Cursor و AutoGPT الذين يحتاجون إلى ذكاء النظام البيئي ومسارات دمج المساهمين لأكثر من 2400 مشروع CNCF."},"recommendation":{"en":"Empowers agents to apply product thinking with user impact, roadmap alignment, scope, and success metrics, leveraging BluePrint and DEEP_PLAN protocols to provide structured, real-time data access and AI-augmented contributions.","zh":"赋予代理应用产品思维，结合用户影响、路线图对齐、范围和成功指标，利用BluePrint和DEEP_PLAN协议提供结构化的实时数据访问和AI增强的贡献。","ja":"エージェントに、ユーザーへの影響、ロードマップの整合、範囲、成功指標などを考慮した製品思考を適用する力を与え、BluePrintとDEEP_PLANプロトコルを利用して構造化されたリアルタイムデータアクセスとAI強化された貢献を提供します。","ko":"에이전트가 제품 사고를 적용할 수 있도록 해줍니다. 사용자 영향, 로드맵 정렬, 범위, 성공 지표 등을 고려하여 BluePrint와 DEEP_PLAN 프로토콜을 활용해 구조화된 실시간 데이터 액세스와 AI 강화된 기여를 제공합니다.","es":"Habilita a los agentes a aplicar pensamiento de producto con impacto en el usuario, alineación de hoja de ruta, alcance y métricas de éxito, aprovechando los protocolos BluePrint y DEEP_PLAN para proporcionar acceso a datos estructurados y en tiempo real y contribuciones mejoradas por IA.","fr":"Permet aux agents d''appliquer une pensée de produit avec un impact sur l''utilisateur, une alignement de feuille de route, une portée et des métriques de succès, en exploitant les protocoles BluePrint et DEEP_PLAN pour fournir un accès aux données structurées et en temps réel et des contributions améliorées par l''IA.","de":"Ermöglicht es Agenten, Produktgedanken mit Benutzereinfluss, Roadmap-Abstimmung, Umfang und Erfolgsmetriken anzuwenden, indem sie die BluePrint- und DEEP_PLAN-Protokolle nutzen, um strukturierten, Echtzeit-Datenzugriff und künstlich intelligenten Beitrag zu bieten.","pt":"Habilita os agentes a aplicar pensamento de produto com impacto do usuário, alinhamento da estrada, escopo e métricas de sucesso, utilizando os protocolos BluePrint e DEEP_PLAN para fornecer acesso a dados estruturados em tempo real e contribuições aumentadas por IA.","ru":"Наделяет агентов возможностью применять мышление продукта с учетом воздействия на пользователя, соответствием дорожной карты, объемом и метриками успеха, используя протоколы BluePrint и DEEP_PLAN для предоставления структурированного доступа к данным в реальном времени и вкладов, дополненных ИИ.","ar":"تمكن الوكلاء من تطبيق التفكير في المنتج مع تأثير المستخدم ومواءمة الخريطة الطريقية والنطاق ومقاييس النجاح، مستخدمة بروتوكولات BluePrint و DEEP_PLAN لتوفير وصول بيانات هيكلي في الوقت الفعلي ومساهمات مدعومة بالذكاء الاصطناعي."},"useCases":{"en":["Accelerating discovery of CNCF projects by 10x","Generating contributor onboarding paths with full CNCF context","Analyzing ecosystem intelligence trends and health"],"zh":["加速发现CNCF项目，速度提高10倍","生成具有完整CNCF上下文的贡献者入职路径","分析生态系统智能趋势和健康状况"],"ja":["CNCFプロジェクトの発見を10倍速で加速する","完全なCNCFコンテキストを備えたコントリビューターオンボーディングパスを生成する","エコシステムの知識トレンドとヘルスを分析する"],"ko":["CNCF 프로젝트 발견을 10배 빠르게 가속화하는 것","전체 CNCF 컨텍스트를 갖춘 기여자 온보딩 경로 생성","생태계 지능 트렌드 및 건강 상태 분석"],"es":["Acelerar el descubrimiento de proyectos de CNCF en 10 veces","Generar rutas de incorporación de contribuyentes con contexto completo de CNCF","Analizar tendencias y salud de la inteligencia del ecosistema"],"fr":["Accélérer la découverte de projets CNCF de 10 fois","Générer des parcours d''intégration des contributeurs avec le contexte complet de CNCF","Analyser les tendances et la santé de l''intelligence d''écosystème"],"de":["Entdeckung von CNCF-Projekten um das 10-fache beschleunigen","Erstellung von Beitrittswegen für Mitwirkende mit vollständigem CNCF-Kontext","Analyse von Trends und Gesundheit der Ökosystem-Intelligenz"],"pt":["Acelerar a descoberta de projetos CNCF em 10 vezes","Gerar caminhos de integração de contribuintes com contexto completo CNCF","Analizar tendências e saúde da inteligência do ecossistema"],"ru":["Ускорить открытие проектов CNCF в 10 раз","Генерировать пути интеграции участников с полным контекстом CNCF","Анализировать тенденции и здоровье экосистемной интеллект"],"ar":["تCELER الاكتشاف لمشاريع CNCF 10 مرات","جعل مسارات دمج المساهمين مع السياق الكامل ل CNCF","تحليل الاتجاهات والصحة الذكاء النظام البيئي"]},"limitations":{"en":["Requires access to 2,400+ CNCF projects data","Limited to CNCF ecosystem"],"zh":["需要访问2,400+个CNCF项目的数据","仅限于CNCF生态系统"],"ja":["2,400以上のCNCFプロジェクトのデータにアクセスする必要がある","CNCFエコシステムのみに限定される"],"ko":["2,400개 이상의 CNCF 프로젝트 데이터에 액세스해야 함","CNCF 생태계에만 제한됨"],"es":["Requiere acceso a datos de 2,400+ proyectos de CNCF","Limitado al ecosistema de CNCF"],"fr":["Nécessite un accès aux données de 2,400+ projets CNCF","Limité à l''écosystème CNCF"],"de":["Benötigt Zugriff auf Daten von 2,400+ CNCF-Projekten","Begrenzt auf das CNCF-Ökosystem"],"pt":["Requer acesso a dados de 2.400+ projetos CNCF","Limitado ao ecossistema CNCF"],"ru":["Требует доступа к данным 2 400+ проектов CNCF","Ограничен экосистемой CNCF"],"ar":["يتطلب الوصول إلى بيانات 2400+ مشاريع CNCF","محدود بنظام بيئي CNCF"]},"version":4},"contentHash":"cc798d9a80f0a9186806fe0b3322b5a7c4932eeb20eccfb064679fdbd1327dce","qualityScore":23}');
