INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aryasoni98/mcpatlas/product-manager', 'product-manager', 'aryasoni98', 'mcpatlas', 'community', 'product-manager aryasoni98 mcpatlas community The product-manager skill applies product thinking to 2,400+ CNCF projects, enabling developers and AI to access structured, real-time data. It benefits developers and AI agents by providing ecosystem intelligence and contributor onboarding paths. 产品经理AI技能实现10x加速发现、AI增强贡献和全CNCF上下文，解决2400+ CNCF项目的结构化实时访问问题 Product Manager AIスキルは、10倍速の発見、AI強化貢献、全面的なCNCFコンテキストを実現し、2400以上のCNCFプロジェクトの構造化リアルタイムアクセス問題を解決 제품 관리자 AI 스킬은 10배 빠른 발견, AI 강화 기여 및 전체 CNCF 컨텍스트를 실현하여 2400개 이상의 CNCF 프로젝트의 구조화된 실시간 액세스 문제를 해결 El product-manager permite un acceso estructurado a más de 2.400 proyectos CNCF, mejorando la descubierta y la colaboración Le product-manager permet un accès structuré à plus de 2.400 projets CNCF, améliorant la découverte et la collaboration Der product-manager ermöglicht einen strukturierten Zugriff auf über 2.400 CNCF-Projekte, verbessert die Entdeckung und die Zusammenarbeit O Gerente de Produto é uma habilidade que aplica pensamento de produto para melhorar a descoberta de projetos CNCF ИИ Агент «Product Manager» — это навык, который применяет продукт-думание для ускорения обнаружения проектов CNCF مدير المنتج هو مهارة تطبق التفكير المنتج لتحسين اكتشاف المشاريع CNCF how to use product-manager what is product-manager product-manager alternative product-manager vs roadmap alignment tools product-manager install guide product-manager setup for CNCF projects AI-augmented project management CNCF project intelligence product-manager for AI agents 产品经理AI技能 AIエージェント CNCF项目 结构化实时访问 AI增强贡献 全CNCF上下文 生态系统智能 贡献者入门路径 Provides 10x faster discovery of CNCF projects Enables AI-augmented contributions with full CNCF context Delivers ecosystem intelligence, including trends and health metrics Offers contributor onboarding paths for streamlined collaboration Applies product thinking to user impact, roadmap alignment, scope, and success metrics product-manager is a skill that applies product thinking to provide user impact, roadmap alignment, scope, and success metrics for CNCF projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CleanExpo/DR-NRPG/nrpg-workflow', 'community', 'CleanExpo', 'DR-NRPG', 'CleanExpo/DR-NRPG', 'nrpg-workflow', 1, 0, 23, '2026-03-05T04:35:48Z', '2026-03-06T13:11:44.524Z', '34c770eec5c7a957937a11359840bbe1f361848b2b694c244652c566989460be', '{"id":"CleanExpo/DR-NRPG/nrpg-workflow","name":"nrpg-workflow","description":{"en":"The nrpg-workflow skill provides a secure authentication and multi-tenancy framework for developers, utilizing NextAuth cookie sessions and server-side role checks.","zh":"nrpg-workflow 是一个实现 NextAuth 和多租户的开发框架，确保安全高效的开发","ja":"nrpg-workflow は NextAuth とマルチテナンシーを実現する開発フレームワークであり、セキュアで効率的な開発を保証する","ko":"nrpg-workflow는 NextAuth 및 멀티 테넌시를 구현하는 개발 프레임워크로, 보안 및 효율적인 개발을 보장한다","es":"El flujo de trabajo nrpg es una herramienta que requiere una configuración específica para garantizar la autenticación y privacidad adecuadas","fr":"Le workflow nrpg est un outil qui nécessite une configuration spécifique pour assurer une authentification et une vie privée appropriées","de":"Der nrpg-Workflow ist ein Tool, das eine spezifische Konfiguration erfordert, um eine angemessene Authentifizierung und Privatsphäre zu gewährleisten","pt":"O nrpg-workflow é uma ferramenta que exige atenção especial à autenticação e à multi-tenância. Aqui estão as melhores práticas para implementar essas funcionalidades","ru":"ИИ Агенты nrpg-workflow требуют особого внимания к аутентификации и мультиарендности. Здесь представлены лучшие практики для реализации этих функций","ar":"أداة nrpg-workflow تتطلب اهتمامًا خاصًا بالتوثيق والملكية المتعددة. هنا يتم تقديم أفضل الممارسات لتنفيذ هذه الوظائف"},"seo":{"title":{"en":"nrpg-workflow: Secure Auth and Multi-tenancy Setup Guide ...","zh":"nrpg-workflow Setup Guide: NextAuth 和多租户最佳实践","ja":"nrpg-workflow セットアップガイド: NextAuth とマルチテナンシーにおけるベストプラクティス","ko":"nrpg-workflow 설정 가이드: NextAuth 및 멀티 테넌시 최고 사례","es":"Configuración de nrpg-workflow: Guía de Autenticación y P...","fr":"Mise en place de nrpg-workflow: Guide de l''Authentificati...","de":"Einrichtung von nrpg-workflow: Anleitung für Authentifizi...","pt":"Guia de Configuração nrpg-workflow: Autenticação e Multi-...","ru":"ИИ Агенты nrpg-workflow: Руководство по Настройке Безопас...","ar":"إعداد أداة nrpg-workflow: دليل أفضل الممارسات للأمان"},"description":{"en":"Implement secure authentication and multi-tenancy with nrpg-workflow. Learn how to use NextAuth and server-side role checks for a robust workflow.","zh":"了解 nrpg-workflow 中的 Auth 和多租户规则，实现安全高效的开发，AIエージェント","ja":"nrpg-workflow の Auth とマルチテナンシーのルールをマスターし、セキュアで効率的な開発を実現する、AIエージェント","ko":"nrpg-workflow의 Auth 및 멀티 테넌시 규칙을熟知하고, 보안 및 효율적인 개발을 실현하는 방법, AI 도구","es":"Aprende a implementar nrpg-workflow con NextAuth y protege la privacidad de tus clientes con nuestras mejores prácticas","fr":"Découvrez comment mettre en place nrpg-workflow avec NextAuth et protégez la vie privée de vos clients avec nos meilleures pratiques","de":"Erfahren Sie, wie Sie nrpg-workflow mit NextAuth implementieren und die Privatsphäre Ihrer Kunden mit unseren Best Practices schützen","pt":"Aprenda a implementar a autenticação e a multi-tenância corretamente no nrpg-workflow, com dicas e melhores práticas para desenvolvedores","ru":"Узнайте, как правильно реализовать аутентификацию и мультиарендность в nrpg-workflow, с советами и лучшими практиками для разработчиков","ar":"تعرف على كيفية تنفيذ التوثيق والملكية المتعددة بشكل صحيح في nrpg-workflow، مع نصائح وأفضل الممارسات للمطورين"},"definition":{"en":"nrpg-workflow is a technical framework that implements secure authentication and multi-tenancy rules for web UI flows and API routes.","zh":"nrpg-workflow 是一个开发框架，用于实现 NextAuth 和多租户的安全高效开发","ja":"nrpg-workflow は、NextAuth とマルチテナンシーのセキュアで効率的な開発を実現する開発フレームワークである","ko":"nrpg-workflow는 NextAuth 및 멀티 테넌시의 보안 및 효율적인 개발을 실현하는 개발 프레임워크이다","es":"nrpg-workflow es un flujo de trabajo que utiliza NextAuth para la autenticación y sigue reglas estrictas para proteger la privacidad","fr":"Le workflow nrpg est un flux de travail qui utilise NextAuth pour l''authentification et suit des règles strictes pour protéger la vie privée","de":"Der nrpg-Workflow ist ein Arbeitsablauf, der NextAuth für die Authentifizierung verwendet und strenge Regeln befolgt, um die Privatsphäre zu schützen","pt":"O nrpg-workflow é uma ferramenta que fornece funcionalidades de autenticação e multi-tenância para aplicações web","ru":"ИИ Агенты nrpg-workflow - это инструмент, который предоставляет функции аутентификации и мультиарендности для веб-приложений","ar":"أداة nrpg-workflow هي أداة توفر وظائف التوثيق والملكية المتعددة للتطبيقات.Web"},"features":{"en":["Uses NextAuth cookie sessions for secure web UI flows","Implements server-side role checks via getServerSession(authOptions)","Supports Authorization: Bearer tokens for non-browser clients","Enforces multi-tenancy and privacy rules to protect contractor identities","Prevents clients from browsing or searching contractor information"],"zh":["使用 NextAuth cookie 会话实现 Web UI 流程","在 API 路由中使用 getServerSession(authOptions) 和服务端角色检查","实现多租户和隐私保护，防止客户端浏览或搜索承包商身份","仅在非浏览器客户端需要时允许 Authorization: Bearer tokens"],"ja":["NextAuth Cookie セッションを使用して Web UI フローを実現","API ルートで getServerSession(authOptions) とサーバーサイド ロール チェックを使用","マルチテナンシーとプライバシー保護を実現し、クライアントが請負業者 ID を参照できないようにする","ブラウザ以外のクライアントでのみ Authorization: Bearer トークンを許可"],"ko":["NextAuth 쿠키 세션을 사용하여 Web UI 흐름을 구현","API 路由에서 getServerSession(authOptions) 및 서버 측 역할 확인을 사용","멀티 테넌시 및 개인 정보 보호를 구현하여 클라이언트가 계약자 ID를 참조할 수 없도록 함","브라우저 이외의 클라이언트에서만 Authorization: Bearer 토큰 허용"],"es":["Autenticación con NextAuth","Uso de getServerSession para comprobar roles en el servidor","Protección de la privacidad de los clientes","Compatibilidad con API routes y clientes no navegador","Uso de Authorization: Bearer para clientes no navegador"],"fr":["Authentification avec NextAuth","Utilisation de getServerSession pour vérifier les rôles sur le serveur","Protection de la vie privée des clients","Compatibilité avec les routes API et les clients non navigateur","Utilisation de Authorization: Bearer pour les clients non navigateur"],"de":["Authentifizierung mit NextAuth","Verwendung von getServerSession für Rollenprüfung auf dem Server","Schutz der Privatsphäre der Kunden","Kompatibilität mit API-Routen und nicht-Browser-Clients","Verwendung von Authorization: Bearer für nicht-Browser-Clients"],"pt":["Uso de NextAuth cookie sessions para fluxos de UI da web","Verificação de papéis no lado do servidor com getServerSession(authOptions)","Suporte à autenticação com Authorization: Bearer para clientes não navegadores","Proteção da identidade dos contratantes contra exposição aos clientes","Implementação de multi-tenância com privacidade e segurança"],"ru":["Использование NextAuth cookie sessions для веб-интерфейса","Проверка ролей на стороне сервера с getServerSession(authOptions)","Поддержка аутентификации с Authorization: Bearer для не-браузерных клиентов","Защита идентификаторов контрактов от раскрытия клиентам","Реализация мультиарендности с приватностью и безопасностью"],"ar":["استخدام NextAuth cookie sessions لتدفقات واجهة المستخدم على الويب","التحقق من أدوار الخادم مع getServerSession(authOptions)","دعم التوثيق مع Authorization: Bearer لآلياء غير متصفحات","حماية هوية المقاولين من الكشف عنها للعملاء","تنفيذ الملكية المتعددة مع الخصوصية والأمان"]},"keywords":{"en":["how to use nrpg-workflow","nrpg-workflow setup guide","nrpg-workflow alternative","nrpg-workflow vs NextAuth","implementing multi-tenancy with nrpg-workflow","nrpg-workflow install","secure authentication with nrpg-workflow"],"zh":["nrpg-workflow","NextAuth","多租户","隐私保护","AIエージェント","开发框架","安全开发","高效开发"],"ja":["nrpg-workflow","NextAuth","マルチテナンシー","プライバシー保護","AIエージェント","開発フレームワーク","セキュア開発","効率的な開発"],"ko":["nrpg-workflow","NextAuth","멀티 테넌시","개인 정보 보호","AI 도구","개발 프레임워크","보안 개발","효율적인 개발"],"es":["nrpg-workflow","NextAuth","autenticación","privacidad","API routes","clientes no navegador","Authorization Bearer","seguridad","desarrollo web"],"fr":["nrpg-workflow","NextAuth","authentification","vie privée","routes API","clients non navigateur","Authorization Bearer","sécurité","développement web"],"de":["nrpg-workflow","NextAuth","Authentifizierung","Privatsphäre","API-Routen","nicht-Browser-Clients","Authorization Bearer","Sicherheit","Webentwicklung"],"pt":["nrpg-workflow","autenticação","multi-tenância","NextAuth","getServerSession","Authorization Bearer","segurança","privacidade"],"ru":["ИИ Агенты nrpg-workflow","аутентификация","мультиарендность","NextAuth","getServerSession","Authorization Bearer","безопасность","приватность"],"ar":["أداة nrpg-workflow","التوثيق","الملكية المتعددة","NextAuth","getServerSession","التوثيق مع Authorization Bearer","الأمان","الخصوصية"]}},"owner":"CleanExpo","repo":"DR-NRPG","repoPath":"CleanExpo/DR-NRPG","stars":1,"forks":0,"updatedAt":"2026-03-05T04:35:48Z","topics":[],"category":"community","skillMd":{"name":"nrpg-workflow","description":"Use when working on NRPG Platform tasks to follow repo conventions (NextAuth cookie sessions, tenant safety, and contractor privacy) and to run the correct checks.","bodyPreview":"Follow these rules when implementing changes in this repository:\n\n## Auth (critical)\n\n- Use NextAuth cookie sessions for web UI flows.\n- Do not use `localStorage` tokens for auth in the UI.\n- In API routes, prefer `getServerSession(authOptions)` and server-side role checks.\n- Only allow `Authorization: Bearer ...` when explicitly required for non-browser clients.\n\n## Multi-tenancy & privacy (critical)\n\n- Never expose contractor identities to clients.\n- Clients must not be able to browse/search c","body":"Follow these rules when implementing changes in this repository:\n\n## Auth (critical)\n\n- Use NextAuth cookie sessions for web UI flows.\n- Do not use `localStorage` tokens for auth in the UI.\n- In API routes, prefer `getServerSession(authOptions)` and server-side role checks.\n- Only allow `Authorization: Bearer ...` when explicitly required for non-browser clients.\n\n## Multi-tenancy & privacy (critical)\n\n- Never expose contractor identities to clients.\n- Clients must not be able to browse/search contractors or contact them directly.\n- Enforce role-based access for any contractor profile endpoints/pages.\n\n## Implementation workflow\n\n1. Scan for auth-token usage (`localStorage`, `Authorization: Bearer`) and remove/limit as required.\n2. Verify server-side auth checks in any modified `app/api/**/route.ts`.\n3. Run targeted checks for the area changed:\n   - `npm run lint`\n   - `npm test`\n   - `npm run build`\n4. Fix failures only if they are related to the change being made.\n\n"},"lastSynced":"2026-03-06T13:11:44.524Z","agentAnalysis":{"suitability":{"en":"Ideal for Security-focused Agents requiring robust authentication and multi-tenancy capabilities.","zh":"适合需要强大的身份验证和多租户功能的安全专注代理。","ja":"セキュリティに重点を置くエージェントが強力な認証とマルチテナンシー機能を必要とする場合に最適です。","ko":"보안에 중점을 둔 에이전트가 강력한 인증 및 멀티 테넌시 기능을 필요로 할 경우 적합합니다.","es":"Ideal para agentes de seguridad que requieren autenticación robusta y capacidades de multi-tenencia.","fr":"Idéal pour les agents axés sur la sécurité nécessitant une authentification robuste et des capacités de multi-locataires.","de":"Ideal für sicherheitsorientierte Agenten, die eine robuste Authentifizierung und Multi-Tenancy-Funktionen erfordern.","pt":"Ideal para Agentes com foco em Segurança que exigem autenticação robusta e capacidades de multi-locatários.","ru":"Идеально для агентов, ориентированных на безопасность, требующих надежной аутентификации и возможностей многоарендаторности.","ar":"مثالي للوكلاء المعنيين بالأمان الذين يحتاجون إلى مصادقة قوية وقدرات متعددة المستأجرين."},"recommendation":{"en":"Empowers agents to implement secure authentication using NextAuth cookie sessions and server-side role checks, ensuring enhanced privacy and access control through multi-tenancy frameworks, specifically utilizing Authorization: Bearer for non-browser clients.","zh":"赋予代理实现使用NextAuth cookie会话和服务器端角色检查的安全身份验证，确保通过多租户框架增强隐私和访问控制，特别是利用Authorization: Bearer用于非浏览器客户端。","ja":"エージェントがNextAuthクッキーセッションとサーバーサイドのロールチェックを使用してセキュアな認証を実装できるようにし、特にAuthorization: Bearerを使用して非ブラウザクライアントに対して、マルチテナンシーフレームワークを介してプライバシーとアクセス制御を強化します。","ko":"에이전트가 NextAuth 쿠키 세션 및 서버 측 역할 확인을 사용하여 보안 인증을 구현할 수 있도록 하여, 특히 Authorization: Bearer를 사용하여 비 브라우저 클라이언트에 대해 멀티 테넌시 프레임 워크를 통해 개인 정보 및 액세스 제어를 향상시킵니다.","es":"Habilita a los agentes a implementar una autenticación segura utilizando sesiones de cookies NextAuth y verificaciones de roles en el servidor, garantizando una privacidad y un control de acceso mejorados a través de frameworks de multi-tenencia, específicamente utilizando Authorization: Bearer para clientes no basados en navegador.","fr":"Permet aux agents de mettre en œuvre une authentification sécurisée en utilisant des sessions de cookies NextAuth et des vérifications de rôles côté serveur, garantissant une confidentialité et un contrôle d''accès améliorés grâce à des frameworks de multi-locataires, en utilisant spécifiquement l''autorisation : Bearer pour les clients non basés sur navigateur.","de":"Ermächtigt Agenten, eine sichere Authentifizierung mithilfe von NextAuth-Cookiesitzungen und serverseitigen Rollenprüfungen zu implementieren, wodurch ein verbesserter Datenschutz und Zugriffsschutz durch Multi-Tenancy-Frameworks gewährleistet wird, insbesondere durch die Verwendung von Authorization: Bearer für nicht browserbasierte Clients.","pt":"Habilita os agentes a implementar autenticação segura usando sessões de cookies NextAuth e verificações de funções no lado do servidor, garantindo privacidade e controle de acesso aprimorados por meio de estruturas de multi-locatários, utilizando especificamente Autorização: Bearer para clientes não navegador.","ru":"Наделяет агентов возможностью реализовать безопасную аутентификацию с использованием сессий cookie NextAuth и проверок ролей на стороне сервера, обеспечивая повышенную конфиденциальность и контроль доступа через фреймворки многоарендаторности, в частности, используя Авторизацию: Bearer для клиентов, не являющихся браузерами.","ar":"تمكّن الوكلاء من تنفيذ مصادقة أمنية باستخدام جلسات كعكات NextAuth والتحقق من أدوار الجانب الخلفي، مما يضمن خصوصية وم 制御 وصول محسّن من خلال إطارات متعددة المستأجرين، باستخدام بشكل خاص ترخيص: حامل لزبائن غير متصفح."},"useCases":{"en":["Implementing secure web UI flows with NextAuth","Enforcing server-side role checks for API routes","Protecting contractor identities through strict access controls"],"zh":["使用NextAuth实现安全的Web UI流程","执行服务器端角色检查用于API路由","通过严格的访问控制保护合同人员的身份"],"ja":["NextAuthを使用してセキュアなWeb UIフローを実装する","APIルートに対するサーバーサイドのロールチェックを実施する","厳格なアクセス制御を通じて契約者のアイデンティティを保護する"],"ko":["NextAuth를 사용하여 보안 웹 UI 흐름을 구현하는 것","API 루트에 대한 서버 측 역할 확인을 시행하는 것","严格한 접근 제어를 통해 계약자의 身分을 보호하는 것"],"es":["Implementar flujos de interfaz de usuario web seguros con NextAuth","Aplicar verificaciones de roles en el servidor para rutas de API","Proteger las identidades de los contratistas a través de controles de acceso estrictos"],"fr":["Mettre en œuvre des flux d''interface utilisateur web sécurisés avec NextAuth","Forcer les vérifications de rôles côté serveur pour les routes API","Protéger les identités des contractants grâce à des contrôles d''accès stricts"],"de":["Implementierung sicherer Web-Benutzeroberflächen-Flows mit NextAuth","Durchsetzen von serverseitigen Rollenprüfungen für API-Routen","Schutz der Identitäten von Vertragspartnern durch strenge Zugriffskontrollen"],"pt":["Implementar fluxos de interface de usuário da web seguros com NextAuth","Aplicar verificações de funções no lado do servidor para rotas da API","Proteger identidades de contratantes por meio de controles de acesso rigorosos"],"ru":["Реализация безопасных веб-интерфейсов с помощью NextAuth","Применение проверок ролей на стороне сервера для маршрутов API","Защита идентификаторов подрядчиков посредством строгих контролей доступа"],"ar":["تنفيذ تدفقات واجهة المستخدم الويب الآمنة مع NextAuth","تنفيذ التحقق من الأدوار الجانب الخلفي لطرق API","حماية هوية المقاولين من خلال ضوابط وصول صارمة"]},"limitations":{"en":["Requires NextAuth setup for cookie sessions","Must adhere to specific auth and multi-tenancy rules","Limited to server-side implementations for role checks"],"zh":["需要NextAuth设置用于cookie会话","必须遵守特定的认证和多租户规则","仅限服务器端实现用于角色检查"],"ja":["NextAuthの設定がクッキーセッションに必要","特定の認証とマルチテナンシーのルールに従う必要がある","ロールチェックの実装はサーバーサイドに限定される"],"ko":["NextAuth 설정이 쿠키 세션에 필요함","특정 인증 및 멀티 테넌시 규칙을 따라야 함","역할 확인의 구현은 서버 측에만 제한됨"],"es":["Requiere configuración de NextAuth para sesiones de cookies","Debe adherirse a reglas de autenticación y multi-tenencia específicas","Limitado a implementaciones en el servidor para verificaciones de roles"],"fr":["Nécessite une configuration NextAuth pour les sessions de cookies","Doit respecter des règles d''authentification et de multi-locataires spécifiques","Limité aux implémentations côté serveur pour les vérifications de rôles"],"de":["Benötigt NextAuth-Konfiguration für Cookiesitzungen","Muss bestimmten Authentifizierungs- und Multi-Tenancy-Regeln entsprechen","Begrenzt auf serverseitige Implementierungen für Rollenprüfungen"],"pt":["Exige configuração do NextAuth para sessões de cookies","Deve aderir a regras específicas de autenticação e multi-locatários","Limitado a implementações no lado do servidor para verificações de funções"],"ru":["Требует настройки NextAuth для сессий cookie","Должно придерживаться определенных правил аутентификации и многоарендаторности","Ограничен реализациями на стороне сервера для проверок ролей"],"ar":["يتطلب إعداد NextAuth لجلسات الكعكات","يجب الالتزام بقواعد مصادقة ومتعددة المستأجرين محددة","محدود بالتنفيذات الجانب الخلفي للتحقق من الأدوار"]},"version":4},"contentHash":"34c770eec5c7a957937a11359840bbe1f361848b2b694c244652c566989460be","qualityScore":23}');
