INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CleanExpo/DR-NRPG/nrpg-workflow', 'nrpg-workflow', 'CleanExpo', 'DR-NRPG', 'community', 'nrpg-workflow CleanExpo DR-NRPG community The nrpg-workflow skill provides a secure authentication and multi-tenancy framework for developers, utilizing NextAuth cookie sessions and server-side role checks. nrpg-workflow 是一个实现 NextAuth 和多租户的开发框架，确保安全高效的开发 nrpg-workflow は NextAuth とマルチテナンシーを実現する開発フレームワークであり、セキュアで効率的な開発を保証する nrpg-workflow는 NextAuth 및 멀티 테넌시를 구현하는 개발 프레임워크로, 보안 및 효율적인 개발을 보장한다 El flujo de trabajo nrpg es una herramienta que requiere una configuración específica para garantizar la autenticación y privacidad adecuadas Le workflow nrpg est un outil qui nécessite une configuration spécifique pour assurer une authentification et une vie privée appropriées Der nrpg-Workflow ist ein Tool, das eine spezifische Konfiguration erfordert, um eine angemessene Authentifizierung und Privatsphäre zu gewährleisten O nrpg-workflow é uma ferramenta que exige atenção especial à autenticação e à multi-tenância. Aqui estão as melhores práticas para implementar essas funcionalidades ИИ Агенты nrpg-workflow требуют особого внимания к аутентификации и мультиарендности. Здесь представлены лучшие практики для реализации этих функций أداة nrpg-workflow تتطلب اهتمامًا خاصًا بالتوثيق والملكية المتعددة. هنا يتم تقديم أفضل الممارسات لتنفيذ هذه الوظائف how to use nrpg-workflow nrpg-workflow setup guide nrpg-workflow alternative nrpg-workflow vs NextAuth implementing multi-tenancy with nrpg-workflow nrpg-workflow install secure authentication with nrpg-workflow nrpg-workflow NextAuth 多租户 隐私保护 AIエージェント 开发框架 安全开发 高效开发 Uses NextAuth cookie sessions for secure web UI flows Implements server-side role checks via getServerSession(authOptions) Supports Authorization: Bearer tokens for non-browser clients Enforces multi-tenancy and privacy rules to protect contractor identities Prevents clients from browsing or searching contractor information nrpg-workflow is a technical framework that implements secure authentication and multi-tenancy rules for web UI flows and API routes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OpenPeopleStudio/open_people/lisa', 'community', 'OpenPeopleStudio', 'open_people', 'OpenPeopleStudio/open_people', 'lisa', 1, 0, 23, '2026-02-18T04:57:31Z', '2026-03-06T13:12:43.682Z', 'a783c48a5fc8007e5b0acd9bc6f30508ac3d4ecacfc8e60a660fc626249e4705', '{"id":"OpenPeopleStudio/open_people/lisa","name":"lisa","description":{"en":"Lisa delivers bold UI and UX updates for OpenPeople.ai''s commerce infrastructure, helping retail brands achieve their product vision. It streamlines the design process for developers.","zh":"Lisa AI工具提供了UI和UX更新的技术解决方案，包括页面、流程和组件的优化","ja":"Lisa AIエージェントは、ページ、フロー、コンポーネントの最適化を含むUIとUXの更新の技術的な解決策を提供します","ko":"Lisa AI 에이전트는 페이지, 흐름, 구성 요소의 최적화를 포함한 UI 및 UX 업데이트의 기술적 해결책을 제공합니다","es":"Lisa es una infraestructura de comercio de IA que ofrece actualizaciones de IU y UX audaces e intencionadas para mejorar la experiencia del usuario","fr":"Lisa est une infrastructure de commerce IA qui propose des mises à jour IU et UX audacieuses et intentionnelles pour améliorer l''expérience utilisateur","de":"Lisa ist eine KI-Handelsinfrastruktur, die kühne und beabsichtigte IU- und UX-Updates bietet, um die Benutzeroberfläche zu verbessern","pt":"A Lisa é uma infraestrutura de comércio inteligente que permite atualizações de UI e UX ousadas e intencionais. Ela é projetada para marcas de varejo ambiciosas","ru":"ИИ Агент Lisa - это интеллектуальная инфраструктура электронной коммерции, которая позволяет выполнять смелые и намеренные обновления UI и UX","ar":"ليزا هي بنية تجارة ذكية تتيح تحديثات واجهة المستخدم وواجهة المستخدم最終ة وجريئة. وهي مصممة لالعلامات التجارية المتعطشة للتجارة الإلكترونية"},"seo":{"title":{"en":"Lisa: UI/UX Updates for Commerce Infrastructure | AI Agen...","zh":"Lisa AI工具集成指南","ja":"Lisa AIエージェント設定ガイド","ko":"Lisa AI 에이전트 구현 가이드","es":"Guía de configuración de Lisa: Infraestructura 