INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OpenPeopleStudio/open_people/lisa', 'lisa', 'OpenPeopleStudio', 'open_people', 'community', 'lisa OpenPeopleStudio open_people community Lisa delivers bold UI and UX updates for OpenPeople.ai''s commerce infrastructure, helping retail brands achieve their product vision. It streamlines the design process for developers. Lisa AI工具提供了UI和UX更新的技术解决方案，包括页面、流程和组件的优化 Lisa AIエージェントは、ページ、フロー、コンポーネントの最適化を含むUIとUXの更新の技術的な解決策を提供します Lisa AI 에이전트는 페이지, 흐름, 구성 요소의 최적화를 포함한 UI 및 UX 업데이트의 기술적 해결책을 제공합니다 Lisa es una infraestructura de comercio de IA que ofrece actualizaciones de IU y UX audaces e intencionadas para mejorar la experiencia del usuario Lisa est une infrastructure de commerce IA qui propose des mises à jour IU et UX audacieuses et intentionnelles pour améliorer l''expérience utilisateur Lisa ist eine KI-Handelsinfrastruktur, die kühne und beabsichtigte IU- und UX-Updates bietet, um die Benutzeroberfläche zu verbessern A Lisa é uma infraestrutura de comércio inteligente que permite atualizações de UI e UX ousadas e intencionais. Ela é projetada para marcas de varejo ambiciosas ИИ Агент Lisa - это интеллектуальная инфраструктура электронной коммерции, которая позволяет выполнять смелые и намеренные обновления UI и UX ليزا هي بنية تجارة ذكية تتيح تحديثات واجهة المستخدم وواجهة المستخدم最終ة وجريئة. وهي مصممة لالعلامات التجارية المتعطشة للتجارة الإلكترونية how to use lisa lisa setup guide lisa alternative lisa vs commerce infrastructure tools what is lisa lisa install for retail brands lisa ui/ux updates lisa for OpenPeople.ai lisa design improvements Lisa AI工具 UI/UX更新 页面优化 流程优化 组件优化 技术解决方案 Layout更新 typography更新 motion更新 Identifies pages, flows, or components to improve using existing patterns in components/ and app/ Proposes distinct visual directions and typography for design updates Defines color tokens for consistent design changes Applies layout, typography, and motion updates for improved UI/UX Ensures mobile and desktop layout consistency Lisa is an AI-powered tool for intentional UI and UX updates, aligning design improvements with product vision for commerce infrastructure.');
